-- Aprenda se Divertindo · 2/4 · Questões 0 a 699
-- Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":0,"materia":"port","nivel":2,"enunciado":"Complete conforme a norma-padrão: “Não sei ___ ele faltou à prova.”","opcoes":["por que","porque","porquê","por quê"],"explicacao":"“Por que” separado e sem acento equivale a “o motivo pelo qual”: “não sei o motivo pelo qual ele faltou”."},{"id":1,"materia":"port","nivel":2,"enunciado":"Qual frase está correta quanto à concordância verbal?","opcoes":["Faz cinco anos que me formei.","Fazem cinco anos que me formei.","Haviam muitos candidatos na sala.","Houveram vários problemas na prova."],"explicacao":"“Fazer” indicando tempo decorrido e “haver” no sentido de existir são impessoais e ficam no singular."},{"id":2,"materia":"port","nivel":2,"enunciado":"Pela norma-padrão, qual frase está correta?","opcoes":["Assisti ao filme ontem.","Assisti o filme ontem.","Prefiro mais cinema do que teatro.","Obedeça o regulamento."],"explicacao":"“Assistir” no sentido de ver pede preposição “a”. “Preferir” rege “a” (prefiro cinema a teatro) e “obedecer” também (obedeça ao regulamento)."},{"id":3,"materia":"port","nivel":2,"enunciado":"Qual frase respeita a colocação pronominal da norma-padrão?","opcoes":["Não me disseram nada.","Não disseram-me nada.","Tinha falado-me a verdade.","Me disseram a verdade."],"explicacao":"Palavra negativa atrai o pronome (próclise). Não se usa ênclise em particípio e, na norma culta, não se inicia frase com pronome oblíquo átono."},{"id":4,"materia":"port","nivel":2,"enunciado":"Em “Passei a tarde lendo Machado de Assis”, que figura de linguagem aparece?","opcoes":["Metonímia","Metáfora","Hipérbole","Ironia"],"explicacao":"Trocar a obra pelo autor é um caso clássico de metonímia."},{"id":5,"materia":"port","nivel":2,"enunciado":"Complete: “O réu se comportou ___ durante a audiência.”","opcoes":["mal","mau","mais","más"],"explicacao":"“Mal” é advérbio, oposto de “bem”. “Mau” é adjetivo, oposto de “bom”. Como se diz “comportou-se bem”, usa-se “mal”."},{"id":6,"materia":"const","nivel":2,"enunciado":"Qual princípio foi acrescentado ao art. 37 da Constituição pela EC nº 19/1998?","opcoes":["Eficiência","Moralidade","Legalidade","Publicidade"],"explicacao":"A Reforma Administrativa (EC 19/1998) incluiu a eficiência no caput do art. 37."},{"id":7,"materia":"const","nivel":2,"enunciado":"O habeas data serve para:","opcoes":["Conhecer ou corrigir dados do próprio impetrante em registros públicos","Proteger direito líquido e certo não amparado por habeas corpus","Anular ato lesivo ao patrimônio público ou ao meio ambiente","Suprir a falta de norma regulamentadora de um direito"],"explicacao":"Art. 5º, LXXII. As outras alternativas descrevem mandado de segurança, ação popular e mandado de injunção."},{"id":8,"materia":"const","nivel":2,"enunciado":"Cada estado elege, na Câmara dos Deputados, no mínimo e no máximo:","opcoes":["8 e 70 deputados","3 e 80 deputados","10 e 60 deputados","4 e 70 deputados"],"explicacao":"Art. 45, § 1º: nenhuma unidade da Federação terá menos de oito ou mais de setenta Deputados."},{"id":9,"materia":"const","nivel":2,"enunciado":"O projeto de lei federal de iniciativa popular exige assinatura de, no mínimo:","opcoes":["1% do eleitorado nacional","5% do eleitorado nacional","0,3% do eleitorado nacional","2% do eleitorado nacional"],"explicacao":"Art. 61, § 2º: 1% do eleitorado nacional, distribuído por pelo menos cinco estados, com no mínimo 0,3% dos eleitores de cada um."},{"id":10,"materia":"const","nivel":2,"enunciado":"Quem julga o Presidente da República nos crimes de responsabilidade?","opcoes":["O Senado Federal","O Supremo Tribunal Federal","A Câmara dos Deputados","O Superior Tribunal de Justiça"],"explicacao":"A Câmara autoriza (art. 51, I) e o Senado processa e julga (art. 52, I). Nos crimes comuns, o julgamento é do STF."},{"id":11,"materia":"adm","nivel":2,"enunciado":"Qual atributo permite à Administração executar suas decisões sem precisar de autorização prévia do Judiciário?","opcoes":["Autoexecutoriedade","Imperatividade","Tipicidade","Presunção de legitimidade"],"explicacao":"Autoexecutoriedade é a execução direta pela própria Administração. Imperatividade é impor obrigações independentemente da concordância do particular."},{"id":12,"materia":"adm","nivel":2,"enunciado":"A revogação de um ato administrativo ocorre por motivo de:","opcoes":["Conveniência e oportunidade","Ilegalidade","Vício de forma","Decisão judicial obrigatória"],"explicacao":"Revoga-se ato válido por conveniência e oportunidade, com efeitos para o futuro (ex nunc). Ato ilegal é anulado."},{"id":13,"materia":"adm","nivel":2,"enunciado":"A vigilância sanitária interdita um restaurante sem higiene. Isso é exercício do poder:","opcoes":["De polícia","Hierárquico","Disciplinar","Regulamentar"],"explicacao":"Poder de polícia é a limitação de direitos individuais em favor do interesse público."},{"id":14,"materia":"adm","nivel":2,"enunciado":"A responsabilidade civil do Estado por danos causados por seus agentes a terceiros é, em regra:","opcoes":["Objetiva, baseada no risco administrativo","Subjetiva, exigindo prova de culpa","Inexistente","Integral, sem nenhuma excludente"],"explicacao":"Art. 37, § 6º. Basta provar conduta, dano e nexo causal. O Estado pode alegar excludentes, como culpa exclusiva da vítima."},{"id":15,"materia":"pen","nivel":2,"enunciado":"Qual destas NÃO é causa de exclusão da ilicitude prevista no art. 23 do Código Penal?","opcoes":["Coação moral irresistível","Legítima defesa","Estado de necessidade","Estrito cumprimento do dever legal"],"explicacao":"Art. 23: estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito. A coação moral irresistível exclui a culpabilidade (art. 22)."},{"id":16,"materia":"pen","nivel":2,"enunciado":"Qual a diferença essencial entre roubo e furto?","opcoes":["No roubo há violência ou grave ameaça à pessoa","No roubo o bem é imóvel","No furto há uso de arma","No furto a vítima é servidor público"],"explicacao":"Os dois envolvem subtração de coisa alheia móvel. O roubo exige violência ou grave ameaça à pessoa."},{"id":17,"materia":"pen","nivel":2,"enunciado":"O servidor que EXIGE vantagem indevida em razão da função comete:","opcoes":["Concussão","Corrupção passiva","Peculato","Prevaricação"],"explicacao":"Exigir é concussão (art. 316). Solicitar ou receber é corrupção passiva (art. 317). Apropriar-se é peculato. Retardar ato por interesse pessoal é prevaricação."},{"id":18,"materia":"pen","nivel":2,"enunciado":"Na tentativa, salvo disposição em contrário, a pena é:","opcoes":["Diminuída de um a dois terços","Igual à do crime consumado","Diminuída pela metade","Aumentada de um terço"],"explicacao":"Art. 14, parágrafo único, do CP."},{"id":19,"materia":"ppen","nivel":2,"enunciado":"Com o indiciado preso, o inquérito policial deve terminar em:","opcoes":["10 dias","30 dias","15 dias","5 dias"],"explicacao":"Art. 10 do CPP: 10 dias se preso; 30 dias se solto."},{"id":20,"materia":"ppen","nivel":2,"enunciado":"Segundo o CPP, diante de alguém em flagrante delito, qualquer pessoa do povo:","opcoes":["Poderá prendê-lo","Deverá prendê-lo","Só pode prendê-lo com ordem judicial","Não pode prendê-lo"],"explicacao":"Art. 301: qualquer do povo PODERÁ (flagrante facultativo) e as autoridades policiais DEVERÃO (flagrante obrigatório) prender quem esteja em flagrante."},{"id":21,"materia":"ppen","nivel":2,"enunciado":"A autoridade policial pode mandar arquivar autos de inquérito?","opcoes":["Não, nunca","Sim, se não houver indícios","Sim, com autorização do ofendido","Sim, nos crimes de menor potencial ofensivo"],"explicacao":"Art. 17 do CPP: a autoridade policial não poderá mandar arquivar autos de inquérito."},{"id":22,"materia":"ppen","nivel":2,"enunciado":"Em quanto tempo o preso em flagrante deve ser apresentado na audiência de custódia?","opcoes":["Até 24 horas","Até 48 horas","Até 72 horas","Até 5 dias"],"explicacao":"Art. 310 do CPP, com redação do Pacote Anticrime: até 24 horas após a realização da prisão."},{"id":23,"materia":"inf","nivel":2,"enunciado":"Como se chama o malware que criptografa os arquivos e exige pagamento de resgate?","opcoes":["Ransomware","Spyware","Worm","Adware"],"explicacao":"Ransomware “sequestra” os dados. Spyware espiona, worm se espalha sozinho pela rede e adware exibe propaganda."},{"id":24,"materia":"inf","nivel":2,"enunciado":"No Excel, a fórmula =SE(A1>10;“Alto”;“Baixo”) retorna “Baixo” quando A1 vale:","opcoes":["10","11","15","20"],"explicacao":"10 não é maior que 10, então o teste é falso e a função retorna o terceiro argumento."},{"id":25,"materia":"inf","nivel":2,"enunciado":"Qual protocolo garante navegação web criptografada?","opcoes":["HTTPS","HTTP","FTP","SMTP"],"explicacao":"HTTPS é o HTTP com camada de segurança (TLS). FTP transfere arquivos e SMTP envia e-mails."},{"id":26,"materia":"inf","nivel":2,"enunciado":"O backup incremental copia:","opcoes":["Apenas o que mudou desde o último backup de qualquer tipo","Todos os arquivos, sempre","O que mudou desde o último backup completo","Somente arquivos do sistema operacional"],"explicacao":"Incremental: desde o último backup (completo ou incremental). Diferencial: desde o último completo."},{"id":27,"materia":"inf","nivel":2,"enunciado":"No Windows, qual atalho bloqueia a tela rapidamente?","opcoes":["Windows + L","Windows + D","Alt + F4","Ctrl + Shift + Esc"],"explicacao":"Win+L bloqueia. Win+D mostra a área de trabalho, Alt+F4 fecha a janela e Ctrl+Shift+Esc abre o Gerenciador de Tarefas."},{"id":28,"materia":"rl","nivel":2,"enunciado":"Qual é a negação de “Todos os candidatos estudaram”?","opcoes":["Algum candidato não estudou","Nenhum candidato estudou","Todos os candidatos não estudaram","Algum candidato estudou"],"explicacao":"Para negar “todos”, basta um contraexemplo: “algum… não…”."},{"id":29,"materia":"rl","nivel":2,"enunciado":"“Se chove, a rua fica molhada.” A rua não está molhada. Logo:","opcoes":["Não choveu","Choveu","Pode ter chovido","A rua está seca porque não choveu e ventou"],"explicacao":"É o modus tollens: se P→Q e não Q, então não P."},{"id":30,"materia":"rl","nivel":2,"enunciado":"A proposição “P e Q” é verdadeira quando:","opcoes":["P e Q são ambas verdadeiras","Pelo menos uma é verdadeira","Ambas são falsas","P é falsa e Q é verdadeira"],"explicacao":"A conjunção só é verdadeira se as duas partes forem verdadeiras."},{"id":31,"materia":"rl","nivel":2,"enunciado":"R$ 1.000,00 aplicados a juros simples de 2% ao mês renderão quanto de juros em 5 meses?","opcoes":["R$ 100,00","R$ 104,08","R$ 50,00","R$ 120,00"],"explicacao":"J = C × i × t = 1000 × 0,02 × 5 = 100. O valor 104,08 seria juros compostos."},{"id":32,"materia":"rl","nivel":2,"enunciado":"De quantas maneiras se escolhem 2 pessoas entre 5 para uma comissão?","opcoes":["10","20","25","5"],"explicacao":"Combinação C(5,2) = 5 × 4 ÷ 2 = 10. A ordem não importa."},{"id":33,"materia":"dh","nivel":2,"enunciado":"O Pacto de San José da Costa Rica é o nome da:","opcoes":["Convenção Americana sobre Direitos Humanos","Declaração Universal dos Direitos Humanos","Convenção contra a Tortura da ONU","Carta da OEA"],"explicacao":"É a Convenção Americana sobre Direitos Humanos, de 1969, promulgada no Brasil em 1992."},{"id":34,"materia":"dh","nivel":2,"enunciado":"Tratados de direitos humanos aprovados em dois turnos, por 3/5 dos votos de cada Casa do Congresso, equivalem a:","opcoes":["Emendas constitucionais","Leis ordinárias","Leis complementares","Decretos legislativos sem força normativa"],"explicacao":"Art. 5º, § 3º, incluído pela EC 45/2004."},{"id":35,"materia":"port","nivel":3,"enunciado":"Em “Espero que você venha”, a oração “que você venha” é:","opcoes":["Subordinada substantiva objetiva direta","Subordinada substantiva subjetiva","Subordinada adjetiva restritiva","Subordinada adverbial final"],"explicacao":"Ela completa o verbo “esperar” sem preposição, funcionando como objeto direto: “espero isso”."},{"id":36,"materia":"port","nivel":3,"enunciado":"Na frase “Os candidatos que estudaram foram aprovados”, sem vírgulas, entende-se que:","opcoes":["Só uma parte dos candidatos estudou, e foi essa parte a aprovada","Todos os candidatos estudaram e foram aprovados","Nenhum candidato estudou","Os aprovados não estudaram"],"explicacao":"Sem vírgulas, a oração adjetiva é restritiva: delimita um grupo. Com vírgulas, seria explicativa e valeria para todos."},{"id":37,"materia":"port","nivel":3,"enunciado":"Qual frase está de acordo com a norma-padrão?","opcoes":["Vendem-se casas neste bairro.","Precisam-se de vendedores.","Aluga-se salas comerciais.","Fazem dez dias que ele saiu."],"explicacao":"Com voz passiva sintética o verbo concorda com o sujeito (casas são vendidas). Com verbo que pede preposição, o “se” indetermina o sujeito e o verbo fica no singular (precisa-se de)."},{"id":38,"materia":"port","nivel":3,"enunciado":"Em qual situação o acento indicativo de crase é FACULTATIVO?","opcoes":["Antes de possessivo feminino no singular","Antes de verbo no infinitivo","Antes de palavra masculina","Na locução “à medida que”"],"explicacao":"“Entreguei o livro a/à minha irmã”: o artigo antes de possessivo é opcional, então a crase também. Antes de verbo e masculino é proibida; em “à medida que”, obrigatória."},{"id":39,"materia":"port","nivel":3,"enunciado":"Qual frase emprega “aonde” corretamente?","opcoes":["Aonde você vai nas férias?","Aonde fica a delegacia?","Aonde você mora?","Onde você foi ontem à noite?"],"explicacao":"“Aonde” = “a + onde”, usado com verbos de movimento que pedem “a” (ir a). “Ficar” e “morar” pedem “onde”. “Ir” pede “aonde”."},{"id":40,"materia":"const","nivel":3,"enunciado":"Qual o quórum para aprovar uma Proposta de Emenda à Constituição?","opcoes":["3/5 dos membros, em dois turnos, em cada Casa","Maioria absoluta, em turno único, em cada Casa","2/3 dos membros, em dois turnos, em sessão conjunta","Maioria simples, em dois turnos, em cada Casa"],"explicacao":"Art. 60, § 2º."},{"id":41,"materia":"const","nivel":3,"enunciado":"Qual destas NÃO é cláusula pétrea expressa no art. 60, § 4º?","opcoes":["A forma republicana de governo","A forma federativa de Estado","A separação dos Poderes","Os direitos e garantias individuais"],"explicacao":"São cláusulas pétreas: forma federativa, voto direto, secreto, universal e periódico, separação dos Poderes e direitos e garantias individuais. A república não está na lista."},{"id":42,"materia":"const","nivel":3,"enunciado":"Qual cargo NÃO é privativo de brasileiro nato?","opcoes":["Ministro do Superior Tribunal de Justiça","Ministro do Supremo Tribunal Federal","Oficial das Forças Armadas","Ministro de Estado da Defesa"],"explicacao":"Art. 12, § 3º. A lista inclui Ministro do STF, mas não do STJ."},{"id":43,"materia":"const","nivel":3,"enunciado":"O mandado de injunção é cabível quando:","opcoes":["Falta norma regulamentadora e o exercício de um direito fica inviável","Há ilegalidade praticada por autoridade pública contra direito certo","Alguém sofre ameaça à sua liberdade de locomoção","O cidadão quer anular ato lesivo ao meio ambiente"],"explicacao":"Art. 5º, LXXI. Ele combate a omissão legislativa."},{"id":44,"materia":"const","nivel":3,"enunciado":"Por determinação judicial, pode-se entrar na casa de alguém sem consentimento do morador:","opcoes":["Somente durante o dia","A qualquer hora","Somente à noite","Somente com a presença do Ministério Público"],"explicacao":"Art. 5º, XI. Já em flagrante delito, desastre ou para prestar socorro, a entrada pode ser a qualquer hora."},{"id":45,"materia":"adm","nivel":3,"enunciado":"Após a Lei nº 14.230/2021, os atos de improbidade administrativa:","opcoes":["Exigem dolo para configuração","Admitem modalidade culposa em todos os casos","Admitem culpa apenas no dano ao erário","Dispensam qualquer elemento subjetivo"],"explicacao":"A reforma da Lei 8.429/92 passou a exigir dolo em todas as modalidades e acabou com a improbidade culposa."},{"id":46,"materia":"adm","nivel":3,"enunciado":"Qual modalidade de licitação foi CRIADA pela Lei nº 14.133/2021?","opcoes":["Diálogo competitivo","Pregão","Tomada de preços","Convite"],"explicacao":"A nova lei criou o diálogo competitivo e extinguiu tomada de preços e convite. O pregão já existia desde 2002."},{"id":47,"materia":"adm","nivel":3,"enunciado":"Na Lei nº 8.112/1990, a penalidade de suspensão não pode passar de:","opcoes":["90 dias","30 dias","60 dias","120 dias"],"explicacao":"Art. 130 da Lei 8.112."},{"id":48,"materia":"adm","nivel":3,"enunciado":"Segundo a Constituição, a instituição de empresa pública é:","opcoes":["Autorizada por lei específica","Criada diretamente por lei específica","Criada por decreto do Executivo","Autorizada por resolução do Senado"],"explicacao":"Art. 37, XIX: a lei específica CRIA a autarquia e AUTORIZA empresa pública, sociedade de economia mista e fundação."},{"id":49,"materia":"pen","nivel":3,"enunciado":"Não se pune a tentativa quando, por ineficácia absoluta do meio ou absoluta impropriedade do objeto, é impossível consumar o crime. Isso é:","opcoes":["Crime impossível","Desistência voluntária","Arrependimento eficaz","Erro de proibição"],"explicacao":"Art. 17 do CP. Ex.: tentar matar quem já estava morto."},{"id":50,"materia":"pen","nivel":3,"enunciado":"No arrependimento posterior, a reparação do dano deve ocorrer até:","opcoes":["O recebimento da denúncia ou queixa","O oferecimento da denúncia","A sentença de primeiro grau","O trânsito em julgado"],"explicacao":"Art. 16 do CP. Vale para crimes sem violência ou grave ameaça e reduz a pena de um a dois terços."},{"id":51,"materia":"pen","nivel":3,"enunciado":"Quem julga o crime de latrocínio?","opcoes":["O juiz singular","O Tribunal do Júri","O juizado especial criminal","O tribunal de justiça originariamente"],"explicacao":"Súmula 603 do STF. O latrocínio é crime contra o patrimônio, não doloso contra a vida."},{"id":52,"materia":"pen","nivel":3,"enunciado":"O erro sobre elemento do tipo, quando inevitável:","opcoes":["Exclui o dolo e a culpa","Exclui só o dolo, permitindo punição por culpa","Apenas diminui a pena","Não tem nenhum efeito"],"explicacao":"Art. 20 do CP. Se o erro for evitável, exclui o dolo e permite punir por culpa, se houver previsão legal."},{"id":53,"materia":"pen","nivel":3,"enunciado":"Quanto ao tempo do crime, o Código Penal adota a teoria:","opcoes":["Da atividade","Do resultado","Da ubiquidade","Mista"],"explicacao":"Art. 4º: considera-se praticado no momento da ação ou omissão. Para o LUGAR do crime (art. 6º), vale a ubiquidade."},{"id":54,"materia":"ppen","nivel":3,"enunciado":"Fora do contexto de violência doméstica contra a mulher, a ação penal na lesão corporal leve é:","opcoes":["Pública condicionada à representação","Pública incondicionada","Privada","Privada subsidiária"],"explicacao":"Art. 88 da Lei 9.099/95. Na violência doméstica contra a mulher, é incondicionada (Súmula 542 do STJ)."},{"id":55,"materia":"ppen","nivel":3,"enunciado":"Estando o réu preso, o prazo para o Ministério Público oferecer denúncia é de:","opcoes":["5 dias","15 dias","10 dias","30 dias"],"explicacao":"Art. 46 do CPP: 5 dias se preso, 15 dias se solto."},{"id":56,"materia":"ppen","nivel":3,"enunciado":"Nos crimes hediondos, a prisão temporária dura:","opcoes":["30 dias, prorrogáveis por igual período","5 dias, prorrogáveis por igual período","10 dias, improrrogáveis","60 dias, improrrogáveis"],"explicacao":"Lei 8.072/90, art. 2º, § 4º. Nos demais crimes, são 5 + 5 dias."},{"id":57,"materia":"ppen","nivel":3,"enunciado":"O juiz das garantias foi incluído no CPP pela:","opcoes":["Lei nº 13.964/2019","Lei nº 12.403/2011","Lei nº 11.719/2008","Lei nº 9.296/1996"],"explicacao":"É o Pacote Anticrime, que criou os arts. 3º-A a 3º-F do CPP. O STF validou o instituto em 2023, com ajustes."},{"id":58,"materia":"ppen","nivel":3,"enunciado":"A busca pessoal sem mandado é permitida quando:","opcoes":["Houver prisão ou fundada suspeita de arma ou objetos do crime","O delegado autorizar verbalmente a abordagem","For realizada de dia, em local público","A pessoa abordada for reincidente"],"explicacao":"Art. 244 do CPP."},{"id":59,"materia":"inf","nivel":3,"enunciado":"Em qual camada do modelo OSI o roteador atua principalmente?","opcoes":["Rede (camada 3)","Enlace (camada 2)","Transporte (camada 4)","Física (camada 1)"],"explicacao":"O roteador encaminha pacotes por endereço IP, na camada de rede. O switch tradicional atua na camada 2."},{"id":60,"materia":"inf","nivel":3,"enunciado":"O que caracteriza um cavalo de Troia?","opcoes":["Parece um programa legítimo, mas executa ações maliciosas","Se replica sozinho pela rede, sem hospedeiro","Só exibe anúncios indesejados","Bloqueia o acesso à internet"],"explicacao":"O trojan engana o usuário fingindo ser útil. Quem se propaga sozinho é o worm."},{"id":61,"materia":"inf","nivel":3,"enunciado":"A função PROCV no Excel:","opcoes":["Procura um valor na 1ª coluna e retorna outra coluna da linha","Conta as células de um intervalo que atendem a um critério","Soma os valores de uma linha que atendem a uma condição","Arredonda números para cima até o múltiplo indicado"],"explicacao":"PROCV = procura vertical. Contar com critério é CONT.SE."},{"id":62,"materia":"inf","nivel":3,"enunciado":"Quantos bits tem um endereço IPv4?","opcoes":["32","64","128","16"],"explicacao":"IPv4 tem 32 bits (ex.: 192.168.0.1). O IPv6 tem 128."},{"id":63,"materia":"inf","nivel":3,"enunciado":"A criptografia assimétrica utiliza:","opcoes":["Um par de chaves, uma pública e uma privada","Uma única chave compartilhada","Apenas senha numérica","Nenhuma chave"],"explicacao":"Na assimétrica, o que uma chave cifra só a outra decifra. A simétrica usa uma chave só."},{"id":64,"materia":"rl","nivel":3,"enunciado":"Qual proposição é equivalente a “Se estudo, então passo”?","opcoes":["Se não passo, então não estudo","Se passo, então estudo","Se não estudo, então não passo","Estudo e passo"],"explicacao":"É a contrapositiva: P→Q equivale a ¬Q→¬P. Também equivale a “Não estudo ou passo”."},{"id":65,"materia":"rl","nivel":3,"enunciado":"Qual é a negação de “Se estudo, então passo”?","opcoes":["Estudo e não passo","Não estudo e não passo","Se não estudo, então não passo","Não estudo ou passo"],"explicacao":"A negação de P→Q é P ∧ ¬Q: acontece a condição e não acontece a consequência."},{"id":66,"materia":"rl","nivel":3,"enunciado":"Lançando dois dados comuns, qual a probabilidade de a soma ser 7?","opcoes":["1/6","1/12","7/36","1/9"],"explicacao":"São 6 combinações favoráveis (1+6, 2+5, 3+4, 4+3, 5+2, 6+1) em 36 possíveis: 6/36 = 1/6."},{"id":67,"materia":"rl","nivel":3,"enunciado":"Quantos anagramas tem a palavra PROVA?","opcoes":["120","60","24","720"],"explicacao":"São 5 letras distintas: 5! = 5 × 4 × 3 × 2 × 1 = 120."},{"id":68,"materia":"rl","nivel":3,"enunciado":"Uma torneira enche um tanque em 3 h; outra, em 6 h. Juntas, enchem em:","opcoes":["2 horas","4,5 horas","1,5 hora","2,5 horas"],"explicacao":"Por hora: 1/3 + 1/6 = 1/2 do tanque. Logo, 2 horas."},{"id":69,"materia":"dh","nivel":3,"enunciado":"Segundo a Constituição, o crime de tortura é:","opcoes":["Inafiançável e insuscetível de graça ou anistia","Imprescritível e afiançável","Inafiançável e imprescritível","Afiançável, mas insuscetível de anistia"],"explicacao":"Art. 5º, XLIII. Tortura, tráfico, terrorismo e hediondos são inafiançáveis e insuscetíveis de graça ou anistia, mas não imprescritíveis."},{"id":70,"materia":"dh","nivel":3,"enunciado":"Segundo a Constituição, a prática do racismo é:","opcoes":["Inafiançável e imprescritível","Afiançável e prescritível","Inafiançável, mas prescritível","Insuscetível de graça, mas afiançável"],"explicacao":"Art. 5º, XLII. Também é imprescritível a ação de grupos armados contra a ordem constitucional (inciso XLIV)."},{"id":71,"materia":"port","nivel":4,"enunciado":"Em “Precisa-se de técnicos”, a partícula “se” é:","opcoes":["Índice de indeterminação do sujeito","Partícula apassivadora","Pronome reflexivo","Parte integrante do verbo"],"explicacao":"O verbo pede preposição (precisar de), então não há voz passiva: o “se” indetermina o sujeito e o verbo fica no singular."},{"id":72,"materia":"port","nivel":4,"enunciado":"Em “Muito embora estivesse cansado, concluiu a prova”, a primeira oração é subordinada adverbial:","opcoes":["Concessiva","Causal","Condicional","Consecutiva"],"explicacao":"“Embora” introduz uma concessão: um fato contrário que não impede o outro."},{"id":73,"materia":"port","nivel":4,"enunciado":"Qual palavra está grafada de acordo com o Acordo Ortográfico?","opcoes":["Autoescola","Microondas","Contra-regra","Anti-religioso"],"explicacao":"Prefixo terminado em vogal + palavra iniciada por outra vogal junta (autoescola). Vogal igual separa com hífen (micro-ondas). Diante de R ou S, dobra-se a consoante (contrarregra, antirreligioso)."},{"id":74,"materia":"port","nivel":4,"enunciado":"Ao se dirigir diretamente a um juiz, qual forma é correta?","opcoes":["Vossa Excelência deve apresentar seu parecer.","Vossa Excelência deveis apresentar vosso parecer.","Sua Excelência deve apresentar vosso parecer.","Vossa Excelência deve apresentar vosso parecer."],"explicacao":"Pronomes de tratamento levam verbo e possessivos para a 3ª pessoa. Usa-se “Vossa” ao falar COM a autoridade e “Sua” ao falar DELA."},{"id":75,"materia":"const","nivel":4,"enunciado":"Medida provisória NÃO pode tratar de:","opcoes":["Direito penal","Instituição de tributos","Créditos extraordinários","Organização administrativa"],"explicacao":"Art. 62, § 1º, I, “b”: é vedada MP sobre direito penal, processual penal e processual civil. Tributo pode, observada a anterioridade."},{"id":76,"materia":"const","nivel":4,"enunciado":"Segundo o art. 144, § 4º, às polícias civis, ressalvada a competência da União, incumbem:","opcoes":["As funções de polícia judiciária e a apuração de infrações penais, exceto as militares","O policiamento ostensivo e a preservação da ordem pública","A segurança dos estabelecimentos penais","A apuração exclusiva de crimes contra a vida"],"explicacao":"Policiamento ostensivo é atribuição da PM; segurança de estabelecimentos penais cabe à polícia penal."},{"id":77,"materia":"const","nivel":4,"enunciado":"Qual órgão foi incluído no art. 144 da Constituição pela EC nº 104/2019?","opcoes":["Polícias penais","Guardas municipais","Polícia ferroviária federal","Força Nacional de Segurança Pública"],"explicacao":"A EC 104/2019 criou as polícias penais federal, estaduais e distrital. A Força Nacional não está no art. 144."},{"id":78,"materia":"const","nivel":4,"enunciado":"Para aprovar uma súmula vinculante, o STF precisa do voto de:","opcoes":["Dois terços dos seus membros","Maioria absoluta","Maioria simples","Três quintos dos seus membros"],"explicacao":"Art. 103-A da Constituição: decisão de 2/3 dos membros, ou seja, 8 ministros."},{"id":79,"materia":"const","nivel":4,"enunciado":"Qual destes NÃO tem legitimidade para propor ADI no STF, segundo o art. 103?","opcoes":["Defensor Público-Geral da União","Conselho Federal da OAB","Procurador-Geral da República","Partido político com representação no Congresso"],"explicacao":"O rol do art. 103 não inclui o DPGU."},{"id":80,"materia":"adm","nivel":4,"enunciado":"Pela Lei nº 9.784/1999, o direito de anular atos com efeitos favoráveis ao destinatário decai em:","opcoes":["5 anos, salvo má-fé","2 anos","10 anos","3 anos, salvo má-fé"],"explicacao":"Art. 54 da Lei 9.784/99."},{"id":81,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 9.784/1999, o recurso administrativo tramita, salvo disposição legal diversa, por no máximo:","opcoes":["Três instâncias administrativas","Duas instâncias","Quatro instâncias","Uma instância"],"explicacao":"Art. 57 da Lei 9.784/99."},{"id":82,"materia":"adm","nivel":4,"enunciado":"Qual destes NÃO é critério de julgamento previsto na Lei nº 14.133/2021?","opcoes":["Melhor proposta socioambiental","Maior desconto","Técnica e preço","Maior retorno econômico"],"explicacao":"Art. 33: menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance e maior retorno econômico."},{"id":83,"materia":"adm","nivel":4,"enunciado":"Pela teoria dos motivos determinantes:","opcoes":["O motivo declarado vincula a validade do ato, mesmo se discricionário","Atos discricionários dispensam qualquer motivo","Só atos vinculados precisam ter motivo verdadeiro","O motivo pode ser alterado depois sem consequência"],"explicacao":"Se a Administração declara um motivo e ele é falso ou inexistente, o ato é inválido."},{"id":84,"materia":"adm","nivel":4,"enunciado":"Na Lei de Improbidade, com a redação da Lei nº 14.230/2021, quem comete ato que gera enriquecimento ilícito pode ter os direitos políticos suspensos por até:","opcoes":["14 anos","8 anos","10 anos","12 anos"],"explicacao":"Art. 12, I. Para dano ao erário, o limite é de até 12 anos (art. 12, II)."},{"id":85,"materia":"pen","nivel":4,"enunciado":"No peculato culposo, a reparação do dano ANTES da sentença irrecorrível:","opcoes":["Extingue a punibilidade","Reduz a pena pela metade","Reduz a pena de um a dois terços","Não produz efeito"],"explicacao":"Art. 312, § 3º. Se a reparação vier depois da sentença irrecorrível, a pena é reduzida de metade."},{"id":86,"materia":"pen","nivel":4,"enunciado":"Os prazos de prescrição são reduzidos pela metade quando o agente era, ao tempo do crime, menor de:","opcoes":["21 anos, ou maior de 70 na data da sentença","18 anos, ou maior de 60 na data do crime","21 anos, ou maior de 60 na data da sentença","18 anos, ou maior de 70 na data do crime"],"explicacao":"Art. 115 do CP."},{"id":87,"materia":"pen","nivel":4,"enunciado":"Em regra, os atos preparatórios de um crime:","opcoes":["Não são puníveis","São punidos como tentativa","São punidos com a pena do crime consumado","São punidos com metade da pena"],"explicacao":"Pelo iter criminis, cogitação e preparação são impuníveis. Exceção: quando o próprio ato preparatório é crime autônomo (ex.: associação criminosa)."},{"id":88,"materia":"pen","nivel":4,"enunciado":"Na desistência voluntária e no arrependimento eficaz, o agente responde:","opcoes":["Apenas pelos atos já praticados","Pelo crime tentado","Pelo crime consumado, com pena reduzida","Por nada, pois há isenção total"],"explicacao":"Art. 15 do CP. É a chamada “ponte de ouro”."},{"id":89,"materia":"pen","nivel":4,"enunciado":"Com a Lei nº 14.994/2024, o feminicídio passou a ser:","opcoes":["Crime autônomo, com pena de 20 a 40 anos","Qualificadora do homicídio, com pena de 12 a 30 anos","Causa de aumento do homicídio simples","Crime de menor potencial ofensivo"],"explicacao":"O “pacote antifeminicídio” criou o art. 121-A do CP, com reclusão de 20 a 40 anos."},{"id":90,"materia":"ppen","nivel":4,"enunciado":"Qual destes é requisito do acordo de não persecução penal (art. 28-A do CPP)?","opcoes":["Pena mínima inferior a 4 anos e confissão formal","Pena máxima de até 2 anos","Crime cometido com grave ameaça","Réu reincidente específico"],"explicacao":"Exige ainda infração sem violência ou grave ameaça e que o acordo seja necessário e suficiente para reprovação e prevenção do crime."},{"id":91,"materia":"ppen","nivel":4,"enunciado":"Segundo o CPP, a cadeia de custódia começa:","opcoes":["Com a preservação do local ou a detecção do vestígio","Com o recebimento da denúncia pelo juiz","Com a chegada do vestígio ao laboratório","Com o indiciamento formal do suspeito"],"explicacao":"Art. 158-A, § 1º, incluído pelo Pacote Anticrime."},{"id":92,"materia":"ppen","nivel":4,"enunciado":"A interceptação telefônica NÃO será admitida quando o fato investigado for punido, no máximo, com:","opcoes":["Detenção","Reclusão","Reclusão de até 4 anos","Multa e reclusão"],"explicacao":"Art. 2º, III, da Lei 9.296/96. O prazo é de 15 dias, renovável por igual tempo se comprovada a necessidade."},{"id":93,"materia":"ppen","nivel":4,"enunciado":"Decretada a prisão preventiva, o juiz deve revisar a necessidade da medida a cada:","opcoes":["90 dias","30 dias","60 dias","180 dias"],"explicacao":"Art. 316, parágrafo único, do CPP, incluído pelo Pacote Anticrime."},{"id":94,"materia":"inf","nivel":4,"enunciado":"Qual é a porta padrão do protocolo HTTPS?","opcoes":["443","80","21","25"],"explicacao":"HTTPS usa a 443. HTTP usa 80, FTP 21 e SMTP 25."},{"id":95,"materia":"inf","nivel":4,"enunciado":"No Excel, qual o resultado de =ARRED(2,567;1)?","opcoes":["2,6","2,5","2,57","3"],"explicacao":"ARRED arredonda para o número de casas indicado: 2,567 com uma casa decimal vira 2,6."},{"id":96,"materia":"inf","nivel":4,"enunciado":"A assinatura digital NÃO garante, por si só:","opcoes":["Confidencialidade","Autenticidade","Integridade","Não repúdio"],"explicacao":"A assinatura prova quem assinou e que nada mudou, mas não esconde o conteúdo. Para isso é preciso cifrar a mensagem."},{"id":97,"materia":"inf","nivel":4,"enunciado":"O que diferencia um worm de um vírus tradicional?","opcoes":["O worm se propaga sozinho, sem precisar infectar outro arquivo","O worm só ataca celulares","O vírus não causa danos","O worm precisa ser executado pelo usuário a cada cópia"],"explicacao":"O vírus precisa de um arquivo hospedeiro e de execução. O worm explora falhas e se espalha automaticamente pela rede."},{"id":98,"materia":"rl","nivel":4,"enunciado":"Qual destas é uma contradição (sempre falsa)?","opcoes":["P e não P","P ou não P","Se P, então P","Não (P e não P)"],"explicacao":"“P e não P” nunca é verdadeira. “P ou não P” é tautologia."},{"id":99,"materia":"rl","nivel":4,"enunciado":"Com os algarismos 1, 2, 3, 4 e 5, quantos números de 3 algarismos distintos podem ser formados?","opcoes":["60","125","10","120"],"explicacao":"Arranjo: 5 × 4 × 3 = 60. Com repetição seriam 125."},{"id":100,"materia":"rl","nivel":4,"enunciado":"“Nenhum A é B. Algum C é A.” Logo, necessariamente:","opcoes":["Algum C não é B","Nenhum C é B","Algum C é B","Todo C é A"],"explicacao":"Os C que são A não podem ser B. Então pelo menos esses C não são B."},{"id":101,"materia":"rl","nivel":4,"enunciado":"R$ 1.000,00 aplicados a juros compostos de 10% ao mês. Qual o montante após 2 meses?","opcoes":["R$ 1.210,00","R$ 1.200,00","R$ 1.100,00","R$ 1.221,00"],"explicacao":"1.000 × 1,1 × 1,1 = 1.210. Em juros simples seria 1.200."},{"id":102,"materia":"rl","nivel":4,"enunciado":"Lançando uma moeda 3 vezes, qual a probabilidade de sair pelo menos uma cara?","opcoes":["7/8","1/2","3/8","1/8"],"explicacao":"Complementar: a única forma de não ter cara é coroa nas três (1/8). Então 1 − 1/8 = 7/8."},{"id":103,"materia":"dh","nivel":4,"enunciado":"Onde fica a sede da Corte Interamericana de Direitos Humanos?","opcoes":["San José, Costa Rica","Washington, EUA","Haia, Países Baixos","Genebra, Suíça"],"explicacao":"A Corte fica em San José. A Comissão Interamericana fica em Washington."},{"id":104,"materia":"dh","nivel":4,"enunciado":"O princípio do non-refoulement, ligado ao refúgio, significa:","opcoes":["Proibição de devolver o refugiado a território onde corra risco","Direito de o Estado expulsar refugiados sem processo","Obrigação de naturalizar o refugiado em 1 ano","Dever do refugiado de voltar ao país de origem"],"explicacao":"Previsto na Convenção de 1951 e na Lei 9.474/97, impede a devolução para onde a vida ou a liberdade estejam ameaçadas."},{"id":105,"materia":"dh","nivel":4,"enunciado":"As “Regras de Mandela” são:","opcoes":["Regras mínimas da ONU para o tratamento de pessoas presas","Normas da OEA sobre refugiados","Princípios da ONU sobre independência judicial","Diretrizes contra o racismo no esporte"],"explicacao":"São as Regras Mínimas das Nações Unidas para o Tratamento de Reclusos, revistas em 2015."},{"id":106,"materia":"port","nivel":2,"enunciado":"Complete: “A proposta veio ___ meus interesses, por isso a aceitei.”","opcoes":["ao encontro de","de encontro a","à encontro de","em encontro a"],"explicacao":"“Ao encontro de” indica concordância. “De encontro a” indica choque, oposição."},{"id":107,"materia":"port","nivel":2,"enunciado":"Complete: “Daqui ___ dois dias sai o resultado.”","opcoes":["a","há","à","ah"],"explicacao":"Para tempo futuro usa-se a preposição “a”. “Há” fica para tempo passado."},{"id":108,"materia":"port","nivel":2,"enunciado":"Complete: “A ___ do júri começou às 9 horas.”","opcoes":["sessão","seção","cessão","secção"],"explicacao":"Sessão é reunião ou tempo de duração de um evento. Seção é divisão; cessão é o ato de ceder."},{"id":109,"materia":"port","nivel":2,"enunciado":"Qual frase está correta quanto à concordância nominal?","opcoes":["É proibido entrada de pessoas estranhas.","É proibido a entrada de pessoas estranhas.","Seguem anexo os documentos.","Elas mesmo resolveram o problema."],"explicacao":"Sem artigo, “é proibido” fica invariável. Com artigo, concorda: “é proibida a entrada”. “Anexo” e “mesmo” concordam com o substantivo: “seguem anexos”, “elas mesmas”."},{"id":110,"materia":"const","nivel":2,"enunciado":"Qual destes NÃO está entre os direitos sociais do art. 6º da Constituição?","opcoes":["Propriedade","Moradia","Transporte","Lazer"],"explicacao":"A propriedade é direito individual (art. 5º). O art. 6º lista educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança e outros."},{"id":111,"materia":"const","nivel":2,"enunciado":"Quem pode propor ação popular?","opcoes":["Qualquer cidadão","Apenas o Ministério Público","Apenas partidos políticos","Qualquer pessoa jurídica"],"explicacao":"Art. 5º, LXXIII: qualquer cidadão, ou seja, quem está em dia com os direitos políticos."},{"id":112,"materia":"const","nivel":2,"enunciado":"Quantos senadores cada estado e o Distrito Federal elegem?","opcoes":["3","2","4","Varia conforme a população"],"explicacao":"Art. 46, § 1º: três senadores por estado e pelo DF, independentemente da população."},{"id":113,"materia":"const","nivel":2,"enunciado":"Os municípios são regidos por:","opcoes":["Lei orgânica","Constituição municipal","Estatuto municipal","Decreto do governador"],"explicacao":"Art. 29 da CF: o município se rege por lei orgânica votada em dois turnos."},{"id":114,"materia":"adm","nivel":2,"enunciado":"O poder que permite distribuir funções, dar ordens e rever atos dos subordinados é o:","opcoes":["Hierárquico","Disciplinar","De polícia","Regulamentar"],"explicacao":"Poder hierárquico organiza a relação de subordinação dentro da Administração."},{"id":115,"materia":"adm","nivel":2,"enunciado":"Aplicar penalidade a servidor por falta funcional é exercício do poder:","opcoes":["Disciplinar","Hierárquico","De polícia","Regulamentar"],"explicacao":"Poder disciplinar pune infrações de quem tem vínculo especial com a Administração."},{"id":116,"materia":"adm","nivel":2,"enunciado":"A criação de uma autarquia é exemplo de:","opcoes":["Descentralização","Desconcentração","Concentração","Hierarquização"],"explicacao":"Descentralização transfere a atividade para outra pessoa jurídica. Desconcentração distribui entre órgãos da mesma pessoa."},{"id":117,"materia":"adm","nivel":2,"enunciado":"Qual destes NÃO é elemento (requisito) do ato administrativo?","opcoes":["Imperatividade","Competência","Finalidade","Motivo"],"explicacao":"Elementos: competência, finalidade, forma, motivo e objeto. Imperatividade é atributo."},{"id":118,"materia":"pen","nivel":2,"enunciado":"Constranger alguém, mediante violência ou grave ameaça, com intuito de obter vantagem econômica, a fazer ou deixar de fazer algo é:","opcoes":["Extorsão","Roubo","Constrangimento ilegal","Estelionato"],"explicacao":"Art. 158 do CP. Na extorsão, a vítima colabora com a conduta exigida; no roubo, o agente subtrai diretamente."},{"id":119,"materia":"pen","nivel":2,"enunciado":"Apropriar-se de coisa alheia móvel de que já tem a posse ou a detenção é:","opcoes":["Apropriação indébita","Furto","Peculato, sempre","Receptação"],"explicacao":"Art. 168 do CP. A posse é lícita no início, e o dolo de ficar com a coisa surge depois."},{"id":120,"materia":"pen","nivel":2,"enunciado":"O servidor que retarda ato de ofício para satisfazer sentimento pessoal comete:","opcoes":["Prevaricação","Concussão","Corrupção passiva","Condescendência criminosa"],"explicacao":"Art. 319 do CP."},{"id":121,"materia":"pen","nivel":2,"enunciado":"O crime é culposo quando o agente deu causa ao resultado por:","opcoes":["Imprudência, negligência ou imperícia","Vontade livre e consciente","Coação irresistível","Obediência hierárquica"],"explicacao":"Art. 18, II, do Código Penal."},{"id":122,"materia":"ppen","nivel":2,"enunciado":"A ação penal privada começa com:","opcoes":["Queixa-crime","Denúncia","Representação","Requisição do Ministro da Justiça"],"explicacao":"Na ação privada, o ofendido ou seu representante oferece queixa por meio de advogado."},{"id":123,"materia":"ppen","nivel":2,"enunciado":"Em regra, o prazo para o ofendido oferecer queixa é de:","opcoes":["6 meses, contados de quando souber quem é o autor","1 ano, contado da data em que o fato ocorreu","30 dias, contados da data em que o fato ocorreu","2 anos, contados da descoberta do crime"],"explicacao":"Art. 38 do CPP. É prazo decadencial."},{"id":124,"materia":"ppen","nivel":2,"enunciado":"Nos crimes de ação pública incondicionada, o inquérito pode ser instaurado:","opcoes":["De ofício pela autoridade policial","Somente a pedido da vítima","Somente por ordem do juiz","Somente após representação"],"explicacao":"Art. 5º, I, do CPP."},{"id":125,"materia":"leg","nivel":2,"enunciado":"Na Lei nº 9.099/1995, infração de menor potencial ofensivo é a contravenção ou o crime com pena máxima não superior a:","opcoes":["2 anos","1 ano","4 anos","3 anos"],"explicacao":"Art. 61 da Lei 9.099/95."},{"id":126,"materia":"leg","nivel":2,"enunciado":"Quem é flagrado com droga para consumo pessoal (art. 28 da Lei de Drogas):","opcoes":["Não está sujeito a pena de prisão","Recebe pena de 1 a 3 anos de detenção","Responde por tráfico","Tem prisão preventiva obrigatória"],"explicacao":"As penas são advertência, prestação de serviços à comunidade e medida educativa."},{"id":127,"materia":"leg","nivel":2,"enunciado":"A Lei nº 13.869/2019 trata dos crimes de:","opcoes":["Abuso de autoridade","Lavagem de dinheiro","Tortura","Organização criminosa"],"explicacao":"É a nova Lei de Abuso de Autoridade, que substituiu a Lei 4.898/65."},{"id":128,"materia":"inf","nivel":2,"enunciado":"No e-mail, o campo que envia cópia sem que os demais destinatários vejam é o:","opcoes":["CCO","CC","Para","Assunto"],"explicacao":"CCO é cópia carbono oculta. Quem está em CC aparece para todos."},{"id":129,"materia":"inf","nivel":2,"enunciado":"O Linux é:","opcoes":["Um sistema operacional de código aberto","Um navegador da Microsoft","Um antivírus pago","Um editor de planilhas"],"explicacao":"Linux é sistema operacional livre, base de distribuições como Ubuntu e Debian."},{"id":130,"materia":"inf","nivel":2,"enunciado":"Google Drive e OneDrive são exemplos de:","opcoes":["Armazenamento em nuvem","Sistemas operacionais","Antivírus","Navegadores"],"explicacao":"São serviços que guardam arquivos em servidores remotos acessíveis pela internet."},{"id":131,"materia":"inf","nivel":2,"enunciado":"No Excel, qual o resultado de =MÉDIA(2;4;6)?","opcoes":["4","12","6","3"],"explicacao":"(2 + 4 + 6) ÷ 3 = 4."},{"id":132,"materia":"rl","nivel":2,"enunciado":"Um carro percorre 240 km em 3 horas. Qual a velocidade média?","opcoes":["80 km/h","72 km/h","90 km/h","60 km/h"],"explicacao":"240 ÷ 3 = 80 km/h."},{"id":133,"materia":"rl","nivel":2,"enunciado":"3 servidores fazem um trabalho em 12 dias. Em quantos dias 6 servidores fazem o mesmo trabalho?","opcoes":["6 dias","24 dias","4 dias","9 dias"],"explicacao":"Grandezas inversamente proporcionais: dobrando os servidores, o tempo cai pela metade."},{"id":134,"materia":"rl","nivel":2,"enunciado":"A proposição “P ou Q” é falsa quando:","opcoes":["P e Q são ambas falsas","P e Q são ambas verdadeiras","Apenas P é verdadeira","Apenas Q é verdadeira"],"explicacao":"A disjunção só é falsa se as duas partes forem falsas."},{"id":135,"materia":"dh","nivel":2,"enunciado":"Segundo o ECA, adolescente é a pessoa entre:","opcoes":["12 e 18 anos","10 e 16 anos","14 e 21 anos","12 e 21 anos"],"explicacao":"Art. 2º do ECA. Excepcionalmente, o estatuto se aplica a pessoas entre 18 e 21 anos."},{"id":136,"materia":"port","nivel":3,"enunciado":"Em qual frase a próclise é exigida por palavra atrativa?","opcoes":["Quem te contou isso?","Contaram-me tudo.","Vou contar-te tudo.","Contar-lhe-ei amanhã."],"explicacao":"Pronomes interrogativos atraem o pronome oblíquo para antes do verbo."},{"id":137,"materia":"port","nivel":3,"enunciado":"Em “A casa de Pedro foi vendida”, o termo “de Pedro” é:","opcoes":["Adjunto adnominal","Complemento nominal","Objeto indireto","Agente da passiva"],"explicacao":"Indica posse e caracteriza o substantivo concreto “casa”. Isso é adjunto adnominal."},{"id":138,"materia":"port","nivel":3,"enunciado":"Em “O livro foi escrito pelo autor”, o termo “pelo autor” é:","opcoes":["Agente da passiva","Objeto indireto","Adjunto adverbial","Sujeito"],"explicacao":"Na voz passiva analítica, quem pratica a ação é o agente da passiva."},{"id":139,"materia":"port","nivel":3,"enunciado":"Qual o plural de “guarda-chuva”?","opcoes":["Guarda-chuvas","Guardas-chuvas","Guardas-chuva","Guarda-chuva"],"explicacao":"Em compostos de verbo + substantivo, só o substantivo vai para o plural."},{"id":140,"materia":"port","nivel":3,"enunciado":"Em “Choveu muito ontem”, o sujeito é classificado como:","opcoes":["Inexistente","Oculto","Indeterminado","Simples"],"explicacao":"É oração sem sujeito: verbos que indicam fenômenos da natureza são impessoais."},{"id":141,"materia":"const","nivel":3,"enunciado":"A prisão civil por dívida é admitida hoje apenas no caso de:","opcoes":["Devedor voluntário de pensão alimentícia","Depositário infiel de bem penhorado","Devedor de empréstimo bancário vencido","Devedor de tributo inscrito em dívida ativa"],"explicacao":"A CF ainda menciona o depositário infiel, mas a Súmula Vinculante 25 proibiu essa prisão."},{"id":142,"materia":"const","nivel":3,"enunciado":"Legislar sobre direito penal é competência:","opcoes":["Privativa da União","Concorrente entre União e estados","Comum a todos os entes","Dos estados"],"explicacao":"Art. 22, I, da Constituição."},{"id":143,"materia":"const","nivel":3,"enunciado":"Segundo o art. 144, a segurança pública é dever do Estado e direito e responsabilidade de:","opcoes":["Todos","Apenas das polícias","Apenas dos estados","Apenas da União"],"explicacao":"É o caput do art. 144."},{"id":144,"materia":"const","nivel":3,"enunciado":"Qual a idade mínima para concorrer a Governador?","opcoes":["30 anos","35 anos","21 anos","25 anos"],"explicacao":"Art. 14, § 3º, VI, “b”. Deputado e Prefeito exigem 21; Vereador, 18."},{"id":145,"materia":"adm","nivel":3,"enunciado":"A inexigibilidade de licitação ocorre quando:","opcoes":["A competição é inviável","O valor é baixo","Há emergência","A licitação anterior foi deserta"],"explicacao":"Inexigibilidade (art. 74 da Lei 14.133) é falta de competição possível. Valor baixo e emergência são casos de dispensa."},{"id":146,"materia":"adm","nivel":3,"enunciado":"Pela Lei nº 8.112/1990, a posse deve ocorrer em até:","opcoes":["30 dias da publicação do ato de provimento","15 dias da publicação do ato de provimento","60 dias da homologação do concurso","10 dias da assinatura da nomeação"],"explicacao":"Art. 13, § 1º."},{"id":147,"materia":"adm","nivel":3,"enunciado":"Pela Lei nº 8.112/1990, após a posse, o servidor deve entrar em exercício em até:","opcoes":["15 dias","30 dias","5 dias","45 dias"],"explicacao":"Art. 15, § 1º."},{"id":148,"materia":"adm","nivel":3,"enunciado":"O Tribunal de Contas da União auxilia no controle externo o:","opcoes":["Congresso Nacional","Presidente da República","Supremo Tribunal Federal","Ministério Público"],"explicacao":"Art. 71 da Constituição."},{"id":149,"materia":"pen","nivel":3,"enunciado":"Opor-se à execução de ato legal mediante violência ou ameaça ao funcionário competente é:","opcoes":["Resistência","Desobediência","Desacato","Coação no curso do processo"],"explicacao":"Art. 329 do CP. Na desobediência (art. 330), não há violência nem ameaça."},{"id":150,"materia":"pen","nivel":3,"enunciado":"No concurso material de crimes, as penas são:","opcoes":["Somadas","Aplicadas apenas a mais grave, aumentada","Reduzidas pela metade","Unificadas na menor"],"explicacao":"Art. 69 do CP. No concurso formal e no crime continuado, aplica-se uma pena aumentada."},{"id":151,"materia":"pen","nivel":3,"enunciado":"Há reincidência quando o agente comete novo crime depois de:","opcoes":["Transitar em julgado a condenação por crime anterior","Ser denunciado pelo MP por crime anterior","Ser preso em flagrante por crime anterior","Ser indiciado em inquérito por crime anterior"],"explicacao":"Art. 63 do Código Penal."},{"id":152,"materia":"pen","nivel":3,"enunciado":"Passado quanto tempo do cumprimento ou extinção da pena a condenação anterior deixa de gerar reincidência?","opcoes":["5 anos","3 anos","10 anos","2 anos"],"explicacao":"Art. 64, I, do CP: é o período depurador."},{"id":153,"materia":"pen","nivel":3,"enunciado":"Em regra, a ação penal no crime de ameaça é:","opcoes":["Pública condicionada à representação","Pública incondicionada","Privada","Privada personalíssima"],"explicacao":"Art. 147, parágrafo único, do CP."},{"id":154,"materia":"ppen","nivel":3,"enunciado":"As provas obtidas por meios ilícitos são:","opcoes":["Inadmissíveis e devem ser retiradas do processo","Válidas, se confirmarem a culpa do réu","Válidas apenas na fase de inquérito","Admitidas com valor probatório reduzido"],"explicacao":"Art. 5º, LVI, da CF e art. 157 do CPP."},{"id":155,"materia":"ppen","nivel":3,"enunciado":"A autoridade policial pode conceder fiança nas infrações com pena máxima não superior a:","opcoes":["4 anos","2 anos","8 anos","6 anos"],"explicacao":"Art. 322 do CPP. Acima disso, a fiança é pedida ao juiz."},{"id":156,"materia":"ppen","nivel":3,"enunciado":"Após o Pacote Anticrime, a prisão preventiva pode ser decretada de ofício pelo juiz?","opcoes":["Não; depende de requerimento ou representação","Sim, em qualquer fase da persecução","Sim, mas somente durante o inquérito","Sim, mas somente durante a ação penal"],"explicacao":"Art. 311 do CPP: depende de requerimento do MP, do querelante ou do assistente, ou de representação da autoridade policial."},{"id":157,"materia":"ppen","nivel":3,"enunciado":"Em regra, a competência criminal é determinada pelo:","opcoes":["Lugar em que se consumou a infração","Domicílio ou residência da vítima","Domicílio ou residência do réu","Lugar onde o réu foi preso"],"explicacao":"Art. 70 do CPP."},{"id":158,"materia":"leg","nivel":3,"enunciado":"No Estatuto do Desarmamento, o porte ilegal de arma de fogo de uso permitido (art. 14) tem pena de:","opcoes":["Reclusão de 2 a 4 anos e multa","Detenção de 1 a 3 anos e multa","Reclusão de 3 a 6 anos e multa","Detenção de 6 meses a 2 anos"],"explicacao":"Já a posse irregular de arma de uso permitido (art. 12) tem detenção de 1 a 3 anos."},{"id":159,"materia":"leg","nivel":3,"enunciado":"Qual a pena do tráfico de drogas (art. 33 da Lei nº 11.343/2006)?","opcoes":["Reclusão de 5 a 15 anos e multa","Reclusão de 3 a 10 anos","Reclusão de 8 a 20 anos","Detenção de 2 a 8 anos"],"explicacao":"Art. 33, caput, da Lei de Drogas."},{"id":160,"materia":"leg","nivel":3,"enunciado":"Qual destas NÃO é forma de violência doméstica listada no art. 7º da Lei Maria da Penha?","opcoes":["Violência institucional","Violência patrimonial","Violência moral","Violência psicológica"],"explicacao":"O art. 7º lista violência física, psicológica, sexual, patrimonial e moral."},{"id":161,"materia":"leg","nivel":3,"enunciado":"Pela Lei de Abuso de Autoridade, a divergência na interpretação de lei ou na avaliação de fatos e provas:","opcoes":["Não configura, por si só, abuso de autoridade","Sempre configura abuso","Configura abuso se a decisão for reformada","Configura abuso culposo"],"explicacao":"Art. 1º, § 2º, da Lei 13.869/2019. O crime exige finalidade específica, como prejudicar alguém ou satisfazer capricho pessoal."},{"id":162,"materia":"inf","nivel":3,"enunciado":"Uma intranet é:","opcoes":["Uma rede privada que usa as tecnologias da internet","Um tipo de vírus que se espalha pela rede","A internet acessada pela rede do celular","Um cabo de rede de alta velocidade"],"explicacao":"A intranet usa protocolos como HTTP e TCP/IP, com acesso restrito a uma organização."},{"id":163,"materia":"inf","nivel":3,"enunciado":"A navegação anônima (janela privada) do navegador:","opcoes":["Não guarda o histórico local, mas não esconde o acesso do provedor","Torna o usuário invisível para sites e provedores","Impede a instalação de qualquer vírus no aparelho","Criptografa todos os sites, mesmo os sem HTTPS"],"explicacao":"Ela só evita guardar histórico, cookies e dados no próprio aparelho."},{"id":164,"materia":"inf","nivel":3,"enunciado":"No Excel, como se escreve uma referência absoluta à célula A1?","opcoes":["$A$1","A1","&A&1","#A#1"],"explicacao":"O cifrão fixa coluna e linha quando a fórmula é copiada."},{"id":165,"materia":"inf","nivel":3,"enunciado":"A função principal de um firewall é:","opcoes":["Filtrar o tráfego de rede conforme regras","Remover vírus de arquivos infectados","Fazer backup automático do sistema","Acelerar a conexão com a internet"],"explicacao":"Firewall permite ou bloqueia conexões. A remoção de malware é tarefa do antivírus."},{"id":166,"materia":"rl","nivel":3,"enunciado":"Quantos anagramas tem a palavra ARARA?","opcoes":["10","120","20","60"],"explicacao":"Permutação com repetição: 5! ÷ (3! × 2!) = 120 ÷ 12 = 10."},{"id":167,"materia":"rl","nivel":3,"enunciado":"Num grupo de 30 pessoas, 18 gostam de café, 15 de chá e 5 de nenhum dos dois. Quantas gostam dos dois?","opcoes":["8","3","10","13"],"explicacao":"25 gostam de pelo menos um. 18 + 15 − 25 = 8."},{"id":168,"materia":"rl","nivel":3,"enunciado":"Qual é a equivalente de “Não é verdade que João é alto e magro”?","opcoes":["João não é alto ou não é magro","João não é alto e não é magro","João é alto ou magro","João é baixo e gordo"],"explicacao":"Lei de De Morgan: ¬(P ∧ Q) equivale a ¬P ∨ ¬Q."},{"id":169,"materia":"rl","nivel":3,"enunciado":"Qual capital rende R$ 300,00 de juros simples em 6 meses, a 2,5% ao mês?","opcoes":["R$ 2.000,00","R$ 1.500,00","R$ 2.500,00","R$ 3.000,00"],"explicacao":"300 = C × 0,025 × 6 = 0,15C. Logo C = 2.000."},{"id":170,"materia":"dh","nivel":3,"enunciado":"Segundo a Súmula Vinculante 11 do STF, o uso de algemas só é lícito em caso de:","opcoes":["Resistência, receio de fuga ou perigo, justificados por escrito","Qualquer prisão em flagrante, a critério do policial","Crimes hediondos, independentemente de justificativa","Determinação verbal do delegado responsável"],"explicacao":"A excepcionalidade deve ser justificada por escrito, sob pena de responsabilidade."},{"id":171,"materia":"port","nivel":4,"enunciado":"Em “Os alunos chegaram cansados”, o termo “cansados” é:","opcoes":["Predicativo do sujeito","Adjunto adnominal","Objeto direto","Adjunto adverbial"],"explicacao":"Atribui estado ao sujeito por meio de um verbo de ação. É predicado verbo-nominal."},{"id":172,"materia":"port","nivel":4,"enunciado":"A conjunção “conquanto” expressa ideia de:","opcoes":["Concessão","Condição","Causa","Conclusão"],"explicacao":"“Conquanto” equivale a “embora”."},{"id":173,"materia":"port","nivel":4,"enunciado":"Qual frase está de acordo com a norma-padrão quanto à regência?","opcoes":["A decisão implicará prejuízos.","Aspiro o cargo de delegado.","Esqueci do compromisso.","Simpatizo-me com ele."],"explicacao":"“Implicar” no sentido de acarretar é transitivo direto. Correto: “aspiro AO cargo”, “esqueci o compromisso” ou “esqueci-me do”, “simpatizo com ele”."},{"id":174,"materia":"port","nivel":4,"enunciado":"Complete conforme a norma-padrão: “Os candidatos ___ direito a recurso.”","opcoes":["têm","tem","teem","tém"],"explicacao":"Na 3ª pessoa do plural, “ter” leva acento circunflexo: eles têm."},{"id":175,"materia":"const","nivel":4,"enunciado":"Desde a expedição do diploma, deputados e senadores não podem ser presos, salvo:","opcoes":["Em flagrante de crime inafiançável","Por ordem de qualquer juiz","Em crimes de menor potencial","Por decisão do Presidente"],"explicacao":"Art. 53, § 2º. Os autos vão em 24 horas à Casa respectiva, que decide sobre a prisão."},{"id":176,"materia":"const","nivel":4,"enunciado":"Quem decreta a intervenção federal?","opcoes":["O Presidente da República","O Congresso Nacional","O STF","O Senado Federal"],"explicacao":"Art. 84, X. O decreto é submetido ao Congresso em 24 horas."},{"id":177,"materia":"const","nivel":4,"enunciado":"O estado de defesa dura no máximo:","opcoes":["30 dias, prorrogáveis uma vez por igual período","60 dias, improrrogáveis","90 dias, prorrogáveis sem limite","15 dias, improrrogáveis"],"explicacao":"Art. 136, § 2º."},{"id":178,"materia":"const","nivel":4,"enunciado":"Quantos ministros compõem o Supremo Tribunal Federal?","opcoes":["11","15","33","9"],"explicacao":"Art. 101. O STJ tem no mínimo 33 ministros."},{"id":179,"materia":"adm","nivel":4,"enunciado":"O desvio de finalidade é vício em qual elemento do ato administrativo?","opcoes":["Finalidade","Competência","Forma","Objeto"],"explicacao":"Ocorre quando o agente busca fim diverso do interesse público ou do previsto em lei."},{"id":180,"materia":"adm","nivel":4,"enunciado":"Segundo a doutrina majoritária, a convalidação é possível para vícios de:","opcoes":["Competência não exclusiva e forma não essencial","Finalidade e motivo, se houver interesse público","Objeto e finalidade, se não houver prejuízo","Qualquer elemento, a critério do administrador"],"explicacao":"Vícios de finalidade, motivo e objeto, em regra, não são sanáveis."},{"id":181,"materia":"adm","nivel":4,"enunciado":"Pela Lei nº 8.112/1990, configura abandono de cargo a ausência intencional por mais de:","opcoes":["30 dias consecutivos","15 dias consecutivos","60 dias interpolados","45 dias consecutivos"],"explicacao":"Art. 138. Inassiduidade habitual é a falta sem causa justificada por 60 dias, interpoladamente, em 12 meses."},{"id":182,"materia":"adm","nivel":4,"enunciado":"As agências reguladoras têm natureza jurídica de:","opcoes":["Autarquias em regime especial","Empresas públicas","Sociedades de economia mista","Órgãos sem personalidade jurídica"],"explicacao":"Têm mais autonomia, como mandato fixo dos dirigentes."},{"id":183,"materia":"pen","nivel":4,"enunciado":"Quantas pessoas são necessárias para a associação criminosa do art. 288 do CP?","opcoes":["3 ou mais","4 ou mais","2 ou mais","5 ou mais"],"explicacao":"Já a organização criminosa da Lei 12.850/2013 exige 4 ou mais pessoas."},{"id":184,"materia":"pen","nivel":4,"enunciado":"O erro sobre a ilicitude do fato, se inevitável:","opcoes":["Isenta de pena","Exclui o dolo","Reduz a pena de 1/6 a 1/3","Não tem efeito"],"explicacao":"Art. 21 do CP. Se evitável, a pena diminui de 1/6 a 1/3."},{"id":185,"materia":"pen","nivel":4,"enunciado":"Antes do trânsito em julgado, um crime com pena máxima superior a 12 anos prescreve em:","opcoes":["20 anos","16 anos","12 anos","30 anos"],"explicacao":"Art. 109, I, do Código Penal."},{"id":186,"materia":"ppen","nivel":4,"enunciado":"Quando o juiz dá ao fato definição jurídica diversa da denúncia, sem alterar a descrição do fato, ocorre:","opcoes":["Emendatio libelli","Mutatio libelli","Aditamento obrigatório","Absolvição sumária"],"explicacao":"Art. 383 do CPP. Na mutatio (art. 384), surge prova de elemento não descrito, e o MP adita a denúncia."},{"id":187,"materia":"ppen","nivel":4,"enunciado":"A revisão criminal pode ser pedida:","opcoes":["A qualquer tempo, só em favor do réu","Em até 2 anos do trânsito em julgado","Pelo MP para agravar a pena","Somente antes de extinta a pena"],"explicacao":"Art. 622 do CPP. Cabe antes ou depois de extinta a pena."},{"id":188,"materia":"ppen","nivel":4,"enunciado":"Quantos jurados formam o Conselho de Sentença no Tribunal do Júri?","opcoes":["7","12","25","5"],"explicacao":"São 25 jurados sorteados para a reunião; 7 compõem o Conselho de Sentença."},{"id":189,"materia":"ppen","nivel":4,"enunciado":"A prisão temporária pode ser decretada:","opcoes":["Apenas durante a investigação","Em qualquer fase do processo","Apenas após a sentença","Somente pelo delegado"],"explicacao":"Lei 7.960/89. Ela serve às investigações do inquérito e é decretada pelo juiz."},{"id":190,"materia":"leg","nivel":4,"enunciado":"No tráfico privilegiado (art. 33, § 4º, da Lei de Drogas), a pena pode ser reduzida de:","opcoes":["1/6 a 2/3","1/3 a 1/2","1/6 a 1/3","Metade"],"explicacao":"Exige réu primário, de bons antecedentes, que não se dedique a atividades criminosas nem integre organização criminosa."},{"id":191,"materia":"leg","nivel":4,"enunciado":"Na colaboração premiada (Lei nº 12.850/2013), o juiz pode, entre outros benefícios:","opcoes":["Conceder perdão judicial ou reduzir a pena em até 2/3","Reduzir a pena em no máximo 1/6, sem perdão","Apenas substituir a pena de prisão por multa","Anular o processo e arquivar a investigação"],"explicacao":"Art. 4º. Também pode substituir a pena por restritiva de direitos."},{"id":192,"materia":"leg","nivel":4,"enunciado":"Na Lei de Tortura, a condenação acarreta perda do cargo e interdição para seu exercício pelo:","opcoes":["Dobro do prazo da pena aplicada","Mesmo prazo da pena aplicada","Prazo fixo de 8 anos","Triplo do prazo da pena"],"explicacao":"Art. 1º, § 5º, da Lei 9.455/97."},{"id":193,"materia":"leg","nivel":4,"enunciado":"Na Lei de Tortura, se o crime é cometido por agente público, a pena é aumentada de:","opcoes":["1/6 até 1/3","1/3 até a metade","Metade","2/3"],"explicacao":"Art. 1º, § 4º, I, da Lei 9.455/97."},{"id":194,"materia":"inf","nivel":4,"enunciado":"O DNS serve para:","opcoes":["Traduzir nomes de domínio em endereços IP","Enviar e-mails","Criptografar senhas","Distribuir endereços IP aos computadores"],"explicacao":"Distribuir IPs automaticamente é função do DHCP."},{"id":195,"materia":"inf","nivel":4,"enunciado":"A autenticação em dois fatores combina:","opcoes":["Algo que você sabe e algo que tem ou é","Duas senhas diferentes digitadas","O login e o endereço de e-mail","Dois navegadores abertos juntos"],"explicacao":"Ex.: senha mais código no celular ou biometria."},{"id":196,"materia":"inf","nivel":4,"enunciado":"O RAID 1 é conhecido como:","opcoes":["Espelhamento","Distribuição sem redundância","Paridade distribuída","Compactação"],"explicacao":"Grava os mesmos dados em dois discos. RAID 0 distribui sem redundância; RAID 5 usa paridade distribuída."},{"id":197,"materia":"rl","nivel":4,"enunciado":"Quantos subconjuntos tem um conjunto com 5 elementos?","opcoes":["32","25","10","120"],"explicacao":"Um conjunto com n elementos tem 2ⁿ subconjuntos: 2⁵ = 32."},{"id":198,"materia":"rl","nivel":4,"enunciado":"Quantas linhas tem a tabela-verdade de uma proposição com 4 proposições simples?","opcoes":["16","8","4","32"],"explicacao":"São 2ⁿ linhas: 2⁴ = 16."},{"id":199,"materia":"rl","nivel":4,"enunciado":"Uma urna tem 3 bolas azuis e 2 vermelhas. Retirando 2, sem reposição, qual a probabilidade de ambas serem azuis?","opcoes":["3/10","9/25","3/5","1/5"],"explicacao":"3/5 × 2/4 = 6/20 = 3/10."},{"id":200,"materia":"dh","nivel":4,"enunciado":"Desde quando o Brasil reconhece a competência contenciosa da Corte Interamericana de Direitos Humanos?","opcoes":["1998","1992","1988","2004"],"explicacao":"O Brasil aderiu à Convenção em 1992 e reconheceu a jurisdição da Corte em dezembro de 1998."},{"id":201,"materia":"dh","nivel":4,"enunciado":"O Pacto Internacional sobre Direitos Civis e Políticos foi adotado pela ONU em:","opcoes":["1966","1948","1969","1984"],"explicacao":"Junto com o Pacto sobre Direitos Econômicos, Sociais e Culturais. O Brasil os promulgou em 1992."},{"id":202,"materia":"port","nivel":2,"enunciado":"Complete com o verbo “trazer”: “Ele ___ os documentos ontem.”","opcoes":["trouxe","trazeu","trouxeu","trazi"],"explicacao":"O pretérito perfeito de trazer é irregular: eu trouxe, ele trouxe."},{"id":203,"materia":"port","nivel":2,"enunciado":"Qual frase emprega “onde” corretamente?","opcoes":["A cidade onde nasci é pequena.","Foi uma época onde tudo era difícil.","Aonde você estuda?","Esse é o motivo onde desisti."],"explicacao":"“Onde” só se usa para lugar físico. Para tempo, usa-se “em que”; para motivo, “pelo qual”."},{"id":204,"materia":"port","nivel":2,"enunciado":"Qual é o plural do substantivo “mal”?","opcoes":["Males","Mals","Mais","Maus"],"explicacao":"Como substantivo (“um mal”), o plural é “males”."},{"id":205,"materia":"port","nivel":2,"enunciado":"Em qual frase há pleonasmo vicioso?","opcoes":["Vamos subir para cima.","Ele saiu cedo.","Entrou na sala.","Desceu as escadas."],"explicacao":"Subir já indica ir para cima. A repetição é redundante."},{"id":206,"materia":"port","nivel":3,"enunciado":"Em “Necessito de sua ajuda”, o termo “de sua ajuda” é:","opcoes":["Objeto indireto","Complemento nominal","Adjunto adnominal","Objeto direto"],"explicacao":"Ele completa um VERBO (necessitar) com preposição. Se completasse um nome, seria complemento nominal."},{"id":207,"materia":"port","nivel":3,"enunciado":"Em “Tenho medo de altura”, o termo “de altura” é:","opcoes":["Complemento nominal","Objeto indireto","Adjunto adnominal","Agente da passiva"],"explicacao":"Completa o sentido do substantivo abstrato “medo”, com preposição."},{"id":208,"materia":"port","nivel":3,"enunciado":"Qual frase segue a norma-padrão?","opcoes":["Trouxe o livro para eu ler.","Trouxe o livro para mim ler.","Isso é para mim fazer?","Deixe para mim resolver."],"explicacao":"Antes de verbo no infinitivo, o sujeito usa pronome reto: “para eu ler”."},{"id":209,"materia":"port","nivel":3,"enunciado":"Complete conforme a norma-padrão: “Fazia anos que não ___ concursos na cidade.”","opcoes":["havia","haviam","houveram","existia"],"explicacao":"“Haver” no sentido de existir é impessoal e fica no singular. Com “existir”, o verbo concordaria: “não existiam concursos”."},{"id":210,"materia":"port","nivel":4,"enunciado":"Em qual frase o acento grave está correto?","opcoes":["Refiro-me àquele documento.","Estou disposto à colaborar.","Fui à Portugal nas férias.","Assisti à todas as aulas."],"explicacao":"“Referir-se a” + “aquele” forma “àquele”. Não há crase antes de verbo, de Portugal (sem artigo) nem de “todas”."},{"id":211,"materia":"port","nivel":4,"enunciado":"Em “As estrelas dançavam no céu”, a figura de linguagem é:","opcoes":["Prosopopeia","Metonímia","Eufemismo","Pleonasmo"],"explicacao":"Prosopopeia ou personificação atribui ação humana a seres inanimados."},{"id":212,"materia":"port","nivel":4,"enunciado":"Em “O livro que comprei é ótimo”, a palavra “que” é:","opcoes":["Pronome relativo","Conjunção integrante","Conjunção consecutiva","Partícula expletiva"],"explicacao":"Ela retoma “livro” e pode ser trocada por “o qual”."},{"id":213,"materia":"port","nivel":4,"enunciado":"Qual é a voz passiva analítica de “O delegado ouviu as testemunhas”?","opcoes":["As testemunhas foram ouvidas pelo delegado.","As testemunhas eram ouvidas pelo delegado.","Ouviram-se as testemunhas pelo delegado.","O delegado foi ouvido pelas testemunhas."],"explicacao":"Mantém-se o tempo verbal (pretérito perfeito) e o objeto vira sujeito."},{"id":214,"materia":"const","nivel":2,"enunciado":"O mandado de segurança protege:","opcoes":["Direito líquido e certo não amparado por habeas corpus ou habeas data","A liberdade de locomoção","O patrimônio público, por ação de qualquer cidadão","O acesso a dados pessoais"],"explicacao":"Art. 5º, LXIX."},{"id":215,"materia":"const","nivel":2,"enunciado":"Qual é a idade mínima para concorrer a vereador?","opcoes":["18 anos","21 anos","16 anos","25 anos"],"explicacao":"Art. 14, § 3º, VI, “d”."},{"id":216,"materia":"const","nivel":2,"enunciado":"O brasileiro naturalizado pode ser extraditado em caso de:","opcoes":["Crime comum anterior à naturalização ou tráfico de drogas","Qualquer crime, cometido a qualquer tempo","Crime político ou de opinião","Nunca, em nenhuma hipótese"],"explicacao":"Art. 5º, LI. O brasileiro nato nunca é extraditado."},{"id":217,"materia":"const","nivel":2,"enunciado":"Para reuniões pacíficas, sem armas, em locais abertos ao público, a Constituição exige:","opcoes":["Apenas aviso prévio à autoridade","Autorização prévia da polícia","Autorização judicial","Nada, nem aviso"],"explicacao":"Art. 5º, XVI: independem de autorização, exigido prévio aviso."},{"id":218,"materia":"const","nivel":3,"enunciado":"Qual tribunal julga a Ação Direta de Inconstitucionalidade contra lei federal?","opcoes":["STF","STJ","TSE","Senado Federal"],"explicacao":"Art. 102, I, “a”."},{"id":219,"materia":"const","nivel":3,"enunciado":"Qual quórum se exige para aprovar lei complementar?","opcoes":["Maioria absoluta","Maioria simples","Três quintos","Dois terços"],"explicacao":"Art. 69. Lei ordinária usa maioria simples."},{"id":220,"materia":"const","nivel":3,"enunciado":"Os estados podem instituir regiões metropolitanas por meio de:","opcoes":["Lei complementar estadual","Lei ordinária federal","Decreto do governador","Emenda à Constituição Federal"],"explicacao":"Art. 25, § 3º."},{"id":221,"materia":"const","nivel":3,"enunciado":"Quanto aos direitos políticos, a Constituição:","opcoes":["Veda a cassação, admitindo só perda ou suspensão","Permite a cassação por decisão do Presidente","Permite a cassação por condenação civil","Não trata da perda dos direitos políticos"],"explicacao":"Art. 15. Ex.: condenação criminal transitada em julgado suspende os direitos políticos."},{"id":222,"materia":"const","nivel":4,"enunciado":"São de iniciativa privativa do Presidente as leis que:","opcoes":["Fixem ou modifiquem os efetivos das Forças Armadas","Tratem de direito penal e processual penal","Tratem de direito civil e comercial","Criem feriados nacionais e datas comemorativas"],"explicacao":"Art. 61, § 1º, I."},{"id":223,"materia":"const","nivel":4,"enunciado":"O Presidente tem quantos dias para sancionar ou vetar um projeto, e o que significa o silêncio?","opcoes":["15 dias úteis; o silêncio importa sanção","30 dias; o silêncio importa veto","10 dias úteis; o silêncio importa veto","15 dias corridos; o silêncio arquiva o projeto"],"explicacao":"Art. 66, §§ 1º e 3º."},{"id":224,"materia":"const","nivel":4,"enunciado":"O veto presidencial é derrubado pelo voto de:","opcoes":["Maioria absoluta de deputados e senadores, em sessão conjunta","Dois terços do Senado","Três quintos de cada Casa, separadamente","Maioria simples da Câmara"],"explicacao":"Art. 66, § 4º."},{"id":225,"materia":"const","nivel":4,"enunciado":"Uma CPI é criada a requerimento de:","opcoes":["Um terço dos membros, para fato determinado e por prazo certo","Maioria absoluta, sem prazo","Qualquer parlamentar, para qualquer fato","Dois terços, por prazo indeterminado"],"explicacao":"Art. 58, § 3º."},{"id":226,"materia":"adm","nivel":2,"enunciado":"Qual Súmula Vinculante proíbe o nepotismo na Administração Pública?","opcoes":["Súmula Vinculante 13","Súmula Vinculante 11","Súmula Vinculante 25","Súmula Vinculante 3"],"explicacao":"A SV 13 veda nomear cônjuge, companheiro ou parente até o 3º grau para cargo em comissão."},{"id":227,"materia":"adm","nivel":2,"enunciado":"Qual acumulação remunerada de cargos públicos a Constituição permite, havendo compatibilidade de horários?","opcoes":["Dois cargos de professor","Dois cargos de delegado","Dois cargos técnicos administrativos","Qualquer combinação de cargos"],"explicacao":"Art. 37, XVI: dois de professor; um de professor com outro técnico ou científico; dois de profissionais de saúde regulamentados."},{"id":228,"materia":"adm","nivel":2,"enunciado":"Qual é o prazo de validade de um concurso público?","opcoes":["Até 2 anos, prorrogável uma vez por igual período","Até 5 anos, improrrogável","1 ano, prorrogável indefinidamente","Até 4 anos, improrrogável"],"explicacao":"Art. 37, III."},{"id":229,"materia":"adm","nivel":2,"enunciado":"O servidor nomeado por concurso para cargo efetivo adquire estabilidade após:","opcoes":["3 anos de efetivo exercício","2 anos de efetivo exercício","1 ano","5 anos"],"explicacao":"Art. 41, com avaliação especial de desempenho."},{"id":230,"materia":"adm","nivel":3,"enunciado":"Qual destas NÃO é forma de o servidor estável perder o cargo?","opcoes":["Decisão do chefe imediato, sem processo","Sentença judicial transitada em julgado","Processo administrativo com ampla defesa","Avaliação periódica de desempenho, com ampla defesa"],"explicacao":"Art. 41, § 1º."},{"id":231,"materia":"adm","nivel":3,"enunciado":"Na Lei nº 8.112/1990, a sindicância pode resultar em suspensão de até:","opcoes":["30 dias","90 dias","15 dias","60 dias"],"explicacao":"Art. 145. Se a penalidade cabível for maior, instaura-se o processo disciplinar."},{"id":232,"materia":"adm","nivel":3,"enunciado":"Qual é o prazo para concluir o processo administrativo disciplinar na Lei nº 8.112/1990?","opcoes":["60 dias, prorrogáveis por igual prazo","30 dias, improrrogáveis","90 dias, prorrogáveis por 30","120 dias, improrrogáveis"],"explicacao":"Art. 152."},{"id":233,"materia":"adm","nivel":3,"enunciado":"As responsabilidades civil, penal e administrativa do servidor são:","opcoes":["Independentes entre si","Sempre dependentes da esfera penal","Excludentes: só se aplica uma","Subordinadas à esfera civil"],"explicacao":"Art. 125 da Lei 8.112. Podem ser aplicadas cumulativamente."},{"id":234,"materia":"adm","nivel":4,"enunciado":"A responsabilidade administrativa do servidor é afastada quando a absolvição criminal:","opcoes":["Negar a existência do fato ou da autoria","Ocorrer por falta de provas","Reconhecer a prescrição","Aplicar a insignificância"],"explicacao":"Art. 126 da Lei 8.112."},{"id":235,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 14.133/2021, qual modalidade serve à escolha de trabalho técnico, científico ou artístico?","opcoes":["Concurso","Leilão","Pregão","Diálogo competitivo"],"explicacao":"O concurso premia o vencedor. O leilão serve à alienação de bens."},{"id":236,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 8.112/1990, a ação disciplinar para infrações punidas com demissão prescreve em:","opcoes":["5 anos","2 anos","180 dias","10 anos"],"explicacao":"Art. 142, I. Suspensão prescreve em 2 anos e advertência em 180 dias."},{"id":237,"materia":"adm","nivel":4,"enunciado":"Para o Estado exercer o direito de regresso contra o agente que causou o dano, é preciso provar:","opcoes":["Dolo ou culpa do agente","Apenas o nexo causal","Apenas o dano","Nada, o regresso é automático"],"explicacao":"Art. 37, § 6º. A responsabilidade do Estado é objetiva; a do agente, subjetiva."},{"id":238,"materia":"pen","nivel":2,"enunciado":"Imputar falsamente a alguém fato definido como crime é:","opcoes":["Calúnia","Difamação","Injúria","Denunciação caluniosa"],"explicacao":"Art. 138. Difamação imputa fato ofensivo à reputação; injúria ofende a dignidade sem imputar fato."},{"id":239,"materia":"pen","nivel":2,"enunciado":"Chamar alguém de “ladrão” em uma discussão, sem atribuir fato específico, configura em tese:","opcoes":["Injúria","Calúnia","Difamação","Ameaça"],"explicacao":"Sem um fato determinado, há só xingamento: injúria (art. 140)."},{"id":240,"materia":"pen","nivel":2,"enunciado":"O falso testemunho é crime contra:","opcoes":["A administração da justiça","A fé pública","A pessoa","O patrimônio"],"explicacao":"Está no art. 342 do CP, no capítulo dos crimes contra a administração da justiça."},{"id":241,"materia":"pen","nivel":2,"enunciado":"A lei penal posterior que de qualquer modo favorece o agente:","opcoes":["Retroage e se aplica a fatos anteriores","Só vale para fatos futuros","Só retroage antes da sentença","Nunca retroage"],"explicacao":"Art. 2º, parágrafo único, do CP. Vale até após o trânsito em julgado."},{"id":242,"materia":"pen","nivel":3,"enunciado":"Na abolitio criminis, o que acontece com os efeitos civis da sentença condenatória?","opcoes":["Permanecem","Desaparecem junto com os penais","São reduzidos à metade","Dependem de nova ação"],"explicacao":"Art. 2º do CP: cessam a execução e os efeitos penais. A obrigação de indenizar continua."},{"id":243,"materia":"pen","nivel":3,"enunciado":"Matar alguém por motivo insignificante, desproporcional, qualifica o homicídio por motivo:","opcoes":["Fútil","Torpe","Relevante valor moral","De violenta emoção"],"explicacao":"Torpe é o repugnante, como matar por herança. Relevante valor moral é causa de diminuição."},{"id":244,"materia":"pen","nivel":3,"enunciado":"Matar o próprio filho, sob influência do estado puerperal, durante o parto ou logo após, é:","opcoes":["Infanticídio","Homicídio qualificado","Aborto","Homicídio culposo"],"explicacao":"Art. 123 do Código Penal."},{"id":245,"materia":"pen","nivel":3,"enunciado":"O princípio da insignificância, quando aplicado, exclui a:","opcoes":["Tipicidade material","Culpabilidade","Ilicitude","Punibilidade apenas"],"explicacao":"O fato é formalmente típico, mas a lesão ao bem jurídico é ínfima."},{"id":246,"materia":"pen","nivel":4,"enunciado":"Quanto ao nexo causal, o art. 13 do Código Penal adota como regra a teoria da:","opcoes":["Equivalência dos antecedentes","Causalidade adequada","Imputação objetiva","Relevância jurídica"],"explicacao":"Também chamada conditio sine qua non: causa é toda ação ou omissão sem a qual o resultado não teria ocorrido."},{"id":247,"materia":"pen","nivel":4,"enunciado":"A embriaguez voluntária ou culposa, pelo álcool ou substância análoga:","opcoes":["Não exclui a imputabilidade penal","Exclui a imputabilidade","Sempre reduz a pena","Isenta de pena se completa"],"explicacao":"Art. 28, II, do CP. Só a embriaguez completa por caso fortuito ou força maior isenta de pena."},{"id":248,"materia":"pen","nivel":4,"enunciado":"Quem tinha o dever legal de enfrentar o perigo pode alegar estado de necessidade?","opcoes":["Não","Sim, sempre","Sim, se o perigo for atual","Sim, se agir para salvar a si mesmo"],"explicacao":"Art. 24, § 1º. Ex.: o bombeiro em serviço não pode fugir do incêndio alegando estado de necessidade."},{"id":249,"materia":"pen","nivel":4,"enunciado":"Quem induz alguém a erro sobre o fato e o faz praticar o crime responde como:","opcoes":["Autor mediato","Partícipe","Coautor","Não responde"],"explicacao":"Art. 20, § 2º, do CP: responde pelo crime o terceiro que determina o erro."},{"id":250,"materia":"ppen","nivel":2,"enunciado":"Em quanto tempo o preso em flagrante deve receber a nota de culpa?","opcoes":["24 horas","48 horas","72 horas","5 dias"],"explicacao":"Art. 306, § 2º, do CPP."},{"id":251,"materia":"ppen","nivel":2,"enunciado":"É preso logo depois do crime, com armas ou objetos que façam presumir ser ele o autor. Esse flagrante é chamado de:","opcoes":["Presumido (ficto)","Próprio","Impróprio (quase-flagrante)","Preparado"],"explicacao":"Art. 302, IV. No impróprio (inciso III), o agente é perseguido logo após o crime."},{"id":252,"materia":"ppen","nivel":2,"enunciado":"O inquérito policial é indispensável para oferecer denúncia?","opcoes":["Não, se houver elementos suficientes por outro meio","Sim, em todos os crimes, sem exceção","Sim, salvo nos crimes hediondos","Só é dispensável nos crimes de ação privada"],"explicacao":"O inquérito é dispensável (art. 39, § 5º, e art. 46, § 1º, do CPP)."},{"id":253,"materia":"ppen","nivel":2,"enunciado":"Perseguido logo após o crime, em situação que faça presumir a autoria, o agente está em flagrante:","opcoes":["Impróprio (quase-flagrante)","Próprio (flagrante real)","Presumido (ficto)","Diferido (retardado)"],"explicacao":"Art. 302, III, do CPP."},{"id":254,"materia":"ppen","nivel":3,"enunciado":"Segundo a Súmula 145 do STF, quando a preparação do flagrante pela polícia torna impossível a consumação:","opcoes":["Não há crime","Há crime consumado","Há tentativa punível","Há crime culposo"],"explicacao":"É o flagrante preparado ou provocado, ligado ao crime impossível."},{"id":255,"materia":"ppen","nivel":3,"enunciado":"Nos crimes que deixam vestígios, o exame de corpo de delito:","opcoes":["É indispensável e não pode ser suprido pela confissão","Pode ser substituído pela confissão","É facultativo","Só é exigido em homicídios"],"explicacao":"Art. 158 do CPP. Desaparecidos os vestígios, a prova testemunhal pode supri-lo (art. 167)."},{"id":256,"materia":"ppen","nivel":3,"enunciado":"A representação do ofendido será irretratável depois de:","opcoes":["Oferecida a denúncia","Recebida a denúncia","Instaurado o inquérito","Proferida a sentença"],"explicacao":"Art. 25 do CPP. Na Lei Maria da Penha, a renúncia é em audiência perante o juiz, antes do recebimento da denúncia."},{"id":257,"materia":"ppen","nivel":3,"enunciado":"A ação controlada, que permite retardar o flagrante para colher mais provas, está prevista na lei de:","opcoes":["Organizações criminosas (Lei 12.850/2013)","Juizados Especiais (Lei 9.099/1995)","Abuso de autoridade (Lei 13.869/2019)","Crimes hediondos (Lei 8.072/1990)"],"explicacao":"Art. 8º da Lei 12.850/2013. A Lei de Drogas também a admite."},{"id":258,"materia":"ppen","nivel":4,"enunciado":"A perempção é causa de extinção da punibilidade própria da ação penal:","opcoes":["Privada","Pública incondicionada","Pública condicionada","De qualquer espécie"],"explicacao":"Art. 60 do CPP. Ex.: o querelante deixa de promover o andamento por 30 dias seguidos."},{"id":259,"materia":"ppen","nivel":4,"enunciado":"O princípio da indivisibilidade está previsto expressamente no CPP para a ação penal:","opcoes":["Privada","Pública incondicionada","Pública condicionada","Popular"],"explicacao":"Art. 48: a queixa contra um dos autores obriga ao processo de todos."},{"id":260,"materia":"ppen","nivel":4,"enunciado":"Como regra, qual sistema de apreciação das provas o CPP adota?","opcoes":["Livre convencimento motivado","Íntima convicção","Prova tarifada","Certeza moral do legislador"],"explicacao":"Art. 155. No Tribunal do Júri, os jurados decidem por íntima convicção."},{"id":261,"materia":"ppen","nivel":4,"enunciado":"Segundo o CPP, o exame pericial é realizado, em regra, por:","opcoes":["Perito oficial com diploma de curso superior","Dois peritos leigos nomeados pelo delegado","O próprio delegado responsável pelo caso","Qualquer servidor da polícia civil"],"explicacao":"Art. 159. Na falta de perito oficial, duas pessoas idôneas com diploma superior."},{"id":262,"materia":"leg","nivel":2,"enunciado":"Segundo a Lei nº 8.072/1990, os crimes hediondos são insuscetíveis de:","opcoes":["Anistia, graça, indulto e fiança","Progressão de regime","Liberdade provisória","Qualquer recurso"],"explicacao":"Art. 2º da Lei 8.072/90."},{"id":263,"materia":"leg","nivel":2,"enunciado":"Qual destas é medida protetiva de urgência da Lei Maria da Penha?","opcoes":["Afastamento do agressor do lar","Prisão perpétua","Multa ao município","Perda automática da nacionalidade"],"explicacao":"Art. 22, II. Há ainda proibição de aproximação e de contato, entre outras."},{"id":264,"materia":"leg","nivel":2,"enunciado":"Na Lei nº 9.099/1995, quem propõe a transação penal?","opcoes":["O Ministério Público","O juiz, de ofício","O delegado","A vítima"],"explicacao":"Art. 76."},{"id":265,"materia":"leg","nivel":2,"enunciado":"Pelo Estatuto do Desarmamento, qual a idade mínima para adquirir arma de fogo?","opcoes":["25 anos","18 anos","21 anos","30 anos"],"explicacao":"Art. 28 da Lei 10.826/2003, com ressalvas para alguns profissionais."},{"id":266,"materia":"leg","nivel":3,"enunciado":"A suspensão condicional do processo (art. 89 da Lei nº 9.099/1995) cabe nos crimes com pena mínima:","opcoes":["Igual ou inferior a 1 ano","Inferior a 2 anos","Igual ou inferior a 4 anos","Inferior a 6 meses"],"explicacao":"O período de prova vai de 2 a 4 anos."},{"id":267,"materia":"leg","nivel":3,"enunciado":"Aos crimes com violência doméstica e familiar contra a mulher:","opcoes":["Não se aplica a Lei nº 9.099/1995","Aplica-se a transação penal","Aplica-se sempre a suspensão do processo","Aplica-se o rito do juizado especial"],"explicacao":"Art. 41 da Lei Maria da Penha."},{"id":268,"materia":"leg","nivel":3,"enunciado":"Oferecer droga eventualmente, sem lucro, a pessoa do seu relacionamento, para consumirem juntos, tem pena de:","opcoes":["Detenção de 6 meses a 1 ano e multa","Reclusão de 5 a 15 anos","Apenas advertência","Reclusão de 2 a 4 anos"],"explicacao":"Art. 33, § 3º, da Lei de Drogas."},{"id":269,"materia":"leg","nivel":3,"enunciado":"Qual destes NÃO está no rol de crimes hediondos do art. 1º da Lei nº 8.072/1990?","opcoes":["Tráfico de drogas","Latrocínio","Estupro","Extorsão mediante sequestro"],"explicacao":"O tráfico é EQUIPARADO a hediondo (art. 2º e CF, art. 5º, XLIII), mas não está no rol do art. 1º."},{"id":270,"materia":"leg","nivel":3,"enunciado":"Quem se omite diante da tortura quando tinha o dever de evitá-la ou apurá-la responde com pena de:","opcoes":["Detenção de 1 a 4 anos","Reclusão de 2 a 8 anos","Reclusão de 8 a 16 anos","Não responde"],"explicacao":"Art. 1º, § 2º, da Lei 9.455/97."},{"id":271,"materia":"leg","nivel":4,"enunciado":"Na Lei nº 12.850/2013, a infiltração de agentes é autorizada por até:","opcoes":["6 meses, renováveis se comprovada a necessidade","30 dias, improrrogáveis em qualquer caso","1 ano, sem possibilidade de renovação","90 dias, renováveis uma única vez"],"explicacao":"Art. 10, § 3º."},{"id":272,"materia":"leg","nivel":4,"enunciado":"Qual é a lei que trata da lavagem de dinheiro?","opcoes":["Lei nº 9.613/1998","Lei nº 12.850/2013","Lei nº 8.137/1990","Lei nº 7.492/1986"],"explicacao":"A 8.137/90 trata de crimes contra a ordem tributária e a 7.492/86, de crimes contra o sistema financeiro."},{"id":273,"materia":"leg","nivel":4,"enunciado":"Após a Lei nº 14.994/2024, descumprir medida protetiva da Lei Maria da Penha tem pena de:","opcoes":["Reclusão de 2 a 5 anos e multa","Detenção de 3 meses a 2 anos","Apenas multa","Reclusão de 1 a 3 anos"],"explicacao":"Art. 24-A da Lei 11.340/2006, com a redação do pacote antifeminicídio."},{"id":274,"materia":"leg","nivel":4,"enunciado":"Os crimes da Lei de Abuso de Autoridade são de ação penal:","opcoes":["Pública incondicionada","Pública condicionada à representação","Privada","Privada personalíssima"],"explicacao":"Art. 3º da Lei 13.869/2019. Admite ação privada subsidiária se o MP não agir no prazo."},{"id":275,"materia":"leg","nivel":4,"enunciado":"Qual a pena do porte ilegal de arma de fogo de uso RESTRITO (art. 16 do Estatuto do Desarmamento)?","opcoes":["Reclusão de 3 a 6 anos e multa","Reclusão de 2 a 4 anos e multa","Detenção de 1 a 3 anos e multa","Reclusão de 4 a 12 anos"],"explicacao":"Se a arma for de uso proibido, a pena sobe para reclusão de 4 a 12 anos (§ 2º)."},{"id":276,"materia":"inf","nivel":2,"enunciado":"Qual memória é volátil e perde os dados ao desligar o computador?","opcoes":["RAM","ROM","SSD","HD"],"explicacao":"A RAM guarda temporariamente o que está em uso. ROM, SSD e HD mantêm os dados."},{"id":277,"materia":"inf","nivel":2,"enunciado":"O que é spam?","opcoes":["Mensagem não solicitada enviada em massa","Memória temporária usada pelo navegador","Navegador com proteção reforçada","Backup automático da caixa de entrada"],"explicacao":"Muito spam também carrega golpes de phishing."},{"id":278,"materia":"inf","nivel":2,"enunciado":"A função CONT.SE do Excel:","opcoes":["Conta as células que atendem a um critério","Soma valores de um intervalo","Calcula a média","Procura valores em outra coluna"],"explicacao":"Ex.: =CONT.SE(A1:A10;“>5”)."},{"id":279,"materia":"inf","nivel":2,"enunciado":"Engenharia social, em segurança da informação, é:","opcoes":["Manipular pessoas para obter informações ou acessos","Construir e organizar redes de computadores","Programar sistemas para redes sociais","Fazer backup de dados em nuvem"],"explicacao":"Explora a confiança humana, e não falhas técnicas."},{"id":280,"materia":"inf","nivel":3,"enunciado":"Qual protocolo de e-mail mantém as mensagens no servidor e sincroniza as pastas entre dispositivos?","opcoes":["IMAP","POP3","SMTP","FTP"],"explicacao":"O POP3 costuma baixar e apagar do servidor. O SMTP é para envio."},{"id":281,"materia":"inf","nivel":3,"enunciado":"Cookie, na navegação web, é:","opcoes":["Arquivo que o site grava no navegador","Tipo de vírus que infecta páginas","Protocolo de envio de e-mail","Cabo usado em redes locais"],"explicacao":"Guarda preferências, sessões de login e dados de rastreamento."},{"id":282,"materia":"inf","nivel":3,"enunciado":"Um backdoor é:","opcoes":["Um meio de o invasor voltar a um sistema","Uma cópia de segurança dos arquivos","Um firewall instalado na borda da rede","Uma porta USB traseira do computador"],"explicacao":"Ele permite acesso remoto sem passar pela autenticação normal."},{"id":283,"materia":"inf","nivel":3,"enunciado":"Um keylogger é um programa que:","opcoes":["Registra as teclas digitadas","Bloqueia sites indesejados","Acelera a digitação no teclado","Criptografa o disco rígido"],"explicacao":"É usado para roubar senhas e dados bancários."},{"id":284,"materia":"inf","nivel":4,"enunciado":"O protocolo DHCP serve para:","opcoes":["Atribuir endereços IP automaticamente aos dispositivos","Traduzir nomes de domínio","Enviar e-mails","Transferir arquivos com criptografia"],"explicacao":"Traduzir nomes de domínio é função do DNS."},{"id":285,"materia":"inf","nivel":4,"enunciado":"Uma função de hash criptográfico é usada principalmente para garantir:","opcoes":["Integridade","Disponibilidade","Confidencialidade","Velocidade de transmissão"],"explicacao":"Qualquer alteração no arquivo gera um hash diferente."},{"id":286,"materia":"inf","nivel":4,"enunciado":"Uma botnet é:","opcoes":["Rede de computadores infectados e controlados","Antivírus que funciona na nuvem","Robô de atendimento automático","Rede privada virtual criptografada"],"explicacao":"É usada em ataques de negação de serviço (DDoS) e envio de spam."},{"id":287,"materia":"inf","nivel":4,"enunciado":"No Excel, qual o resultado de =ESQUERDA(“CONCURSO”;3)?","opcoes":["CON","SO","CONC","RSO"],"explicacao":"ESQUERDA retorna os primeiros caracteres do texto."},{"id":288,"materia":"rl","nivel":2,"enunciado":"Qual o próximo número da sequência 1, 1, 2, 3, 5, 8, …?","opcoes":["13","11","12","16"],"explicacao":"É a sequência de Fibonacci: cada termo é a soma dos dois anteriores (5 + 8 = 13)."},{"id":289,"materia":"rl","nivel":2,"enunciado":"Qual é a negação de “Algum aluno faltou”?","opcoes":["Nenhum aluno faltou","Todos os alunos faltaram","Algum aluno não faltou","Todo aluno faltou"],"explicacao":"Negar a existência de “algum” equivale a dizer “nenhum”."},{"id":290,"materia":"rl","nivel":2,"enunciado":"Um preço sobe 20% e depois cai 20%. Em relação ao preço inicial, o resultado final é:","opcoes":["Uma queda de 4%","O mesmo preço","Uma alta de 4%","Uma queda de 2%"],"explicacao":"1,2 × 0,8 = 0,96. Ou seja, 4% abaixo do inicial."},{"id":291,"materia":"rl","nivel":2,"enunciado":"Para ter média 7 em três provas, quem tirou 6 e 8 precisa tirar quanto na terceira?","opcoes":["7","8","6","9"],"explicacao":"A soma precisa ser 21. 21 − 6 − 8 = 7."},{"id":292,"materia":"rl","nivel":3,"enunciado":"A bicondicional “P se e somente se Q” é verdadeira quando:","opcoes":["P e Q têm o mesmo valor lógico","Apenas P é verdadeira","Apenas Q é verdadeira","P e Q têm valores diferentes"],"explicacao":"Verdadeira se ambas forem V ou ambas forem F."},{"id":293,"materia":"rl","nivel":3,"enunciado":"De quantas formas 5 pessoas podem sentar em volta de uma mesa redonda?","opcoes":["24","120","60","25"],"explicacao":"Permutação circular: (5 − 1)! = 4! = 24."},{"id":294,"materia":"rl","nivel":3,"enunciado":"Um produto comprado por R$ 80,00 foi vendido por R$ 100,00. Qual foi o lucro sobre o custo?","opcoes":["25%","20%","80%","15%"],"explicacao":"Lucro de 20 sobre custo de 80: 20/80 = 25%."},{"id":295,"materia":"rl","nivel":3,"enunciado":"Qual é a negação de “João é alto ou Maria é baixa”?","opcoes":["João não é alto e Maria não é baixa","João não é alto ou Maria não é baixa","João é baixo ou Maria é alta","João é alto e Maria é baixa"],"explicacao":"De Morgan: ¬(P ∨ Q) = ¬P ∧ ¬Q."},{"id":296,"materia":"rl","nivel":4,"enunciado":"“Se P, então Q” é equivalente a:","opcoes":["Não P ou Q","P ou não Q","P e não Q","Não P e Q"],"explicacao":"Uma condicional só é falsa com P verdadeira e Q falsa. Isso é o mesmo comportamento de ¬P ∨ Q."},{"id":297,"materia":"rl","nivel":4,"enunciado":"Com os algarismos 1, 2, 3, 4 e 5, quantos números PARES de 3 algarismos distintos podem ser formados?","opcoes":["24","60","36","48"],"explicacao":"O último algarismo só pode ser 2 ou 4 (2 opções). Sobram 4 e depois 3: 2 × 4 × 3 = 24."},{"id":298,"materia":"rl","nivel":4,"enunciado":"Qual a probabilidade de tirar um ás de um baralho comum de 52 cartas?","opcoes":["1/13","1/52","4/13","1/4"],"explicacao":"São 4 ases em 52 cartas: 4/52 = 1/13."},{"id":299,"materia":"rl","nivel":4,"enunciado":"Descontos sucessivos de 10% e 20% equivalem a um desconto único de:","opcoes":["28%","30%","25%","32%"],"explicacao":"0,9 × 0,8 = 0,72. Restam 72% do preço, ou seja, 28% de desconto."},{"id":300,"materia":"dh","nivel":2,"enunciado":"Os direitos de segunda dimensão correspondem aos direitos:","opcoes":["Sociais, econômicos e culturais","Civis e políticos","De solidariedade","Digitais"],"explicacao":"Ligados à igualdade, exigem prestações do Estado, como saúde e educação."},{"id":301,"materia":"dh","nivel":2,"enunciado":"Os direitos de terceira dimensão estão ligados ao valor da:","opcoes":["Fraternidade (solidariedade)","Liberdade individual","Igualdade material","Propriedade"],"explicacao":"Ex.: meio ambiente equilibrado, paz e desenvolvimento."},{"id":302,"materia":"dh","nivel":2,"enunciado":"Onde fica a sede da Comissão Interamericana de Direitos Humanos?","opcoes":["Washington, EUA","San José, Costa Rica","Genebra, Suíça","Nova York, EUA"],"explicacao":"A Corte Interamericana é que fica em San José."},{"id":303,"materia":"dh","nivel":2,"enunciado":"O princípio da proibição do retrocesso social impede que o Estado:","opcoes":["Suprima direitos sociais já conquistados","Crie novos direitos sociais por lei","Aumente impostos para custear serviços","Reforme a Constituição por emenda"],"explicacao":"Também chamado efeito cliquet."},{"id":304,"materia":"dh","nivel":3,"enunciado":"Segundo o STF, tratados de direitos humanos aprovados SEM o rito do art. 5º, § 3º, têm status:","opcoes":["Supralegal","Constitucional","De lei ordinária","De decreto"],"explicacao":"Ficam acima das leis e abaixo da Constituição (RE 466.343, de 2008)."},{"id":305,"materia":"dh","nivel":3,"enunciado":"A Lei nº 9.474/1997 trata:","opcoes":["Do Estatuto dos Refugiados","Do Estatuto da Pessoa Idosa","Da Lei de Tortura","Da Lei de Migração"],"explicacao":"Ela criou o Conare. A Lei de Migração é a 13.445/2017."},{"id":306,"materia":"dh","nivel":3,"enunciado":"Segundo a Convenção da ONU sobre os Direitos da Criança, criança é todo ser humano com menos de:","opcoes":["18 anos","12 anos","14 anos","16 anos"],"explicacao":"Difere do ECA, em que criança vai até 12 anos incompletos."},{"id":307,"materia":"dh","nivel":3,"enunciado":"O incidente de deslocamento de competência para a Justiça Federal, em graves violações de direitos humanos, é suscitado pelo PGR perante o:","opcoes":["STJ","STF","TSE","CNJ"],"explicacao":"Art. 109, § 5º, da CF, incluído pela EC 45/2004."},{"id":308,"materia":"dh","nivel":3,"enunciado":"Os direitos humanos são indivisíveis, o que significa que:","opcoes":["Formam um todo interdependente, sem hierarquia","Só valem para quem é cidadão do país","Podem ser negociados entre os Estados","Valem apenas em tempos de paz"],"explicacao":"Direitos civis e sociais se complementam."},{"id":309,"materia":"dh","nivel":4,"enunciado":"Para peticionar à Comissão Interamericana, em regra, é necessário:","opcoes":["Ter esgotado os recursos internos","Ser advogado","Ser cidadão do Estado acusado","Ter autorização do governo"],"explicacao":"Art. 46 da Convenção Americana, com exceções, como demora injustificada."},{"id":310,"materia":"dh","nivel":4,"enunciado":"Quem pode submeter um caso à Corte Interamericana de Direitos Humanos?","opcoes":["Somente os Estados Partes e a Comissão","Qualquer pessoa diretamente","Apenas ONGs","Apenas a ONU"],"explicacao":"Art. 61 da Convenção Americana."},{"id":311,"materia":"dh","nivel":4,"enunciado":"Qual foi o primeiro caso em que o Brasil foi condenado pela Corte Interamericana?","opcoes":["Caso Ximenes Lopes","Caso Gomes Lund","Caso Maria da Penha","Caso Favela Nova Brasília"],"explicacao":"Em 2006, pela morte de Damião Ximenes Lopes em clínica psiquiátrica."},{"id":312,"materia":"dh","nivel":4,"enunciado":"A Lei Maria da Penha teve origem em recomendação feita ao Brasil pela:","opcoes":["Comissão Interamericana de Direitos Humanos","Corte Internacional de Justiça","Assembleia Geral da ONU","Corte Interamericana de Direitos Humanos"],"explicacao":"O caso foi analisado pela Comissão, que em 2001 responsabilizou o Brasil por omissão. Não chegou à Corte."},{"id":313,"materia":"dh","nivel":2,"enunciado":"A Constituição admite a pena de morte apenas:","opcoes":["Em caso de guerra declarada","Para crimes hediondos","Para reincidentes","Nunca, em nenhuma hipótese"],"explicacao":"Art. 5º, XLVII, “a”."},{"id":314,"materia":"dh","nivel":2,"enunciado":"Qual destas penas é ADMITIDA pela Constituição?","opcoes":["Perda de bens","Banimento","Trabalhos forçados","Caráter perpétuo"],"explicacao":"Art. 5º, XLVI, “b”. As demais são proibidas pelo inciso XLVII."},{"id":315,"materia":"dh","nivel":2,"enunciado":"A Constituição assegura às presidiárias condições para permanecer com seus filhos durante o período de:","opcoes":["Amamentação","Toda a infância","Até o fim da pena","Até os 12 anos da criança"],"explicacao":"Art. 5º, L."},{"id":316,"materia":"dh","nivel":2,"enunciado":"Segundo a Constituição, ninguém será considerado culpado até:","opcoes":["O trânsito em julgado da sentença condenatória","O recebimento da denúncia pelo juiz","O indiciamento no inquérito policial","A sentença condenatória de primeiro grau"],"explicacao":"Art. 5º, LVII: presunção de inocência."},{"id":317,"materia":"dh","nivel":3,"enunciado":"O preso tem direito, segundo a Constituição, à identificação:","opcoes":["Dos responsáveis por sua prisão ou por seu interrogatório policial","Do nome de todas as testemunhas antes do inquérito","Do juiz que julgará o caso, já no flagrante","Do promotor que fará a denúncia"],"explicacao":"Art. 5º, LXIV."},{"id":318,"materia":"dh","nivel":3,"enunciado":"A Lei nº 13.445/2017 é conhecida como:","opcoes":["Lei de Migração","Estatuto dos Refugiados","Lei de Abuso de Autoridade","Estatuto da Igualdade Racial"],"explicacao":"Substituiu o antigo Estatuto do Estrangeiro, de 1980."},{"id":319,"materia":"dh","nivel":3,"enunciado":"A Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher (CEDAW) foi adotada pela ONU em:","opcoes":["1979","1948","1994","2006"],"explicacao":"Foi promulgada no Brasil em 2002."},{"id":320,"materia":"dh","nivel":3,"enunciado":"A Convenção de Belém do Pará, da OEA, trata de:","opcoes":["Prevenir, punir e erradicar a violência contra a mulher","Garantir direitos dos povos indígenas da América","Proteger o meio ambiente nos países-membros","Combater a corrupção na administração pública"],"explicacao":"É de 1994, no sistema interamericano."},{"id":321,"materia":"dh","nivel":4,"enunciado":"No Brasil, a Convenção sobre os Direitos das Pessoas com Deficiência tem status de:","opcoes":["Emenda constitucional","Lei ordinária","Norma supralegal","Decreto regulamentar"],"explicacao":"Foi o primeiro tratado aprovado pelo rito do art. 5º, § 3º."},{"id":322,"materia":"dh","nivel":4,"enunciado":"Qual tratado também foi aprovado no Brasil com status de emenda constitucional?","opcoes":["Tratado de Marraqueche","Pacto de San José da Costa Rica","CEDAW","Convenção da ONU contra a Tortura"],"explicacao":"Ele facilita o acesso de pessoas cegas ou com deficiência visual a obras publicadas. O Pacto de San José tem status supralegal."},{"id":323,"materia":"dh","nivel":4,"enunciado":"O Protocolo de San Salvador, no sistema interamericano, trata de:","opcoes":["Direitos econômicos, sociais e culturais","Abolição da pena de morte","Direitos das crianças","Refugiados"],"explicacao":"É o protocolo adicional à Convenção Americana de 1988."},{"id":324,"materia":"dh","nivel":4,"enunciado":"Em casos de extrema gravidade e urgência, a Corte Interamericana pode adotar:","opcoes":["Medidas provisórias","Intervenção federal","Sanções econômicas","Prisão de autoridades"],"explicacao":"Art. 63.2 da Convenção Americana. A Comissão adota medidas cautelares."},{"id":325,"materia":"leg","nivel":2,"enunciado":"Se o autor de infração de menor potencial ofensivo for encaminhado ao juizado ou se comprometer a comparecer:","opcoes":["Não se impõe prisão em flagrante nem fiança","Será preso em flagrante normalmente","Pagará fiança fixada pelo delegado","Responderá preso até a audiência"],"explicacao":"Art. 69, parágrafo único, da Lei 9.099/95."},{"id":326,"materia":"leg","nivel":2,"enunciado":"Pelo ECA, a internação de adolescente não pode passar de:","opcoes":["3 anos","1 ano","5 anos","2 anos"],"explicacao":"Art. 121, § 3º. A liberação é compulsória aos 21 anos."},{"id":327,"materia":"leg","nivel":2,"enunciado":"Pelo ECA, ato infracional é:","opcoes":["Conduta descrita como crime ou contravenção penal","Qualquer desobediência aos pais","Falta escolar grave","Infração de trânsito"],"explicacao":"Art. 103 do ECA."},{"id":328,"materia":"leg","nivel":2,"enunciado":"As penas por porte de droga para consumo pessoal (art. 28 da Lei de Drogas) prescrevem em:","opcoes":["2 anos","4 anos","1 ano","6 meses"],"explicacao":"Art. 30 da Lei 11.343/2006."},{"id":329,"materia":"leg","nivel":3,"enunciado":"Na Lei nº 9.099/1995, a composição civil dos danos homologada, em ação privada ou pública condicionada, acarreta:","opcoes":["Renúncia ao direito de queixa ou representação","Condenação do autor","Suspensão do processo por 2 anos","Prisão preventiva"],"explicacao":"Art. 74, parágrafo único."},{"id":330,"materia":"leg","nivel":3,"enunciado":"O homicídio simples é considerado hediondo quando praticado:","opcoes":["Em atividade típica de grupo de extermínio","Contra qualquer pessoa, sem distinção","Com emprego de arma de fogo de uso permitido","Durante o repouso noturno da vítima"],"explicacao":"Art. 1º, I, da Lei 8.072/90."},{"id":331,"materia":"leg","nivel":3,"enunciado":"Qual a pena do crime de organização criminosa (art. 2º da Lei nº 12.850/2013)?","opcoes":["Reclusão de 3 a 8 anos e multa","Reclusão de 1 a 3 anos","Reclusão de 5 a 15 anos","Detenção de 2 a 4 anos"],"explicacao":"A pena é aumentada se houver emprego de arma de fogo."},{"id":332,"materia":"leg","nivel":3,"enunciado":"A associação para o tráfico (art. 35 da Lei de Drogas) exige no mínimo:","opcoes":["2 pessoas","3 pessoas","4 pessoas","5 pessoas"],"explicacao":"Basta que duas ou mais pessoas se associem para traficar, de forma estável."},{"id":333,"materia":"leg","nivel":4,"enunciado":"Após a Lei nº 14.550/2023, as medidas protetivas da Lei Maria da Penha podem ser concedidas:","opcoes":["Mesmo sem inquérito, ação penal ou boletim","Apenas após o oferecimento da denúncia","Apenas com laudo pericial da lesão","Apenas se houver lesão corporal grave"],"explicacao":"Art. 19, § 5º, da Lei 11.340/2006."},{"id":334,"materia":"leg","nivel":4,"enunciado":"Qual é a pena do crime de lavagem de dinheiro?","opcoes":["Reclusão de 3 a 10 anos e multa","Reclusão de 1 a 4 anos","Detenção de 2 a 6 anos","Reclusão de 5 a 15 anos"],"explicacao":"Art. 1º da Lei 9.613/1998."},{"id":335,"materia":"leg","nivel":4,"enunciado":"Na Lei de Abuso de Autoridade, a perda do cargo como efeito da condenação depende de:","opcoes":["Reincidência em abuso e declaração motivada na sentença","Qualquer condenação, de forma automática","Pedido expresso da vítima no processo","Pena aplicada superior a 8 anos"],"explicacao":"Art. 4º, parágrafo único, da Lei 13.869/2019."},{"id":336,"materia":"leg","nivel":4,"enunciado":"Qual é a pena da associação para o tráfico (art. 35 da Lei de Drogas)?","opcoes":["Reclusão de 3 a 10 anos e multa","Reclusão de 5 a 15 anos","Detenção de 1 a 3 anos","Reclusão de 8 a 20 anos"],"explicacao":"A mesma pena se aplica a quem se associa para financiar o tráfico (parágrafo único)."},{"id":337,"materia":"port","nivel":2,"enunciado":"O que significa “ratificar”?","opcoes":["Confirmar","Corrigir","Anular","Adiar"],"explicacao":"Ratificar é confirmar. Retificar é corrigir."},{"id":338,"materia":"port","nivel":2,"enunciado":"Complete: “Estude bastante, ___ não passará.”","opcoes":["senão","se não","sinão","senão de"],"explicacao":"“Senão” equivale a “caso contrário”. “Se não” é condição: “se não estudar, não passa”."},{"id":339,"materia":"port","nivel":2,"enunciado":"Complete conforme a norma-padrão: “Havia ___ provas sobre a mesa.”","opcoes":["bastantes","bastante","bastantemente","bastanta"],"explicacao":"Antes de substantivo, “bastante” é adjetivo (muitas) e concorda em número."},{"id":340,"materia":"port","nivel":3,"enunciado":"Em “Ele chegou cedo”, a palavra “cedo” é:","opcoes":["Advérbio","Adjetivo","Substantivo","Preposição"],"explicacao":"Indica circunstância de tempo do verbo."},{"id":341,"materia":"port","nivel":3,"enunciado":"A forma “estudara” está no:","opcoes":["Pretérito mais-que-perfeito do indicativo","Pretérito imperfeito do subjuntivo","Futuro do pretérito","Pretérito perfeito do indicativo"],"explicacao":"Equivale a “tinha estudado”."},{"id":342,"materia":"port","nivel":4,"enunciado":"Em “Fiz tudo para que ele passasse”, a oração destacada é subordinada adverbial:","opcoes":["Final","Causal","Consecutiva","Condicional"],"explicacao":"“Para que” indica finalidade."},{"id":343,"materia":"port","nivel":4,"enunciado":"Pela norma-padrão, qual frase está correta?","opcoes":["O juiz procedeu ao interrogatório.","O juiz procedeu o interrogatório.","O juiz procedeu no interrogatório.","O juiz procedeu com o interrogatório."],"explicacao":"“Proceder”, no sentido de realizar, pede a preposição “a”."},{"id":344,"materia":"const","nivel":2,"enunciado":"Qual destes NÃO é símbolo da República (art. 13, § 1º)?","opcoes":["O mapa do Brasil","A bandeira","O hino","O selo nacional"],"explicacao":"Os símbolos são a bandeira, o hino, as armas e o selo nacionais."},{"id":345,"materia":"const","nivel":2,"enunciado":"Faltando Presidente e Vice, quem é chamado PRIMEIRO a exercer a Presidência?","opcoes":["O Presidente da Câmara dos Deputados","O Presidente do Senado","O Presidente do STF","O Ministro da Justiça"],"explicacao":"Art. 80: Câmara, depois Senado, depois STF."},{"id":346,"materia":"const","nivel":2,"enunciado":"Para quem o alistamento eleitoral e o voto são OBRIGATÓRIOS?","opcoes":["Maiores de 18 anos, salvo os casos de voto facultativo","Maiores de 16 anos","Todos os brasileiros e estrangeiros residentes","Apenas servidores públicos"],"explicacao":"Art. 14, § 1º. Analfabetos e maiores de 70 têm voto facultativo."},{"id":347,"materia":"const","nivel":3,"enunciado":"Vagando os cargos de Presidente e Vice nos dois primeiros anos do mandato, ocorre:","opcoes":["Eleição direta em 90 dias","Eleição indireta pelo Congresso em 30 dias","Posse definitiva do Presidente da Câmara","Novo mandato do Presidente do STF"],"explicacao":"Art. 81. Nos dois últimos anos, a eleição é indireta, pelo Congresso, em 30 dias."},{"id":348,"materia":"const","nivel":3,"enunciado":"Segundo a Constituição, são inelegíveis:","opcoes":["Os inalistáveis e os analfabetos","Os maiores de 70 anos","Os servidores públicos","Os brasileiros naturalizados"],"explicacao":"Art. 14, § 4º."},{"id":349,"materia":"const","nivel":4,"enunciado":"Nos crimes comuns, quem julga o Governador de estado?","opcoes":["O STJ","O STF","O Tribunal de Justiça","A Assembleia Legislativa"],"explicacao":"Art. 105, I, “a”."},{"id":350,"materia":"const","nivel":4,"enunciado":"Nos crimes comuns, quem julga o Prefeito?","opcoes":["O Tribunal de Justiça","O juiz de primeiro grau","O STJ","A Câmara Municipal"],"explicacao":"Art. 29, X, da Constituição."},{"id":351,"materia":"adm","nivel":2,"enunciado":"O cidadão convocado para ser mesário nas eleições é considerado:","opcoes":["Agente público (particular em colaboração)","Servidor público efetivo, durante o pleito","Empregado público da Justiça Eleitoral","Agente político, como os parlamentares"],"explicacao":"Exerce função pública de forma temporária, mesmo sem vínculo de cargo."},{"id":352,"materia":"adm","nivel":2,"enunciado":"Para contratar empregados, as empresas públicas e as sociedades de economia mista:","opcoes":["Precisam fazer concurso público","Podem contratar livremente","Precisam apenas de entrevista","Contratam só por indicação"],"explicacao":"Art. 37, II, da CF: emprego público também depende de concurso."},{"id":353,"materia":"adm","nivel":2,"enunciado":"A presunção de legitimidade dos atos administrativos é:","opcoes":["Relativa, admitindo prova em contrário","Absoluta","Inexistente","Válida só para atos vinculados"],"explicacao":"Cabe a quem contesta provar a ilegalidade."},{"id":354,"materia":"adm","nivel":3,"enunciado":"O ato que resulta da manifestação de dois ou mais órgãos, cujas vontades se fundem num só ato, é:","opcoes":["Complexo","Simples","Composto","Vinculado"],"explicacao":"No ato composto, há um ato principal e outro acessório que o ratifica."},{"id":355,"materia":"adm","nivel":3,"enunciado":"Os bens públicos podem ser adquiridos por usucapião?","opcoes":["Não","Sim, após 15 anos","Sim, se forem dominicais","Sim, por ordem judicial"],"explicacao":"Arts. 183, § 3º, e 191, parágrafo único, da Constituição."},{"id":356,"materia":"adm","nivel":4,"enunciado":"A teoria do órgão, que imputa à pessoa jurídica a atuação dos agentes, é atribuída a:","opcoes":["Otto Gierke","Hans Kelsen","Montesquieu","Léon Duguit"],"explicacao":"É a teoria da imputação volitiva, adotada no Brasil."},{"id":357,"materia":"adm","nivel":4,"enunciado":"Pela Lei nº 9.784/1999, concluída a instrução, a Administração deve decidir em até:","opcoes":["30 dias, prorrogáveis por igual período","10 dias, improrrogáveis","60 dias, prorrogáveis uma vez","90 dias, improrrogáveis"],"explicacao":"Art. 49."},{"id":358,"materia":"adm","nivel":4,"enunciado":"Pela Lei nº 9.784/1999, salvo disposição específica, o prazo para interpor recurso administrativo é de:","opcoes":["10 dias","5 dias","15 dias","30 dias"],"explicacao":"Art. 59."},{"id":359,"materia":"pen","nivel":2,"enunciado":"O servidor que se apropria de dinheiro público de que tem a posse em razão do cargo comete:","opcoes":["Peculato","Concussão","Corrupção passiva","Prevaricação"],"explicacao":"Art. 312 do CP."},{"id":360,"materia":"pen","nivel":2,"enunciado":"Ofender e humilhar funcionário público no exercício da função é crime de:","opcoes":["Desacato","Desobediência","Resistência","Corrupção ativa"],"explicacao":"Art. 331 do CP."},{"id":361,"materia":"pen","nivel":2,"enunciado":"Oferecer vantagem indevida a funcionário público para que ele pratique ato de ofício é:","opcoes":["Corrupção ativa","Corrupção passiva","Concussão","Tráfico de influência"],"explicacao":"Art. 333 do CP. A passiva é a do funcionário que recebe ou solicita."},{"id":362,"materia":"pen","nivel":3,"enunciado":"Quando o agente, com uma só ação, pratica dois ou mais crimes, há:","opcoes":["Concurso formal","Concurso material","Crime continuado","Crime habitual"],"explicacao":"Art. 70 do CP."},{"id":363,"materia":"pen","nivel":3,"enunciado":"No crime continuado, aplica-se a pena de um dos crimes aumentada de:","opcoes":["1/6 a 2/3","1/3 até o dobro","Metade","1/6 a 1/2"],"explicacao":"Art. 71, caput, do CP. No continuado específico, o aumento pode ir até o triplo."},{"id":364,"materia":"pen","nivel":4,"enunciado":"Qual destes NÃO interrompe a prescrição?","opcoes":["O oferecimento da denúncia","O recebimento da denúncia","A pronúncia","A publicação da sentença condenatória recorrível"],"explicacao":"Art. 117 do CP: interrompe-se pelo RECEBIMENTO, não pelo oferecimento."},{"id":365,"materia":"pen","nivel":4,"enunciado":"O tempo de prisão provisória cumprido no Brasil é descontado da pena final. Isso se chama:","opcoes":["Detração","Remição","Comutação","Indulto"],"explicacao":"Art. 42 do CP. Remição é o desconto por trabalho ou estudo."},{"id":366,"materia":"ppen","nivel":2,"enunciado":"Segundo a Súmula Vinculante 14, o advogado tem direito de acesso aos elementos de prova:","opcoes":["Já documentados no procedimento investigatório","De diligências ainda em andamento","Apenas após a denúncia","Apenas com autorização do delegado"],"explicacao":"Isso preserva as diligências em curso."},{"id":367,"materia":"ppen","nivel":2,"enunciado":"Segundo o CPP, a confissão é:","opcoes":["Divisível e retratável","Indivisível e irretratável","Prova absoluta","Dispensável sempre"],"explicacao":"Art. 200 do CPP."},{"id":368,"materia":"ppen","nivel":2,"enunciado":"Quem pode se recusar a depor como testemunha?","opcoes":["O cônjuge do acusado","O vizinho do acusado","O policial que fez a prisão","O colega de trabalho"],"explicacao":"Art. 206 do CPP, salvo quando não for possível obter a prova de outro modo."},{"id":369,"materia":"ppen","nivel":3,"enunciado":"Qual é o prazo para interpor apelação no processo penal?","opcoes":["5 dias","15 dias","10 dias","30 dias"],"explicacao":"Art. 593 do CPP. As razões podem vir depois, em 8 dias."},{"id":370,"materia":"ppen","nivel":3,"enunciado":"Contra a decisão que não recebe a denúncia, cabe:","opcoes":["Recurso em sentido estrito","Apelação","Embargos infringentes","Revisão criminal"],"explicacao":"Art. 581, I, do CPP."},{"id":371,"materia":"ppen","nivel":3,"enunciado":"Qual destes crimes é AFIANÇÁVEL?","opcoes":["Furto simples","Racismo","Tortura","Tráfico de drogas"],"explicacao":"Art. 323 do CPP e art. 5º da CF: racismo, tortura, tráfico, terrorismo, hediondos e ação de grupos armados são inafiançáveis."},{"id":372,"materia":"ppen","nivel":4,"enunciado":"O habeas corpus pode ser impetrado por:","opcoes":["Qualquer pessoa, inclusive o MP","Somente advogado inscrito na OAB","Somente o próprio preso","Somente o defensor público"],"explicacao":"Art. 654 do CPP. Dispensa advogado."},{"id":373,"materia":"ppen","nivel":4,"enunciado":"Na mutatio libelli, o Ministério Público deve aditar a denúncia em:","opcoes":["5 dias","10 dias","15 dias","48 horas"],"explicacao":"Art. 384 do CPP."},{"id":374,"materia":"inf","nivel":2,"enunciado":"No Windows, Shift + Delete:","opcoes":["Exclui o arquivo sem enviá-lo à Lixeira","Copia o arquivo","Renomeia o arquivo","Envia o arquivo à Lixeira"],"explicacao":"A exclusão é permanente, sem passar pela Lixeira."},{"id":375,"materia":"inf","nivel":2,"enunciado":"No Excel, qual o resultado de =MÁXIMO(3;9;5)?","opcoes":["9","17","5","3"],"explicacao":"MÁXIMO retorna o maior valor."},{"id":376,"materia":"inf","nivel":2,"enunciado":"Qual extensão indica, normalmente, um arquivo compactado?","opcoes":[".zip",".exe",".txt",".mp3"],"explicacao":"Também são comuns .rar e .7z."},{"id":377,"materia":"inf","nivel":3,"enunciado":"Qual a diferença entre internet e web?","opcoes":["A web é um serviço de páginas que usa a internet","São nomes diferentes para a mesma coisa","A internet é um serviço que funciona dentro da web","A web é o nome do serviço de e-mail da internet"],"explicacao":"A internet é a rede mundial. E-mail e web são serviços que usam essa rede."},{"id":378,"materia":"inf","nivel":3,"enunciado":"Um sniffer é uma ferramenta que:","opcoes":["Captura e analisa o tráfego da rede","Remove vírus de arquivos infectados","Acelera downloads em redes lentas","Bloqueia pop-ups de propaganda"],"explicacao":"É usada legitimamente por administradores e, de forma maliciosa, para roubar dados."},{"id":379,"materia":"inf","nivel":4,"enunciado":"Um ataque de negação de serviço distribuído (DDoS) afeta principalmente a:","opcoes":["Disponibilidade","Confidencialidade","Integridade","Autenticidade"],"explicacao":"Ele sobrecarrega o servidor até tirá-lo do ar."},{"id":380,"materia":"inf","nivel":4,"enunciado":"O protocolo SSH é usado para:","opcoes":["Acesso remoto seguro, normalmente na porta 22","Enviar e-mails, normalmente na porta 25","Navegar na web, normalmente na porta 80","Traduzir domínios, normalmente na porta 53"],"explicacao":"Ele substituiu o Telnet, que transmitia sem criptografia."},{"id":381,"materia":"rl","nivel":2,"enunciado":"Qual é o mínimo múltiplo comum (MMC) de 4 e 6?","opcoes":["12","24","2","6"],"explicacao":"Múltiplos de 4: 4, 8, 12… Múltiplos de 6: 6, 12… O primeiro em comum é 12."},{"id":382,"materia":"rl","nivel":2,"enunciado":"Numa prova de 40 questões, um candidato acertou 75%. Quantas questões ele acertou?","opcoes":["30","25","35","32"],"explicacao":"40 × 0,75 = 30."},{"id":383,"materia":"rl","nivel":2,"enunciado":"“Todos os X são Y. Nenhum Y é Z.” Logo:","opcoes":["Nenhum X é Z","Todo Z é X","Algum X é Z","Todo Y é X"],"explicacao":"Se X está dentro de Y, e Y não toca Z, X também não toca Z."},{"id":384,"materia":"rl","nivel":3,"enunciado":"Lançando um dado, qual a probabilidade de sair número par OU maior que 4?","opcoes":["2/3","1/2","5/6","1/3"],"explicacao":"Pares: 2, 4, 6. Maiores que 4: 5, 6. União: 2, 4, 5, 6, ou seja, 4 de 6 = 2/3."},{"id":385,"materia":"rl","nivel":3,"enunciado":"R$ 2.000,00 renderam R$ 240,00 de juros simples em 6 meses. Qual foi a taxa mensal?","opcoes":["2%","4%","1,2%","3%"],"explicacao":"240 = 2000 × i × 6, então i = 0,02 = 2%."},{"id":386,"materia":"rl","nivel":4,"enunciado":"Quantas comissões de 3 pessoas podem ser formadas a partir de 6 pessoas?","opcoes":["20","120","18","60"],"explicacao":"C(6,3) = 6 × 5 × 4 ÷ 6 = 20."},{"id":387,"materia":"rl","nivel":4,"enunciado":"Qual é a equivalente de “Se não estudo, então não passo”?","opcoes":["Se passo, então estudo","Se estudo, então passo","Estudo e passo","Não estudo e passo"],"explicacao":"É a contrapositiva: ¬P→¬Q equivale a Q→P."},{"id":388,"materia":"port","nivel":2,"enunciado":"Complete conforme a norma-padrão: “Os documentos seguem ___.”","opcoes":["anexos","anexo","em anexos","anexas"],"explicacao":"“Anexo” é adjetivo e concorda com o substantivo. A forma “em anexo” fica invariável."},{"id":389,"materia":"port","nivel":2,"enunciado":"Complete: “Ela estava ___ cansada depois da prova.”","opcoes":["meio","meia","meios","meias"],"explicacao":"Com sentido de “um pouco”, “meio” é advérbio e não varia."},{"id":390,"materia":"port","nivel":2,"enunciado":"Complete: “Estudou o fim de semana inteiro ___ passar na prova.”","opcoes":["a fim de","afim de","afim","a fim"],"explicacao":"“A fim de” indica finalidade. “Afim” significa semelhante, com afinidade."},{"id":391,"materia":"port","nivel":3,"enunciado":"Em “Vende-se uma casa”, a palavra “se” é:","opcoes":["Partícula apassivadora","Índice de indeterminação do sujeito","Pronome reflexivo","Conjunção condicional"],"explicacao":"Equivale a “uma casa é vendida”. O sujeito é “uma casa”."},{"id":392,"materia":"port","nivel":3,"enunciado":"Em “Roubaram minha carteira”, o sujeito é:","opcoes":["Indeterminado","Oculto","Inexistente","Simples"],"explicacao":"Verbo na 3ª pessoa do plural, sem referência a quem praticou a ação."},{"id":393,"materia":"port","nivel":3,"enunciado":"Em “O réu foi absolvido pelo júri”, o verbo está na voz:","opcoes":["Passiva analítica","Ativa","Reflexiva","Passiva sintética"],"explicacao":"Formada por ser + particípio, com agente da passiva (“pelo júri”)."},{"id":394,"materia":"port","nivel":4,"enunciado":"Em “Quanto mais estudo, mais aprendo”, a primeira oração é subordinada adverbial:","opcoes":["Proporcional","Comparativa","Consecutiva","Conformativa"],"explicacao":"“Quanto mais… mais” indica proporção entre os fatos."},{"id":395,"materia":"port","nivel":4,"enunciado":"Em “Era preciso que todos colaborassem”, a oração “que todos colaborassem” é subordinada substantiva:","opcoes":["Subjetiva","Objetiva direta","Predicativa","Completiva nominal"],"explicacao":"Ela funciona como sujeito de “era preciso”: “isso era preciso”."},{"id":396,"materia":"const","nivel":2,"enunciado":"A orientação jurídica e a defesa dos necessitados cabem à:","opcoes":["Defensoria Pública","Polícia Civil","Advocacia-Geral da União","Procuradoria do estado"],"explicacao":"Art. 134 da Constituição."},{"id":397,"materia":"const","nivel":2,"enunciado":"Como são escolhidos os ministros do STF?","opcoes":["Nomeados pelo Presidente após aprovação do Senado","Eleitos pelo voto popular a cada oito anos","Escolhidos pelos próprios ministros do tribunal","Indicados pela OAB em lista tríplice"],"explicacao":"Art. 101, parágrafo único."},{"id":398,"materia":"const","nivel":2,"enunciado":"Qual a faixa de idade para nomeação ao STF?","opcoes":["Mais de 35 e menos de 70 anos","Mais de 30 e menos de 65 anos","Mais de 40 e menos de 75 anos","Mais de 35 e menos de 65 anos"],"explicacao":"Art. 101, com redação da EC 122/2022."},{"id":399,"materia":"const","nivel":3,"enunciado":"A Constituição NÃO pode ser emendada durante:","opcoes":["Intervenção federal, estado de defesa ou estado de sítio","O recesso parlamentar","Ano eleitoral","O primeiro ano de mandato presidencial"],"explicacao":"Art. 60, § 1º."},{"id":400,"materia":"const","nivel":3,"enunciado":"Uma PEC rejeitada ou prejudicada pode ser reapresentada:","opcoes":["Só na sessão legislativa seguinte","Na mesma sessão, com assinaturas novas","A qualquer momento","Só após 4 anos"],"explicacao":"Art. 60, § 5º."},{"id":401,"materia":"const","nivel":3,"enunciado":"Para decretar o estado de sítio, o Presidente precisa de:","opcoes":["Autorização prévia do Congresso Nacional","Aprovação prévia do Supremo Tribunal Federal","Consulta popular por meio de plebiscito","Nada, basta o decreto presidencial"],"explicacao":"Art. 137. No estado de defesa, o Presidente decreta e submete o ato ao Congresso em 24 horas."},{"id":402,"materia":"const","nivel":4,"enunciado":"Quem pode impetrar mandado de segurança coletivo?","opcoes":["Partido político com representação no Congresso Nacional","Qualquer cidadão","O Ministério Público apenas","Qualquer associação, mesmo recém-criada"],"explicacao":"Art. 5º, LXX. Também organização sindical, entidade de classe ou associação legalmente constituída há pelo menos um ano."},{"id":403,"materia":"const","nivel":4,"enunciado":"O Conselho Nacional de Justiça (CNJ) é órgão:","opcoes":["Do Poder Judiciário","Do Poder Legislativo","Do Poder Executivo","Independente dos três Poderes"],"explicacao":"Art. 92, I-A, incluído pela EC 45/2004."},{"id":404,"materia":"adm","nivel":2,"enunciado":"Qual a diferença entre exoneração e demissão do servidor?","opcoes":["A exoneração não tem caráter punitivo; a demissão é penalidade","São a mesma coisa","A demissão é a pedido; a exoneração é punição","A exoneração só ocorre na aposentadoria"],"explicacao":"Lei 8.112: demissão é penalidade disciplinar (art. 127)."},{"id":405,"materia":"adm","nivel":2,"enunciado":"Na Lei nº 8.112/1990, qual é a forma ORIGINÁRIA de provimento?","opcoes":["Nomeação","Promoção","Reintegração","Recondução"],"explicacao":"As demais pressupõem vínculo anterior com a Administração."},{"id":406,"materia":"adm","nivel":2,"enunciado":"A reinvestidura do servidor estável quando sua demissão é invalidada chama-se:","opcoes":["Reintegração","Reversão","Recondução","Readaptação"],"explicacao":"Art. 28 da Lei 8.112, com ressarcimento das vantagens."},{"id":407,"materia":"adm","nivel":3,"enunciado":"O retorno à atividade de servidor aposentado chama-se:","opcoes":["Reversão","Reintegração","Aproveitamento","Recondução"],"explicacao":"Art. 25 da Lei 8.112."},{"id":408,"materia":"adm","nivel":3,"enunciado":"O retorno do servidor estável ao cargo anterior, por inabilitação no estágio probatório de outro cargo, é:","opcoes":["Recondução","Reversão","Readaptação","Aproveitamento"],"explicacao":"Art. 29 da Lei 8.112. Também ocorre se o antigo ocupante for reintegrado."},{"id":409,"materia":"adm","nivel":3,"enunciado":"O retorno à atividade do servidor que estava em disponibilidade chama-se:","opcoes":["Aproveitamento","Reversão","Reintegração","Promoção"],"explicacao":"Art. 30 da Lei 8.112."},{"id":410,"materia":"adm","nivel":4,"enunciado":"A investidura em cargo compatível com limitação física ou mental verificada em inspeção médica é a:","opcoes":["Readaptação","Recondução","Reversão","Remoção"],"explicacao":"Art. 24 da Lei 8.112."},{"id":411,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 8.112/1990, o registro de advertência é cancelado após quantos anos sem nova infração?","opcoes":["3 anos","5 anos","2 anos","1 ano"],"explicacao":"Art. 131. O registro de suspensão é cancelado após 5 anos."},{"id":412,"materia":"pen","nivel":2,"enunciado":"Qual resultado torna a lesão corporal GRAVÍSSIMA?","opcoes":["Perda ou inutilização de membro, sentido ou função","Perigo de vida","Incapacidade para ocupações habituais por mais de 30 dias","Aceleração de parto"],"explicacao":"Art. 129, § 2º, III. As outras alternativas são de lesão grave (§ 1º)."},{"id":413,"materia":"pen","nivel":2,"enunciado":"Pelo art. 217-A do Código Penal, considera-se vulnerável, em razão da idade, a pessoa menor de:","opcoes":["14 anos","12 anos","16 anos","18 anos"],"explicacao":"A lei também protege pessoas que, por enfermidade ou deficiência, não podem oferecer resistência."},{"id":414,"materia":"pen","nivel":2,"enunciado":"Nas causas de exclusão da ilicitude, quem se excede responde:","opcoes":["Pelo excesso doloso ou culposo","Por nada, pois está amparado","Sempre por crime doloso","Apenas civilmente"],"explicacao":"Art. 23, parágrafo único, do CP."},{"id":415,"materia":"pen","nivel":3,"enunciado":"Qual é requisito da legítima defesa?","opcoes":["Agressão injusta, atual ou iminente","Agressão já encerrada","Agressão justa","Uso de qualquer meio, sem limite"],"explicacao":"Art. 25: repelir injusta agressão, atual ou iminente, com uso moderado dos meios necessários."},{"id":416,"materia":"pen","nivel":3,"enunciado":"Após o Pacote Anticrime, está em legítima defesa o agente de segurança pública que:","opcoes":["Repele agressão a vítima mantida refém","Atira em suspeito que foge desarmado","Age por vingança após o crime","Prende alguém sem flagrante ou mandado"],"explicacao":"Art. 25, parágrafo único, do Código Penal."},{"id":417,"materia":"pen","nivel":3,"enunciado":"Sequestrar pessoa para obter vantagem como condição ou preço do resgate é crime de:","opcoes":["Extorsão mediante sequestro","Sequestro e cárcere privado","Roubo","Extorsão simples"],"explicacao":"Art. 159 do CP. É crime hediondo."},{"id":418,"materia":"pen","nivel":4,"enunciado":"Após o Pacote Anticrime, o tempo máximo de cumprimento das penas privativas de liberdade é de:","opcoes":["40 anos","30 anos","50 anos","35 anos"],"explicacao":"Art. 75 do CP, alterado pela Lei 13.964/2019."},{"id":419,"materia":"pen","nivel":4,"enunciado":"Em regra, a suspensão condicional da pena (sursis) cabe para pena privativa de liberdade não superior a:","opcoes":["2 anos","4 anos","1 ano","8 anos"],"explicacao":"Art. 77 do Código Penal."},{"id":420,"materia":"ppen","nivel":2,"enunciado":"Segundo o CPP, o silêncio do acusado no interrogatório:","opcoes":["Não importa confissão nem prejudica a defesa","Importa confissão tácita dos fatos","Agrava a pena em caso de condenação","Impede que o juiz profira a sentença"],"explicacao":"Art. 186, parágrafo único, do CPP."},{"id":421,"materia":"ppen","nivel":2,"enunciado":"O juiz pode substituir a prisão preventiva pela domiciliar quando o agente for:","opcoes":["Gestante","Reincidente","Servidor público","Maior de 50 anos"],"explicacao":"Art. 318, IV. Também para maiores de 80 anos e casos de doença grave, entre outros."},{"id":422,"materia":"ppen","nivel":2,"enunciado":"Arquivado o inquérito por falta de base para a denúncia, a autoridade policial pode:","opcoes":["Fazer novas pesquisas, se souber de outras provas","Reabrir sem nenhuma prova nova","Oferecer a denúncia","Nada, o caso está encerrado para sempre"],"explicacao":"Art. 18 do CPP."},{"id":423,"materia":"ppen","nivel":3,"enunciado":"Segundo a Súmula 524 do STF, arquivado o inquérito a pedido do MP, a ação penal só pode ser iniciada com:","opcoes":["Novas provas","Autorização do delegado","Pedido da vítima","Decisão do STJ"],"explicacao":"Sem prova nova, o arquivamento se mantém."},{"id":424,"materia":"ppen","nivel":3,"enunciado":"Quando o oficial de justiça verifica que o réu se oculta para não ser citado, faz a citação:","opcoes":["Por hora certa","Por edital","Por telefone","Pelo correio"],"explicacao":"Art. 362 do CPP."},{"id":425,"materia":"ppen","nivel":3,"enunciado":"Se o réu citado por edital não comparece nem constitui advogado:","opcoes":["Ficam suspensos o processo e o prazo prescricional","O processo segue à revelia","O réu é condenado automaticamente","A ação é arquivada"],"explicacao":"Art. 366 do CPP."},{"id":426,"materia":"ppen","nivel":4,"enunciado":"Qual o prazo da resposta à acusação, no procedimento comum?","opcoes":["10 dias","5 dias","15 dias","20 dias"],"explicacao":"Art. 396 do CPP."},{"id":427,"materia":"ppen","nivel":4,"enunciado":"Qual destas NÃO é hipótese de absolvição sumária (art. 397 do CPP)?","opcoes":["Falta de provas suficientes da autoria","Existência manifesta de causa excludente da ilicitude","Fato narrado que evidentemente não constitui crime","Extinção da punibilidade"],"explicacao":"Insuficiência de provas é motivo para absolver ao final da instrução, não sumariamente."},{"id":428,"materia":"leg","nivel":2,"enunciado":"Qual a pena de dirigir com a capacidade psicomotora alterada por álcool (art. 306 do CTB)?","opcoes":["Detenção de 6 meses a 3 anos, multa e suspensão da habilitação","Apenas multa administrativa e retenção do veículo","Reclusão de 5 a 8 anos e cassação da habilitação","Detenção de 15 dias, convertida em serviços à comunidade"],"explicacao":"Também há as sanções administrativas, como multa e suspensão do direito de dirigir."},{"id":429,"materia":"leg","nivel":2,"enunciado":"Qual a pena do homicídio culposo na direção de veículo (art. 302 do CTB), na forma simples?","opcoes":["Detenção de 2 a 4 anos e suspensão da habilitação","Reclusão de 6 a 20 anos e cassação da habilitação","Detenção de 1 a 3 anos, sem efeito na habilitação","Apenas multa e suspensão do direito de dirigir"],"explicacao":"É mais grave que o homicídio culposo do Código Penal (detenção de 1 a 3 anos)."},{"id":430,"materia":"leg","nivel":2,"enunciado":"Na Lei de Drogas, cultivar pequena quantidade de planta para consumo pessoal:","opcoes":["Tem o mesmo tratamento do porte para consumo (art. 28)","É equiparado ao tráfico de drogas (art. 33)","É crime hediondo, com pena de reclusão","Não é previsto como crime na Lei de Drogas"],"explicacao":"Art. 28, § 1º, da Lei 11.343/2006."},{"id":431,"materia":"leg","nivel":3,"enunciado":"Qual a pena do homicídio culposo na direção de veículo sob influência de álcool (art. 302, § 3º, do CTB)?","opcoes":["Reclusão de 5 a 8 anos","Detenção de 2 a 4 anos","Reclusão de 12 a 30 anos","Detenção de 6 meses a 3 anos"],"explicacao":"Incluído pela Lei 13.546/2017."},{"id":432,"materia":"leg","nivel":3,"enunciado":"No Estatuto do Desarmamento, o disparo de arma de fogo em via pública (art. 15) tem pena de:","opcoes":["Reclusão de 2 a 4 anos e multa","Detenção de 1 a 3 anos","Reclusão de 3 a 6 anos","Apenas multa"],"explicacao":"A conduta só é punida se não tiver como finalidade a prática de outro crime."},{"id":433,"materia":"leg","nivel":3,"enunciado":"Pelo ECA (art. 243), vender ou servir bebida alcoólica a criança ou adolescente é crime com pena de:","opcoes":["Detenção de 2 a 4 anos e multa","Apenas multa administrativa","Reclusão de 5 a 10 anos","Advertência"],"explicacao":"Redação dada pela Lei 13.106/2015, se o fato não constituir crime mais grave."},{"id":434,"materia":"leg","nivel":4,"enunciado":"Pela Lei Maria da Penha, em todos os atos processuais a mulher em situação de violência deve estar acompanhada de:","opcoes":["Advogado ou defensor público","Um familiar","Um policial","Um assistente social"],"explicacao":"Art. 27, ressalvado o pedido de medidas protetivas."},{"id":435,"materia":"leg","nivel":4,"enunciado":"Na Lei de Abuso de Autoridade, decretar prisão em manifesta desconformidade com as hipóteses legais (art. 9º) tem pena de:","opcoes":["Detenção de 1 a 4 anos e multa","Reclusão de 2 a 8 anos","Detenção de 6 meses a 2 anos","Apenas perda do cargo"],"explicacao":"Art. 9º da Lei 13.869/2019."},{"id":436,"materia":"inf","nivel":2,"enunciado":"No Excel, como uma célula é identificada?","opcoes":["Pela coluna e pela linha, como B3","Apenas por um número sequencial","Pelo nome da planilha ativa","Pela cor de preenchimento"],"explicacao":"A célula B3 fica na coluna B, linha 3."},{"id":437,"materia":"inf","nivel":2,"enunciado":"As atualizações de segurança do sistema operacional servem principalmente para:","opcoes":["Corrigir vulnerabilidades","Deixar a tela mais bonita","Apagar arquivos antigos","Aumentar o espaço do disco"],"explicacao":"Sistemas desatualizados são alvo fácil de ataques."},{"id":438,"materia":"inf","nivel":2,"enunciado":"Qual destas é a senha mais forte?","opcoes":["Pc@Ba#2026!Inv","123456","senha","joao1990"],"explicacao":"Senhas fortes misturam maiúsculas, minúsculas, números e símbolos, sem dados pessoais óbvios."},{"id":439,"materia":"inf","nivel":3,"enunciado":"No Excel, a função SOMASE:","opcoes":["Soma os valores que atendem a um critério","Conta as células vazias de um intervalo","Retorna o maior valor de um intervalo","Arredonda números para o inteiro mais próximo"],"explicacao":"Ex.: =SOMASE(A1:A10;“>100”)."},{"id":440,"materia":"inf","nivel":3,"enunciado":"O spoofing consiste em:","opcoes":["Falsificar a origem, como o remetente de um e-mail","Copiar arquivos automaticamente para a nuvem","Acelerar a rede comprimindo os pacotes","Bloquear propagandas exibidas em sites"],"explicacao":"É muito usado junto com phishing."},{"id":441,"materia":"inf","nivel":3,"enunciado":"Um servidor proxy funciona como:","opcoes":["Intermediário entre o usuário e a internet","Antivírus instalado no computador local","Editor de planilhas compartilhadas","Disco de armazenamento em rede"],"explicacao":"Pode filtrar conteúdo, guardar cache e ocultar o IP do usuário."},{"id":442,"materia":"inf","nivel":4,"enunciado":"Qual destes é um algoritmo de criptografia SIMÉTRICA?","opcoes":["AES","RSA","Diffie-Hellman","Assinatura digital com par de chaves"],"explicacao":"RSA e Diffie-Hellman são assimétricos."},{"id":443,"materia":"inf","nivel":4,"enunciado":"Qual protocolo da camada de transporte é orientado à conexão e garante a entrega?","opcoes":["TCP","UDP","IP","ARP"],"explicacao":"O UDP não estabelece conexão nem garante entrega, mas é mais rápido."},{"id":444,"materia":"rl","nivel":2,"enunciado":"Qual a média aritmética de 5, 7, 9 e 11?","opcoes":["8","9","7","32"],"explicacao":"(5 + 7 + 9 + 11) ÷ 4 = 32 ÷ 4 = 8."},{"id":445,"materia":"rl","nivel":2,"enunciado":"Numa sala com 12 homens e 18 mulheres, qual a razão entre homens e mulheres?","opcoes":["2/3","3/2","12/30","1/2"],"explicacao":"12/18 simplificado dá 2/3."},{"id":446,"materia":"rl","nivel":2,"enunciado":"Qual é a negação de “Pedro é policial e Ana é juíza”?","opcoes":["Pedro não é policial ou Ana não é juíza","Pedro não é policial e Ana não é juíza","Pedro é policial ou Ana é juíza","Se Pedro é policial, Ana não é juíza"],"explicacao":"De Morgan: ¬(P ∧ Q) = ¬P ∨ ¬Q."},{"id":447,"materia":"rl","nivel":3,"enunciado":"4 máquinas produzem 200 peças em 5 horas. Quantas peças 6 máquinas iguais produzem no mesmo tempo?","opcoes":["300","250","400","240"],"explicacao":"Cada máquina faz 50 peças em 5 horas. 6 × 50 = 300."},{"id":448,"materia":"rl","nivel":3,"enunciado":"A juros simples de 5% ao mês, em quanto tempo um capital dobra?","opcoes":["20 meses","10 meses","15 meses","25 meses"],"explicacao":"Para dobrar, os juros precisam somar 100%: 100 ÷ 5 = 20 meses."},{"id":449,"materia":"rl","nivel":3,"enunciado":"A proposição “Se P, então P” é:","opcoes":["Tautologia","Contradição","Contingência","Uma negação"],"explicacao":"É sempre verdadeira, qualquer que seja o valor de P."},{"id":450,"materia":"rl","nivel":4,"enunciado":"Quantos anagramas da palavra CASA começam com a letra C?","opcoes":["3","6","12","4"],"explicacao":"Fixando o C, sobram A, S e A: 3! ÷ 2! = 3."},{"id":451,"materia":"rl","nivel":4,"enunciado":"Retirando 2 cartas de um baralho de 52, sem reposição, qual a probabilidade de ambas serem de copas?","opcoes":["1/17","1/16","1/4","13/51"],"explicacao":"13/52 × 12/51 = 1/4 × 4/17 = 1/17."},{"id":452,"materia":"dh","nivel":2,"enunciado":"Constranger alguém com violência, causando sofrimento físico ou mental, em razão de discriminação racial ou religiosa, é crime de:","opcoes":["Tortura","Lesão corporal leve","Ameaça","Injúria simples"],"explicacao":"Art. 1º, I, “c”, da Lei 9.455/97."},{"id":453,"materia":"dh","nivel":2,"enunciado":"Qual lei institui o Estatuto da Igualdade Racial?","opcoes":["Lei nº 12.288/2010","Lei nº 7.716/1989","Lei nº 10.639/2003","Lei nº 9.455/1997"],"explicacao":"Ela busca garantir igualdade de oportunidades e combater a discriminação étnica."},{"id":454,"materia":"dh","nivel":2,"enunciado":"A Lei nº 7.716/1989 define os crimes resultantes de:","opcoes":["Preconceito de raça, cor, etnia, religião ou procedência","Violência doméstica e familiar contra a mulher","Abuso de autoridade praticado por agente público","Tortura física ou psicológica sob custódia"],"explicacao":"É conhecida como Lei do Racismo ou Lei Caó."},{"id":455,"materia":"dh","nivel":3,"enunciado":"Em 2019, no julgamento da ADO 26, o STF enquadrou a homotransfobia como:","opcoes":["Crime de racismo (Lei nº 7.716/1989)","Contravenção penal","Ilícito apenas civil","Crime de injúria simples"],"explicacao":"O enquadramento vale até que o Congresso edite lei específica."},{"id":456,"materia":"dh","nivel":3,"enunciado":"Com a Lei nº 14.532/2023, a injúria racial passou a ser:","opcoes":["Crime da Lei do Racismo, com reclusão de 2 a 5 anos","Contravenção penal, punida apenas com multa","Crime de menor potencial, julgado no juizado","Ilícito apenas administrativo, sem pena criminal"],"explicacao":"Art. 2º-A da Lei 7.716/1989."},{"id":457,"materia":"dh","nivel":3,"enunciado":"Segundo o art. 134 da Constituição, incumbe à Defensoria Pública, entre outras funções:","opcoes":["A promoção dos direitos humanos","Julgar ações penais","Oferecer denúncia","Fiscalizar contas públicas"],"explicacao":"Redação dada pela EC 80/2014."},{"id":458,"materia":"dh","nivel":4,"enunciado":"O princípio pro persona (pro homine) determina que:","opcoes":["Se aplique a norma mais favorável à pessoa","Prevaleça sempre a lei interna","Prevaleça sempre o tratado mais antigo","O Estado escolha a norma mais conveniente"],"explicacao":"Entre normas de direitos humanos, vale a que mais protege."},{"id":459,"materia":"dh","nivel":4,"enunciado":"O controle de convencionalidade consiste em:","opcoes":["Verificar se normas internas respeitam tratados de direitos humanos","Controlar as convenções partidárias de escolha de candidatos","Fiscalizar a execução de contratos administrativos","Revisar convenções coletivas de trabalho"],"explicacao":"É feito por juízes nacionais e pela Corte Interamericana."},{"id":460,"materia":"port","nivel":2,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Obsessão","Obseção","Obcessão","Obsseção"],"explicacao":"Obsessão: “bs” na primeira parte e “ss” antes do “ão”."},{"id":461,"materia":"port","nivel":2,"enunciado":"Qual frase está correta quanto à concordância?","opcoes":["Bastaram dois dias para resolver o caso.","Bastou dois dias para resolver o caso.","Falta muitas questões.","Existe vários motivos."],"explicacao":"Os verbos bastar, faltar e existir concordam com o sujeito, que vem depois: bastaram dois dias, faltam muitas questões, existem vários motivos."},{"id":462,"materia":"port","nivel":2,"enunciado":"Qual a grafia correta segundo o Acordo Ortográfico?","opcoes":["Bem-vindo","Benvindo","Bem vindo","Bemvindo"],"explicacao":"“Bem” como prefixo leva hífen antes de palavra com vida própria: bem-vindo, bem-estar."},{"id":463,"materia":"port","nivel":3,"enunciado":"Em “Estudou tanto que passou”, a palavra “que” é conjunção:","opcoes":["Consecutiva","Causal","Integrante","Final"],"explicacao":"Com “tanto… que”, a segunda oração expressa a consequência."},{"id":464,"materia":"port","nivel":3,"enunciado":"Em “Estudo à noite”, o termo “à noite” é:","opcoes":["Adjunto adverbial de tempo","Objeto indireto","Complemento nominal","Adjunto adnominal"],"explicacao":"Indica a circunstância de tempo da ação."},{"id":465,"materia":"port","nivel":3,"enunciado":"Em “Os alunos estavam atentos”, o predicado é:","opcoes":["Nominal","Verbal","Verbo-nominal","Inexistente"],"explicacao":"O verbo de ligação “estar” liga o sujeito ao predicativo “atentos”."},{"id":466,"materia":"port","nivel":4,"enunciado":"Em “Conforme previsto, a prova foi adiada”, a palavra “conforme” expressa:","opcoes":["Conformidade","Concessão","Condição","Comparação"],"explicacao":"Equivale a “como estava previsto”, “de acordo com o previsto”."},{"id":467,"materia":"port","nivel":4,"enunciado":"Em qual frase o acento grave está correto?","opcoes":["Fui à Bahia nas férias.","Fui à Recife nas férias.","Cheguei à casa cedo.","Saímos à cavalo."],"explicacao":"Bahia aceita artigo (volto DA Bahia). Recife não (volto DE Recife). “Casa” no sentido de lar, sem determinante, e “cavalo”, masculino, não admitem crase."},{"id":468,"materia":"const","nivel":2,"enunciado":"Qual é o sistema de governo adotado no Brasil?","opcoes":["Presidencialismo","Parlamentarismo","Semipresidencialismo","Monarquia constitucional"],"explicacao":"O Presidente é chefe de Estado e de governo ao mesmo tempo."},{"id":469,"materia":"const","nivel":2,"enunciado":"O direito de petição aos Poderes Públicos é assegurado:","opcoes":["Independentemente do pagamento de taxas","Mediante pagamento de taxa","Apenas por advogado","Apenas a eleitores"],"explicacao":"Art. 5º, XXXIV, “a”."},{"id":470,"materia":"const","nivel":2,"enunciado":"Quanto ao juízo ou tribunal de exceção, a Constituição:","opcoes":["Proíbe sua criação","Permite em tempos de guerra","Permite para crimes hediondos","Deixa a critério do Congresso"],"explicacao":"Art. 5º, XXXVII. Ninguém será julgado por tribunal criado depois do fato."},{"id":471,"materia":"const","nivel":3,"enunciado":"O Tribunal do Júri é competente para julgar:","opcoes":["Os crimes dolosos contra a vida","Todos os crimes hediondos","Os crimes de trânsito","Os crimes contra o patrimônio"],"explicacao":"Art. 5º, XXXVIII, “d”."},{"id":472,"materia":"const","nivel":3,"enunciado":"Segundo a Constituição, a lei não prejudicará:","opcoes":["O direito adquirido, o ato jurídico perfeito e a coisa julgada","Apenas a coisa julgada em processos penais","Os contratos privados firmados no futuro","Qualquer expectativa de direito do servidor"],"explicacao":"Art. 5º, XXXVI."},{"id":473,"materia":"const","nivel":3,"enunciado":"Quem julga mandado de segurança contra ato do Presidente da República?","opcoes":["O STF","O STJ","A Justiça Federal de 1º grau","O Senado Federal"],"explicacao":"Art. 102, I, “d”."},{"id":474,"materia":"const","nivel":4,"enunciado":"O recurso especial, contra decisão que contraria lei federal, é julgado pelo:","opcoes":["STJ","STF","TST","TSE"],"explicacao":"Art. 105, III. O recurso extraordinário, por violação à Constituição, vai ao STF."},{"id":475,"materia":"const","nivel":4,"enunciado":"A repercussão geral da questão constitucional é requisito do:","opcoes":["Recurso extraordinário","Recurso especial","Habeas corpus","Mandado de injunção"],"explicacao":"Art. 102, § 3º, incluído pela EC 45/2004."},{"id":476,"materia":"adm","nivel":2,"enunciado":"A prestação de serviço público por empresa privada, por contrato após licitação, chama-se:","opcoes":["Concessão","Desapropriação","Tombamento","Requisição"],"explicacao":"Prevista na Lei 8.987/1995 e no art. 175 da CF."},{"id":477,"materia":"adm","nivel":2,"enunciado":"Qual a natureza jurídica do INSS?","opcoes":["Autarquia","Empresa pública","Sociedade de economia mista","Fundação privada"],"explicacao":"É autarquia federal ligada à Previdência Social."},{"id":478,"materia":"adm","nivel":2,"enunciado":"Qual a natureza jurídica do Banco do Brasil?","opcoes":["Sociedade de economia mista","Empresa pública","Autarquia","Órgão da administração direta"],"explicacao":"Tem capital público e privado, com controle acionário da União."},{"id":479,"materia":"adm","nivel":3,"enunciado":"Segundo a Súmula 473 do STF, a Administração pode:","opcoes":["Anular seus atos ilegais e revogar os inconvenientes","Anular atos ilegais apenas com ordem judicial","Revogar atos ilegais e anular os inconvenientes","Nunca rever os atos que ela mesma praticou"],"explicacao":"É o princípio da autotutela."},{"id":480,"materia":"adm","nivel":3,"enunciado":"As cláusulas exorbitantes dos contratos administrativos permitem à Administração, por exemplo:","opcoes":["Alterar unilateralmente o contrato","Deixar de pagar sem motivo","Contratar sem licitação sempre","Transferir o contrato a qualquer empresa"],"explicacao":"Sempre respeitando o equilíbrio econômico-financeiro do contratado."},{"id":481,"materia":"adm","nivel":3,"enunciado":"Na Lei nº 14.133/2021, os contratos de serviços contínuos podem ter vigência de até:","opcoes":["5 anos, prorrogáveis até o limite de 10 anos","1 ano, improrrogável","2 anos, prorrogáveis até 4","10 anos desde o início, sem prorrogação"],"explicacao":"Arts. 106 e 107."},{"id":482,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 14.133/2021, qual é a vigência da ata de registro de preços?","opcoes":["1 ano, prorrogável por igual período","6 meses, improrrogável","2 anos, improrrogável","5 anos"],"explicacao":"Art. 84, se comprovado que o preço continua vantajoso."},{"id":483,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 14.133/2021, em regra, a fase de habilitação ocorre:","opcoes":["Depois do julgamento das propostas","Antes da divulgação do edital","Antes da apresentação das propostas","Depois da homologação"],"explicacao":"Art. 17. A inversão é a regra; a habilitação antes do julgamento é exceção."},{"id":484,"materia":"pen","nivel":2,"enunciado":"Quem acha coisa perdida e não a devolve ao dono ou à autoridade em 15 dias comete:","opcoes":["Apropriação de coisa achada","Furto simples","Receptação culposa","Estelionato"],"explicacao":"Art. 169, parágrafo único, II, do CP."},{"id":485,"materia":"pen","nivel":2,"enunciado":"Nos crimes contra a honra, a retratação cabal antes da sentença isenta de pena na:","opcoes":["Calúnia e na difamação","Injúria apenas","Injúria racial","Calúnia apenas"],"explicacao":"Art. 143 do Código Penal."},{"id":486,"materia":"pen","nivel":2,"enunciado":"Fazer justiça pelas próprias mãos para satisfazer pretensão, mesmo legítima, é crime de:","opcoes":["Exercício arbitrário das próprias razões","Constrangimento ilegal","Desobediência a ordem legal","Ameaça qualificada"],"explicacao":"Art. 345 do Código Penal."},{"id":487,"materia":"pen","nivel":3,"enunciado":"O funcionário que, sem ter a posse do bem, o subtrai valendo-se da facilidade do cargo comete:","opcoes":["Peculato-furto","Peculato culposo","Furto simples","Concussão"],"explicacao":"Art. 312, § 1º, do CP."},{"id":488,"materia":"pen","nivel":3,"enunciado":"Fabricar moeda falsa é crime contra:","opcoes":["A fé pública","O patrimônio","A administração pública","A ordem econômica"],"explicacao":"Art. 289 do Código Penal."},{"id":489,"materia":"pen","nivel":3,"enunciado":"No homicídio privilegiado, por relevante valor social ou moral, a pena pode ser reduzida de:","opcoes":["1/6 a 1/3","1/3 a 2/3","Metade","1/6 a 2/3"],"explicacao":"Art. 121, § 1º. Também vale para quem age sob violenta emoção logo após injusta provocação da vítima."},{"id":490,"materia":"pen","nivel":4,"enunciado":"Quando a multa for a única pena aplicada, sua prescrição ocorre em:","opcoes":["2 anos","3 anos","4 anos","1 ano"],"explicacao":"Art. 114, I, do Código Penal."},{"id":491,"materia":"pen","nivel":4,"enunciado":"Qual destas é circunstância AGRAVANTE genérica (art. 61 do CP)?","opcoes":["Reincidência","Confissão espontânea","Ser menor de 21 anos na data do fato","Reparação do dano"],"explicacao":"As outras três são atenuantes (art. 65)."},{"id":492,"materia":"ppen","nivel":2,"enunciado":"No procedimento comum ordinário, cada parte pode arrolar até quantas testemunhas?","opcoes":["8","5","3","10"],"explicacao":"Art. 401 do CPP. No sumário, são 5."},{"id":493,"materia":"ppen","nivel":2,"enunciado":"Em regra, a prisão preventiva cabe nos crimes dolosos com pena máxima superior a:","opcoes":["4 anos","2 anos","8 anos","1 ano"],"explicacao":"Art. 313, I, do CPP. Há outras hipóteses, como a violência doméstica."},{"id":494,"materia":"ppen","nivel":2,"enunciado":"As infrações de menor potencial ofensivo seguem o procedimento:","opcoes":["Sumaríssimo","Ordinário","Sumário","Do júri"],"explicacao":"É o procedimento dos Juizados Especiais Criminais."},{"id":495,"materia":"ppen","nivel":3,"enunciado":"O procedimento comum sumário é aplicado ao crime cuja pena máxima é:","opcoes":["Inferior a 4 anos","Igual ou superior a 4 anos","Inferior a 2 anos","Superior a 8 anos"],"explicacao":"Art. 394, § 1º, II, do CPP. Pena de 4 anos ou mais segue o ordinário."},{"id":496,"materia":"ppen","nivel":3,"enunciado":"O assistente de acusação pode ser admitido:","opcoes":["Enquanto não passar em julgado a sentença","Apenas durante o inquérito policial","Somente antes do oferecimento da denúncia","Apenas na fase de recurso ao tribunal"],"explicacao":"Art. 269 do CPP."},{"id":497,"materia":"ppen","nivel":3,"enunciado":"No Tribunal do Júri, as decisões dos jurados são tomadas por:","opcoes":["Maioria de votos","Unanimidade","Voto do juiz presidente","Sorteio"],"explicacao":"Art. 489 do CPP. A votação é sigilosa."},{"id":498,"materia":"ppen","nivel":4,"enunciado":"No rito do Júri, a decisão que admite a acusação e submete o réu a julgamento pelos jurados é a:","opcoes":["Pronúncia","Impronúncia","Desclassificação","Absolvição sumária"],"explicacao":"Art. 413 do CPP."},{"id":499,"materia":"ppen","nivel":4,"enunciado":"Contra a decisão de pronúncia, cabe:","opcoes":["Recurso em sentido estrito","Apelação","Embargos de declaração apenas","Revisão criminal"],"explicacao":"Art. 581, IV, do CPP."},{"id":500,"materia":"leg","nivel":2,"enunciado":"Na Lei Maria da Penha, reter ou destruir objetos, documentos ou bens da mulher é violência:","opcoes":["Patrimonial","Moral","Psicológica","Sexual"],"explicacao":"Art. 7º, IV, da Lei 11.340/2006."},{"id":501,"materia":"leg","nivel":2,"enunciado":"Pelo CTB, dirigir sem habilitação, gerando perigo de dano (art. 309), tem pena de:","opcoes":["Detenção de 6 meses a 1 ano, ou multa","Reclusão de 2 a 4 anos","Apenas advertência","Detenção de 2 a 4 anos"],"explicacao":"Sem perigo de dano, é só infração administrativa."},{"id":502,"materia":"leg","nivel":2,"enunciado":"Segundo o ECA, o Conselho Tutelar é órgão:","opcoes":["Permanente e autônomo, não jurisdicional","Temporário e subordinado ao juiz","Integrante da Polícia Civil","Integrante do Ministério Público"],"explicacao":"Art. 131 do ECA."},{"id":503,"materia":"leg","nivel":3,"enunciado":"Na Lei de Lavagem de Dinheiro, o colaborador pode ter a pena reduzida de:","opcoes":["1/3 a 2/3","1/6 a 1/3","Metade","1/6 a 2/3"],"explicacao":"Art. 1º, § 5º, da Lei 9.613/98. O juiz também pode deixar de aplicar a pena ou substituí-la."},{"id":504,"materia":"leg","nivel":3,"enunciado":"Na Lei de Drogas, financiar ou custear o tráfico (art. 36) tem pena de:","opcoes":["Reclusão de 8 a 20 anos e multa","Reclusão de 5 a 15 anos","Reclusão de 3 a 10 anos","Detenção de 2 a 6 anos"],"explicacao":"É mais grave que o próprio tráfico do art. 33."},{"id":505,"materia":"leg","nivel":3,"enunciado":"Após o Pacote Anticrime, o comércio ilegal de arma de fogo (art. 17 do Estatuto do Desarmamento) tem pena de:","opcoes":["Reclusão de 6 a 12 anos e multa","Reclusão de 2 a 4 anos","Reclusão de 4 a 8 anos","Detenção de 1 a 3 anos"],"explicacao":"Alteração feita pela Lei 13.964/2019."},{"id":506,"materia":"leg","nivel":4,"enunciado":"Após o Pacote Anticrime, o tráfico internacional de arma de fogo (art. 18 do Estatuto do Desarmamento) tem pena de:","opcoes":["Reclusão de 8 a 16 anos e multa","Reclusão de 4 a 8 anos","Reclusão de 6 a 12 anos","Reclusão de 12 a 30 anos"],"explicacao":"Alteração feita pela Lei 13.964/2019."},{"id":507,"materia":"leg","nivel":4,"enunciado":"Na Lei nº 12.850/2013, quem homologa o acordo de colaboração premiada?","opcoes":["O juiz","O delegado","O Ministério Público","O advogado do colaborador"],"explicacao":"O acordo é celebrado entre o delegado ou o MP e o colaborador, com seu defensor, e o juiz verifica a regularidade e a voluntariedade."},{"id":508,"materia":"inf","nivel":2,"enunciado":"No Windows, o Explorador de Arquivos serve para:","opcoes":["Gerenciar pastas e arquivos","Navegar na internet","Editar planilhas","Remover vírus"],"explicacao":"Por ele você copia, move, renomeia e exclui arquivos."},{"id":509,"materia":"inf","nivel":2,"enunciado":"No Excel, se A1 = 2, A2 = 4 e A3 = 6, qual o resultado de =SOMA(A1:A3)?","opcoes":["12","6","4","246"],"explicacao":"2 + 4 + 6 = 12."},{"id":510,"materia":"inf","nivel":2,"enunciado":"Uma rede LAN é uma rede:","opcoes":["Local, como a de um escritório ou casa","Mundial, como a internet","Apenas sem fio","De telefonia celular"],"explicacao":"Local Area Network."},{"id":511,"materia":"inf","nivel":3,"enunciado":"No Excel, o erro #DIV/0! indica:","opcoes":["Divisão por zero","Referência inválida","Nome de função errado","Texto em vez de número"],"explicacao":"Aparece quando o divisor da fórmula é zero ou uma célula vazia."},{"id":512,"materia":"inf","nivel":3,"enunciado":"Um ataque de força bruta consiste em:","opcoes":["Testar sistematicamente muitas senhas até acertar","Danificar fisicamente o computador","Enviar e-mails falsos","Desligar a energia do servidor"],"explicacao":"Senhas longas e bloqueio após tentativas reduzem o risco."},{"id":513,"materia":"inf","nivel":3,"enunciado":"Um rootkit é um conjunto de programas que:","opcoes":["Esconde a presença de malware no sistema","Acelera o processador do computador","Organiza arquivos em pastas automaticamente","Faz backup automático dos documentos"],"explicacao":"É difícil de detectar por agir em níveis profundos do sistema."},{"id":514,"materia":"inf","nivel":4,"enunciado":"Na segurança da informação, a confidencialidade garante que:","opcoes":["A informação só seja acessada por quem tem autorização","O sistema fique sempre disponível quando necessário","A informação não seja alterada sem permissão","O autor de uma mensagem não negue a autoria"],"explicacao":"Disponibilidade, integridade e não repúdio são outros princípios."},{"id":515,"materia":"inf","nivel":4,"enunciado":"No Excel, a função CONT.VALORES conta:","opcoes":["As células não vazias de um intervalo","Apenas células com números","Apenas células vazias","As células que atendem a um critério"],"explicacao":"Para contar só números, usa-se CONT.NÚM; para vazias, CONTAR.VAZIO."},{"id":516,"materia":"rl","nivel":2,"enunciado":"18 representa quantos por cento de 72?","opcoes":["25%","18%","30%","20%"],"explicacao":"18 ÷ 72 = 0,25."},{"id":517,"materia":"rl","nivel":2,"enunciado":"Qual é a negação de “Nenhum candidato faltou”?","opcoes":["Algum candidato faltou","Todos os candidatos faltaram","Nenhum candidato compareceu","Algum candidato não faltou"],"explicacao":"Negar “nenhum” equivale a afirmar que pelo menos um faltou."},{"id":518,"materia":"rl","nivel":2,"enunciado":"Um carro a 90 km/h constantes percorre quantos quilômetros em 40 minutos?","opcoes":["60 km","45 km","90 km","36 km"],"explicacao":"40 minutos = 2/3 de hora. 90 × 2/3 = 60."},{"id":519,"materia":"rl","nivel":2,"enunciado":"Qual é o máximo divisor comum (MDC) de 12 e 18?","opcoes":["6","3","2","36"],"explicacao":"Divisores comuns: 1, 2, 3 e 6. O maior é 6."},{"id":520,"materia":"rl","nivel":3,"enunciado":"A condicional “Se P, então Q” é falsa somente quando:","opcoes":["P é verdadeira e Q é falsa","P é falsa e Q é verdadeira","Ambas são falsas","Ambas são verdadeiras"],"explicacao":"É a única linha falsa da tabela-verdade da condicional."},{"id":521,"materia":"rl","nivel":3,"enunciado":"R$ 2.000,00 a juros compostos de 5% ao mês. Qual o montante após 2 meses?","opcoes":["R$ 2.205,00","R$ 2.200,00","R$ 2.100,00","R$ 2.250,00"],"explicacao":"2.000 × 1,05 × 1,05 = 2.205."},{"id":522,"materia":"rl","nivel":3,"enunciado":"Seis pessoas se cumprimentam, cada uma uma única vez com cada outra. Quantos apertos de mão ocorrem?","opcoes":["15","30","36","12"],"explicacao":"C(6,2) = 6 × 5 ÷ 2 = 15."},{"id":523,"materia":"rl","nivel":4,"enunciado":"Lançando dois dados, qual a probabilidade de a soma ser 10?","opcoes":["1/12","1/6","1/9","1/18"],"explicacao":"Casos favoráveis: (4,6), (5,5), (6,4). São 3 em 36 = 1/12."},{"id":524,"materia":"rl","nivel":4,"enunciado":"Quantas senhas de 4 dígitos (0 a 9) podem ser formadas sem repetir dígitos?","opcoes":["5.040","10.000","210","3.024"],"explicacao":"10 × 9 × 8 × 7 = 5.040."},{"id":525,"materia":"dh","nivel":2,"enunciado":"Qual destes é princípio das relações internacionais do Brasil (art. 4º da CF)?","opcoes":["Concessão de asilo político","Intervenção em outros países","Expansão territorial","Neutralidade absoluta em qualquer conflito"],"explicacao":"Art. 4º, X. Também estão lá a prevalência dos direitos humanos e o repúdio ao terrorismo e ao racismo."},{"id":526,"materia":"dh","nivel":2,"enunciado":"A Lei nº 13.010/2014, conhecida como Lei Menino Bernardo, garante à criança e ao adolescente o direito de:","opcoes":["Ser educados sem o uso de castigos físicos","Trabalhar a partir dos 12 anos","Votar aos 14 anos","Escolher a própria escola sem os pais"],"explicacao":"Ela alterou o ECA."},{"id":527,"materia":"dh","nivel":2,"enunciado":"A Constituição assegura o direito de resposta:","opcoes":["Proporcional ao agravo, além da indenização","Apenas na imprensa escrita","Somente com autorização judicial prévia","Apenas a autoridades públicas"],"explicacao":"Art. 5º, V."},{"id":528,"materia":"dh","nivel":3,"enunciado":"São princípios institucionais da Defensoria Pública:","opcoes":["Unidade, indivisibilidade e independência funcional","Hierarquia, disciplina e obediência","Sigilo, celeridade e oralidade","Legalidade, moralidade e publicidade"],"explicacao":"Art. 134, § 4º, da CF."},{"id":529,"materia":"dh","nivel":3,"enunciado":"O Conselho Nacional dos Direitos Humanos foi criado pela Lei:","opcoes":["12.986/2014","13.445/2017","9.474/1997","12.288/2010"],"explicacao":"Ele substituiu o antigo Conselho de Defesa dos Direitos da Pessoa Humana."},{"id":530,"materia":"dh","nivel":3,"enunciado":"A Lei nº 13.344/2016 trata do enfrentamento ao:","opcoes":["Tráfico de pessoas","Tráfico de drogas","Trabalho infantil","Racismo"],"explicacao":"Ela também incluiu o crime de tráfico de pessoas no Código Penal (art. 149-A)."},{"id":531,"materia":"dh","nivel":4,"enunciado":"O Tribunal Penal Internacional foi criado pelo:","opcoes":["Estatuto de Roma","Pacto de San José","Tratado de Versalhes","Protocolo de Kyoto"],"explicacao":"Tem sede em Haia e julga crimes como genocídio e crimes contra a humanidade."},{"id":532,"materia":"dh","nivel":4,"enunciado":"Pelo princípio da complementaridade, o Tribunal Penal Internacional atua:","opcoes":["Quando o Estado não quer ou não consegue julgar","Sempre antes da justiça do país do crime","Apenas a pedido do próprio acusado","Em qualquer crime comum, sem distinção"],"explicacao":"A jurisdição nacional tem prioridade; o TPI é complementar."},{"id":533,"materia":"port","nivel":2,"enunciado":"Qual palavra está escrita corretamente?","opcoes":["Ascensão","Acensão","Assenção","Ascenção"],"explicacao":"Ascensão: SC no meio e S antes do “ão”."},{"id":534,"materia":"port","nivel":2,"enunciado":"Complete: “Não estudou, ___ trabalhou.”","opcoes":["tampouco","tão pouco","tan pouco","tampoco"],"explicacao":"“Tampouco” significa “também não”. “Tão pouco” indica pequena quantidade."},{"id":535,"materia":"port","nivel":2,"enunciado":"Uma mulher agradece dizendo:","opcoes":["Obrigada","Obrigado","Obrigados","Obrigadas"],"explicacao":"“Obrigado” é adjetivo e concorda com quem fala: mulher diz “obrigada”."},{"id":536,"materia":"port","nivel":3,"enunciado":"Em “Choveu bastante ontem”, a palavra “bastante” é:","opcoes":["Advérbio","Adjetivo","Substantivo","Pronome"],"explicacao":"Modifica o verbo e não varia. Antes de substantivo seria adjetivo (bastantes provas)."},{"id":537,"materia":"port","nivel":3,"enunciado":"A mesóclise ocorre quando o verbo está no:","opcoes":["Futuro do presente ou do pretérito","Pretérito perfeito do indicativo","Imperativo afirmativo","Infinitivo pessoal"],"explicacao":"Sem palavra atrativa antes do verbo. Ex.: “Far-se-á a prova”, “Dir-lhe-ia a verdade”."},{"id":538,"materia":"port","nivel":3,"enunciado":"Em “Precisamos de você”, o verbo é:","opcoes":["Transitivo indireto","Transitivo direto","Intransitivo","De ligação"],"explicacao":"Precisar pede complemento com a preposição “de”."},{"id":539,"materia":"port","nivel":4,"enunciado":"Em “Como estava doente, faltou à prova”, a conjunção “como” é:","opcoes":["Causal","Comparativa","Conformativa","Concessiva"],"explicacao":"Equivale a “porque estava doente”."},{"id":540,"materia":"port","nivel":4,"enunciado":"Em “Ele é mais estudioso que o irmão”, a segunda oração é subordinada adverbial:","opcoes":["Comparativa","Consecutiva","Proporcional","Final"],"explicacao":"A estrutura “mais… que” estabelece comparação."},{"id":541,"materia":"const","nivel":2,"enunciado":"Qual é a duração do mandato de um governador?","opcoes":["4 anos","5 anos","6 anos","8 anos"],"explicacao":"Art. 28, permitida uma reeleição."},{"id":542,"materia":"const","nivel":2,"enunciado":"Segundo a Constituição, para o militar são proibidas:","opcoes":["A sindicalização e a greve","A promoção por mérito","A remuneração por subsídio","A aposentadoria"],"explicacao":"Art. 142, § 3º, IV."},{"id":543,"materia":"const","nivel":2,"enunciado":"Os Territórios Federais, quando criados, integram:","opcoes":["A União","Os estados vizinhos","Os municípios","Nenhum ente"],"explicacao":"Art. 18, § 2º. Hoje não existem territórios no Brasil."},{"id":544,"materia":"const","nivel":3,"enunciado":"Segundo o art. 144, às polícias militares cabem:","opcoes":["A polícia ostensiva e a preservação da ordem pública","A apuração de infrações penais comuns","A polícia judiciária da União","A segurança dos estabelecimentos penais"],"explicacao":"Art. 144, § 5º."},{"id":545,"materia":"const","nivel":3,"enunciado":"As polícias civis, militares e penais estaduais e os corpos de bombeiros subordinam-se:","opcoes":["Aos Governadores","Ao Presidente da República","Ao Ministro da Justiça","Ao Tribunal de Justiça"],"explicacao":"Art. 144, § 6º."},{"id":546,"materia":"const","nivel":3,"enunciado":"Prevenir e reprimir o tráfico ilícito de entorpecentes, sem prejuízo da ação de outros órgãos, é atribuição constitucional da:","opcoes":["Polícia Federal","Polícia Rodoviária Federal","Guarda Municipal","Força Nacional"],"explicacao":"Art. 144, § 1º, II."},{"id":547,"materia":"const","nivel":4,"enunciado":"Segundo a Constituição, as guardas municipais destinam-se à:","opcoes":["Proteção dos bens, serviços e instalações do município","Apuração de crimes ocorridos no município","Polícia judiciária no âmbito municipal","Segurança dos presídios e cadeias públicas"],"explicacao":"Art. 144, § 8º."},{"id":548,"materia":"const","nivel":4,"enunciado":"Qual emenda constitucional incluiu a segurança viária no art. 144?","opcoes":["EC 82/2014","EC 45/2004","EC 104/2019","EC 19/1998"],"explicacao":"Ela acrescentou o § 10 ao art. 144."},{"id":549,"materia":"adm","nivel":2,"enunciado":"Na Lei nº 8.112/1990, a licença para tratar de interesses particulares é:","opcoes":["Sem remuneração, por até 3 anos","Remunerada, por até 1 ano","Remunerada, sem prazo","Obrigatória a cada 5 anos"],"explicacao":"Art. 91. Só para servidor que não esteja em estágio probatório."},{"id":550,"materia":"adm","nivel":2,"enunciado":"No ato discricionário, a Administração tem margem de escolha quanto à:","opcoes":["Conveniência e oportunidade","Competência","Finalidade pública","Forma prevista em lei"],"explicacao":"É o chamado mérito administrativo."},{"id":551,"materia":"adm","nivel":2,"enunciado":"É dever do servidor, pela Lei nº 8.112/1990:","opcoes":["Levar à autoridade superior as irregularidades de que souber","Recusar fé a documentos públicos apresentados","Manter sob sua chefia parentes até o 2º grau","Atuar como procurador junto a repartições"],"explicacao":"Art. 116, VI. As outras alternativas são proibições do art. 117."},{"id":552,"materia":"adm","nivel":3,"enunciado":"Na Lei nº 8.112/1990, vencimento é:","opcoes":["A retribuição pelo exercício do cargo, fixada em lei","O vencimento somado às vantagens permanentes","Qualquer gratificação eventual recebida","A indenização paga pelo transporte"],"explicacao":"Art. 40. Remuneração é o vencimento mais as vantagens pecuniárias permanentes (art. 41)."},{"id":553,"materia":"adm","nivel":3,"enunciado":"O deslocamento do servidor, a pedido ou de ofício, no mesmo quadro, com ou sem mudança de sede, é a:","opcoes":["Remoção","Redistribuição","Readaptação","Recondução"],"explicacao":"Art. 36 da Lei 8.112."},{"id":554,"materia":"adm","nivel":3,"enunciado":"Na Lei nº 8.112/1990, a redistribuição é o deslocamento de:","opcoes":["Cargo efetivo, ocupado ou vago, para outro órgão","Servidor para outro setor do mesmo órgão","Servidor aposentado de volta à atividade","Cargo em comissão para a iniciativa privada"],"explicacao":"Art. 37."},{"id":555,"materia":"adm","nivel":4,"enunciado":"Na Lei nº 8.112/1990, o processo disciplinar é conduzido por comissão composta de:","opcoes":["3 servidores estáveis","2 servidores quaisquer","5 servidores comissionados","1 servidor efetivo"],"explicacao":"Art. 149. O presidente deve ocupar cargo de nível igual ou superior ao do indiciado, ou ter escolaridade igual ou superior."},{"id":556,"materia":"pen","nivel":2,"enunciado":"O furto cometido com destruição ou rompimento de obstáculo é:","opcoes":["Furto qualificado","Roubo","Furto privilegiado","Dano"],"explicacao":"Art. 155, § 4º, I, do CP."},{"id":557,"materia":"pen","nivel":2,"enunciado":"O furto praticado durante o repouso noturno tem a pena aumentada de:","opcoes":["1/3","Metade","2/3","1/6"],"explicacao":"Art. 155, § 1º, do CP."},{"id":558,"materia":"pen","nivel":2,"enunciado":"No furto privilegiado, o juiz pode reduzir a pena quando:","opcoes":["O réu é primário e a coisa é de pequeno valor","O crime é cometido durante a noite","Há rompimento de obstáculo","O agente é reincidente, mas confessa"],"explicacao":"Art. 155, § 2º."},{"id":559,"materia":"pen","nivel":3,"enunciado":"Quando a violência é empregada logo após a subtração, para garantir a impunidade ou a posse da coisa, há:","opcoes":["Roubo impróprio","Furto qualificado","Extorsão","Roubo próprio"],"explicacao":"Art. 157, § 1º. No roubo próprio, a violência vem antes ou durante a subtração."},{"id":560,"materia":"pen","nivel":3,"enunciado":"No roubo com emprego de arma de fogo de uso permitido, a pena é aumentada de:","opcoes":["2/3","1/3","Metade","1/6"],"explicacao":"Art. 157, § 2º-A, I, incluído pela Lei 13.654/2018."},{"id":561,"materia":"pen","nivel":3,"enunciado":"No roubo com emprego de arma de fogo de uso restrito ou proibido, a pena é:","opcoes":["Aplicada em dobro","Aumentada de 1/3","Aumentada de 2/3","Reduzida pela metade"],"explicacao":"Art. 157, § 2º-B, incluído pelo Pacote Anticrime."},{"id":562,"materia":"pen","nivel":4,"enunciado":"Após o Pacote Anticrime, a ação penal no estelionato é, em regra:","opcoes":["Pública condicionada à representação","Pública incondicionada","Privada","Privada subsidiária"],"explicacao":"Art. 171, § 5º. É incondicionada quando a vítima é a Administração Pública, criança ou adolescente, pessoa com deficiência mental ou maior de 70 anos ou incapaz."},{"id":563,"materia":"pen","nivel":4,"enunciado":"Quem comete furto, sem violência, contra o cônjuge na constância da sociedade conjugal:","opcoes":["É isento de pena (escusa absolutória)","Tem a pena aumentada","Responde normalmente","Responde por crime hediondo"],"explicacao":"Art. 181, I, do CP. Não se aplica se a vítima tiver 60 anos ou mais (art. 183, III)."},{"id":564,"materia":"ppen","nivel":2,"enunciado":"No reconhecimento de pessoas, quem será reconhecido deve ser colocado, se possível:","opcoes":["Ao lado de pessoas parecidas com ela","Sozinha na sala de reconhecimento","De costas para a testemunha","Algemada, por segurança"],"explicacao":"Art. 226, II, do CPP."},{"id":565,"materia":"ppen","nivel":2,"enunciado":"A acareação é feita quando:","opcoes":["Há divergência entre declarações","O réu confessa o crime","A testemunha não comparece","A perícia é concluída"],"explicacao":"Art. 229 do CPP."},{"id":566,"materia":"ppen","nivel":2,"enunciado":"No processo penal, a regra é a citação:","opcoes":["Pessoal, por mandado","Por edital","Por telefone","Por e-mail"],"explicacao":"Art. 351 do CPP."},{"id":567,"materia":"ppen","nivel":3,"enunciado":"O laudo pericial deve ser elaborado no prazo máximo de:","opcoes":["10 dias, prorrogável em casos excepcionais","30 dias, prorrogável uma única vez","5 dias, improrrogável em qualquer caso","48 horas, contadas do exame"],"explicacao":"Art. 160, parágrafo único, do CPP."},{"id":568,"materia":"ppen","nivel":3,"enunciado":"Em regra, a autópsia deve ser feita pelo menos quanto tempo depois do óbito?","opcoes":["6 horas","24 horas","1 hora","12 horas"],"explicacao":"Art. 162 do CPP, salvo se os peritos atestarem a morte por sinais evidentes."},{"id":569,"materia":"ppen","nivel":3,"enunciado":"A busca domiciliar por mandado deve ser executada:","opcoes":["De dia, salvo se o morador consentir à noite","A qualquer hora, apresentado o mandado","Somente à noite, para surpreender o investigado","Somente com a presença do juiz que a autorizou"],"explicacao":"Art. 245 do CPP e art. 5º, XI, da CF."},{"id":570,"materia":"ppen","nivel":4,"enunciado":"Qual o prazo dos embargos de declaração no processo penal?","opcoes":["2 dias","5 dias","10 dias","15 dias"],"explicacao":"Art. 619 do CPP."},{"id":571,"materia":"ppen","nivel":4,"enunciado":"A carta testemunhável cabe contra a decisão que:","opcoes":["Denega o recurso ou impede seu seguimento","Recebe a denúncia oferecida pelo MP","Condena o réu em primeira instância","Decreta a prisão preventiva do réu"],"explicacao":"Art. 639 do CPP."},{"id":572,"materia":"leg","nivel":2,"enunciado":"Pela Lei de Crimes Ambientais, a pessoa jurídica:","opcoes":["Pode ser responsabilizada penalmente","Nunca responde penalmente","Responde só civilmente","Só responde se for pública"],"explicacao":"Art. 3º da Lei 9.605/98 e art. 225, § 3º, da CF."},{"id":573,"materia":"leg","nivel":2,"enunciado":"Pelo ECA, qual a idade mínima para adotar?","opcoes":["18 anos","21 anos","25 anos","30 anos"],"explicacao":"Art. 42. O adotante deve ser pelo menos 16 anos mais velho que o adotado."},{"id":574,"materia":"leg","nivel":2,"enunciado":"Pelo Estatuto da Pessoa Idosa, a gratuidade no transporte coletivo urbano é garantida a partir de:","opcoes":["65 anos","60 anos","70 anos","55 anos"],"explicacao":"Art. 39 da Lei 10.741/2003."},{"id":575,"materia":"leg","nivel":2,"enunciado":"Quem é flagrado com droga para consumo pessoal (art. 28 da Lei de Drogas):","opcoes":["Não é preso em flagrante; vai ao juízo ou assina compromisso","É preso em flagrante e fica preso até a audiência","Só é liberado após pagar fiança arbitrada pelo delegado","É levado ao presídio e responde por tráfico"],"explicacao":"Art. 48, § 2º, da Lei 11.343/2006."},{"id":576,"materia":"leg","nivel":3,"enunciado":"Na Lei Maria da Penha, a prisão preventiva do agressor pode ser decretada:","opcoes":["Em qualquer fase do inquérito ou da instrução","Apenas após a sentença","Apenas com flagrante","Somente se houver lesão grave"],"explicacao":"Art. 20 da Lei 11.340/2006."},{"id":577,"materia":"leg","nivel":3,"enunciado":"Após o Pacote Anticrime, qual o percentual para progressão do primário condenado por crime SEM violência ou grave ameaça (art. 112 da LEP)?","opcoes":["16%","25%","40%","1/6"],"explicacao":"Art. 112, I, da Lei 7.210/84."},{"id":578,"materia":"leg","nivel":3,"enunciado":"Após o Pacote Anticrime, o primário condenado por crime hediondo COM resultado morte progride ao cumprir:","opcoes":["50% da pena, vedado o livramento","40% da pena, com livramento","2/5 da pena, vedado o livramento","70% da pena, com livramento"],"explicacao":"Art. 112, VI, “a”, da LEP."},{"id":579,"materia":"leg","nivel":4,"enunciado":"Após o Pacote Anticrime, o primário condenado por crime hediondo SEM resultado morte progride ao cumprir:","opcoes":["40% da pena","50% da pena","60% da pena","16% da pena"],"explicacao":"Art. 112, V, da LEP."},{"id":580,"materia":"leg","nivel":4,"enunciado":"Após o Pacote Anticrime, o reincidente em crime hediondo com resultado morte progride ao cumprir:","opcoes":["70% da pena","60% da pena","50% da pena","3/5 da pena"],"explicacao":"Art. 112, VIII, da LEP. Também é vedado o livramento condicional."},{"id":581,"materia":"inf","nivel":2,"enunciado":"No Word, o recurso de revisão ortográfica serve para:","opcoes":["Apontar erros de ortografia e gramática","Inserir imagens e gráficos no texto","Criar tabelas a partir de listas","Proteger o documento com senha"],"explicacao":"As palavras com possível erro ficam sublinhadas."},{"id":582,"materia":"inf","nivel":2,"enunciado":"Fazer upload de um arquivo significa:","opcoes":["Enviá-lo do seu aparelho para a internet","Baixá-lo da internet para o seu aparelho","Apagá-lo definitivamente do servidor","Compactá-lo para ocupar menos espaço"],"explicacao":"Download é o caminho inverso."},{"id":583,"materia":"inf","nivel":2,"enunciado":"No Excel, qual o resultado de =MÍNIMO(4;2;8)?","opcoes":["2","4","8","14"],"explicacao":"MÍNIMO retorna o menor valor."},{"id":584,"materia":"inf","nivel":3,"enunciado":"Qual destes é um endereço IPv4 PRIVADO, usado em redes locais?","opcoes":["192.168.0.10","8.8.8.8","200.150.10.1","1.1.1.1"],"explicacao":"As faixas 10.x, 172.16 a 172.31 e 192.168.x são reservadas para redes privadas."},{"id":585,"materia":"inf","nivel":3,"enunciado":"Na navegação web, o código de erro 404 indica:","opcoes":["Página não encontrada","Acesso proibido","Erro interno do servidor","Redirecionamento"],"explicacao":"403 é acesso proibido; 500 é erro interno do servidor."},{"id":586,"materia":"inf","nivel":3,"enunciado":"Um software livre permite ao usuário:","opcoes":["Usar, estudar, modificar e redistribuir o programa","Apenas usar, sem ver o código","Usar só por 30 dias","Usar só em computadores do governo"],"explicacao":"São as quatro liberdades do software livre."},{"id":587,"materia":"inf","nivel":4,"enunciado":"Qual é a máscara de sub-rede padrão de uma rede classe C?","opcoes":["255.255.255.0","255.0.0.0","255.255.0.0","255.255.255.255"],"explicacao":"Classe A usa 255.0.0.0 e classe B, 255.255.0.0."},{"id":588,"materia":"inf","nivel":4,"enunciado":"Qual protocolo é usado para sincronizar o relógio dos computadores pela rede?","opcoes":["NTP","FTP","SNMP","DNS"],"explicacao":"Network Time Protocol."},{"id":589,"materia":"rl","nivel":2,"enunciado":"Quantos dias há em 3 semanas e 4 dias?","opcoes":["25","21","24","27"],"explicacao":"3 × 7 = 21; 21 + 4 = 25."},{"id":590,"materia":"rl","nivel":2,"enunciado":"Se 3 kg de um produto custam R$ 12,00, quanto custam 5 kg?","opcoes":["R$ 20,00","R$ 15,00","R$ 18,00","R$ 24,00"],"explicacao":"Cada quilo custa R$ 4,00. 5 × 4 = 20."},{"id":591,"materia":"rl","nivel":2,"enunciado":"A proposição “não P” é verdadeira quando:","opcoes":["P é falsa","P é verdadeira","P é verdadeira ou falsa","Nunca"],"explicacao":"A negação inverte o valor lógico."},{"id":592,"materia":"rl","nivel":3,"enunciado":"Dois aumentos sucessivos de 10% equivalem a um aumento único de:","opcoes":["21%","20%","11%","22%"],"explicacao":"1,1 × 1,1 = 1,21."},{"id":593,"materia":"rl","nivel":3,"enunciado":"Lançando um dado duas vezes, qual a probabilidade de NÃO sair nenhum 6?","opcoes":["25/36","1/36","11/36","5/6"],"explicacao":"5/6 × 5/6 = 25/36."},{"id":594,"materia":"rl","nivel":3,"enunciado":"Quantos números naturais de dois algarismos existem?","opcoes":["90","99","100","89"],"explicacao":"De 10 a 99: 99 − 10 + 1 = 90."},{"id":595,"materia":"rl","nivel":4,"enunciado":"Qual é a equivalente de “P ou Q”?","opcoes":["Se não P, então Q","Se P, então Q","Não P e não Q","P e Q"],"explicacao":"Se P não acontece, Q tem de acontecer para a disjunção ser verdadeira."},{"id":596,"materia":"rl","nivel":4,"enunciado":"Quantos triângulos podem ser formados com 7 pontos, sem três deles alinhados?","opcoes":["35","21","42","210"],"explicacao":"C(7,3) = 7 × 6 × 5 ÷ 6 = 35."},{"id":597,"materia":"dh","nivel":2,"enunciado":"O Estado prestará assistência jurídica integral e gratuita:","opcoes":["Aos que comprovarem insuficiência de recursos","A todos, sem exceção","Apenas aos servidores públicos","Apenas em processos criminais"],"explicacao":"Art. 5º, LXXIV."},{"id":598,"materia":"dh","nivel":2,"enunciado":"Segundo a Constituição, são gratuitas as ações de:","opcoes":["Habeas corpus e habeas data","Mandado de segurança e ação popular, sempre","Todas as ações cíveis","Indenização por danos morais"],"explicacao":"Art. 5º, LXXVII. A ação popular é isenta de custas, salvo má-fé."},{"id":599,"materia":"dh","nivel":2,"enunciado":"A garantia da razoável duração do processo foi incluída na Constituição pela:","opcoes":["EC 45/2004","EC 19/1998","EC 104/2019","EC 1/1992"],"explicacao":"Art. 5º, LXXVIII."},{"id":600,"materia":"dh","nivel":3,"enunciado":"A Lei nº 14.611/2023 trata da:","opcoes":["Igualdade salarial entre mulheres e homens","Proteção a refugiados e apátridas","Violência contra pessoas idosas","Abuso de autoridade por agentes públicos"],"explicacao":"Ela reforça a obrigação de remuneração igual para trabalho de igual valor."},{"id":601,"materia":"dh","nivel":3,"enunciado":"A Declaração e Programa de Ação de Viena (1993) afirmou que os direitos humanos são:","opcoes":["Universais, indivisíveis e interdependentes","Relativos, variando conforme cada cultura","Restritos aos direitos civis e políticos","Hierarquizados, com prioridade aos sociais"],"explicacao":"Fruto da Conferência Mundial sobre Direitos Humanos."},{"id":602,"materia":"dh","nivel":3,"enunciado":"A Convenção 169 da OIT trata dos direitos dos:","opcoes":["Povos indígenas e tribais","Trabalhadores domésticos","Refugiados","Idosos"],"explicacao":"Prevê, entre outros, o direito à consulta prévia, livre e informada."},{"id":603,"materia":"dh","nivel":4,"enunciado":"Quantos juízes compõem a Corte Interamericana de Direitos Humanos?","opcoes":["7","11","15","9"],"explicacao":"São eleitos pelos Estados Partes da Convenção Americana."},{"id":604,"materia":"dh","nivel":4,"enunciado":"Quantos membros compõem a Comissão Interamericana de Direitos Humanos?","opcoes":["7","11","5","9"],"explicacao":"Eles atuam a título pessoal, não como representantes dos países."},{"id":605,"materia":"est","nivel":2,"enunciado":"Qual a média ponderada das notas 6 (peso 1) e 9 (peso 2)?","opcoes":["8","7,5","7","9"],"explicacao":"(6 × 1 + 9 × 2) ÷ (1 + 2) = 24 ÷ 3 = 8."},{"id":606,"materia":"est","nivel":2,"enunciado":"A média de 5 números é 8. Qual a soma desses números?","opcoes":["40","13","8","45"],"explicacao":"Soma = média × quantidade = 8 × 5 = 40."},{"id":607,"materia":"est","nivel":2,"enunciado":"Somando 3 a todos os valores de um conjunto, a média:","opcoes":["Aumenta em 3","Não se altera","Triplica","Aumenta em 9"],"explicacao":"Somar uma constante desloca a média pelo mesmo valor."},{"id":608,"materia":"est","nivel":2,"enunciado":"Somando 3 a todos os valores de um conjunto, a variância:","opcoes":["Não se altera","Aumenta em 3","Aumenta em 9","Triplica"],"explicacao":"Todos se deslocam juntos, então a dispersão continua igual."},{"id":609,"materia":"est","nivel":2,"enunciado":"Multiplicando todos os valores por 2, o desvio padrão:","opcoes":["Dobra","Não se altera","Quadruplica","Cai pela metade"],"explicacao":"O desvio padrão é multiplicado pela mesma constante."},{"id":610,"materia":"est","nivel":2,"enunciado":"Multiplicando todos os valores por 2, a variância:","opcoes":["Quadruplica","Dobra","Não se altera","Cai pela metade"],"explicacao":"A variância é multiplicada pelo quadrado da constante: 2² = 4."},{"id":611,"materia":"est","nivel":2,"enunciado":"O desvio padrão é:","opcoes":["A raiz quadrada da variância","O quadrado da variância","A metade da amplitude","A média dos valores absolutos"],"explicacao":"Por isso ele fica na mesma unidade dos dados."},{"id":612,"materia":"est","nivel":2,"enunciado":"Qual medida é MENOS afetada por valores extremos?","opcoes":["Mediana","Média aritmética","Amplitude","Variância"],"explicacao":"A mediana depende só da posição central, não do tamanho dos extremos."},{"id":613,"materia":"est","nivel":2,"enunciado":"Qual a mediana de 7, 1, 9, 3, 5?","opcoes":["5","9","7","25"],"explicacao":"Primeiro ordene: 1, 3, 5, 7, 9. O valor central é 5. O 9 é o do meio só na lista desordenada."},{"id":614,"materia":"est","nivel":2,"enunciado":"No histograma, as barras representam:","opcoes":["Frequências de classes de valores","Valores individuais em ordem","Partes de um todo em graus","A relação entre duas variáveis"],"explicacao":"As barras ficam lado a lado, uma para cada intervalo de valores."},{"id":615,"materia":"est","nivel":2,"enunciado":"Um conjunto tem média 10 e desvio padrão 2. Qual o coeficiente de variação?","opcoes":["20%","5%","12%","8%"],"explicacao":"CV = desvio padrão ÷ média = 2 ÷ 10 = 20%."},{"id":616,"materia":"est","nivel":2,"enunciado":"A variável “grau de escolaridade” (fundamental, médio, superior) é qualitativa:","opcoes":["Ordinal","Nominal","Discreta","Contínua"],"explicacao":"As categorias têm uma ordem natural. Na nominal, como cor dos olhos, não há ordem."},{"id":617,"materia":"est","nivel":2,"enunciado":"Qual a variância populacional de 2, 4, 6 e 8?","opcoes":["5","20","4","2,5"],"explicacao":"Média 5. Desvios ao quadrado: 9, 1, 1, 9. Soma 20 ÷ 4 = 5."},{"id":618,"materia":"est","nivel":2,"enunciado":"Em uma distribuição simétrica, média, mediana e moda:","opcoes":["São iguais","São sempre diferentes","Somam zero","Têm a média maior"],"explicacao":"É o caso da distribuição normal."},{"id":619,"materia":"est","nivel":2,"enunciado":"Na amostragem aleatória simples, cada elemento da população:","opcoes":["Tem a mesma chance de ser escolhido","É escolhido por conveniência","É sorteado só dentro de grupos","É escolhido de k em k na lista"],"explicacao":"Por exemplo, um sorteio entre todos os nomes."},{"id":620,"materia":"est","nivel":2,"enunciado":"Escolher 1 elemento a cada 10 de uma lista é amostragem:","opcoes":["Sistemática","Estratificada","Por conglomerados","Por conveniência"],"explicacao":"Sorteia-se o ponto de partida e segue-se um intervalo fixo."},{"id":621,"materia":"est","nivel":2,"enunciado":"A frequência acumulada de uma classe indica:","opcoes":["A soma das frequências até ela","A frequência só da última classe","A frequência dividida pelo total","O número de classes da tabela"],"explicacao":"Somam-se as frequências desde a primeira classe até a classe em questão."},{"id":622,"materia":"est","nivel":2,"enunciado":"Qual a média de 2, 4, 4, 5, 10?","opcoes":["5","4","4,5","25"],"explicacao":"(2 + 4 + 4 + 5 + 10) ÷ 5 = 25 ÷ 5 = 5."},{"id":623,"materia":"est","nivel":2,"enunciado":"Qual a mediana de 3, 8, 1, 6?","opcoes":["4,5","7","3","6"],"explicacao":"Ordenando: 1, 3, 6, 8. A média dos centrais é (3 + 6) ÷ 2 = 4,5."},{"id":624,"materia":"est","nivel":2,"enunciado":"Notas 5, 7 e 9 com pesos 2, 1 e 1. Qual a média ponderada?","opcoes":["6,5","7","6","7,5"],"explicacao":"(5 × 2 + 7 + 9) ÷ 4 = 26 ÷ 4 = 6,5."},{"id":625,"materia":"est","nivel":2,"enunciado":"Num gráfico de setores, uma categoria com 25% do total ocupa um ângulo de:","opcoes":["90°","25°","45°","120°"],"explicacao":"25% de 360° = 90°."},{"id":626,"materia":"est","nivel":3,"enunciado":"Qual o desvio padrão populacional de 2, 4, 6 e 8?","opcoes":["√5","5","25","2,5"],"explicacao":"A variância populacional é 5; o desvio padrão é a raiz: √5 ≈ 2,24."},{"id":627,"materia":"est","nivel":3,"enunciado":"Numa distribuição com assimetria positiva (cauda à direita), em geral:","opcoes":["A média é maior que a mediana","A média é menor que a mediana","A moda é maior que a média","Média e mediana são iguais"],"explicacao":"Os valores altos da cauda puxam a média para cima. Ex.: distribuição de renda."},{"id":628,"materia":"est","nivel":3,"enunciado":"Na distribuição normal, cerca de quantos % dos dados ficam a até 1 desvio padrão da média?","opcoes":["68%","50%","95%","99,7%"],"explicacao":"Regra 68–95–99,7: 68% a 1 desvio, 95% a 2 e 99,7% a 3."},{"id":629,"materia":"est","nivel":3,"enunciado":"Na distribuição normal, cerca de quantos % dos dados ficam a até 2 desvios padrão da média?","opcoes":["95%","68%","99,7%","90%"],"explicacao":"Regra 68–95–99,7."},{"id":630,"materia":"est","nivel":3,"enunciado":"Um aluno tirou 80 numa prova com média 70 e desvio padrão 5. Qual o seu escore z?","opcoes":["2","10","1","0,5"],"explicacao":"z = (80 − 70) ÷ 5 = 2. Ele ficou 2 desvios padrão acima da média."},{"id":631,"materia":"est","nivel":3,"enunciado":"O primeiro quartil (Q1) é o valor que deixa abaixo dele:","opcoes":["25% dos dados","50% dos dados","75% dos dados","10% dos dados"],"explicacao":"Q2 é a mediana (50%) e Q3 deixa 75% abaixo."},{"id":632,"materia":"est","nivel":3,"enunciado":"A mediana corresponde ao:","opcoes":["Segundo quartil (Q2)","Primeiro quartil (Q1)","Terceiro quartil (Q3)","Décimo percentil"],"explicacao":"Também é o 5º decil e o 50º percentil."},{"id":633,"materia":"est","nivel":3,"enunciado":"A amplitude interquartil é calculada por:","opcoes":["Q3 − Q1","Q3 + Q1","Q2 − Q1","Máximo − mínimo"],"explicacao":"Mede a dispersão dos 50% centrais dos dados."},{"id":634,"materia":"est","nivel":3,"enunciado":"No boxplot, a linha dentro da caixa representa a:","opcoes":["Mediana","Média","Moda","Amplitude"],"explicacao":"As bordas da caixa são Q1 e Q3."},{"id":635,"materia":"est","nivel":3,"enunciado":"Um coeficiente de correlação de Pearson igual a −0,9 indica:","opcoes":["Forte relação linear negativa","Fraca relação linear negativa","Forte relação linear positiva","Ausência de qualquer relação"],"explicacao":"O sinal dá a direção; a proximidade de 1 em módulo dá a força."},{"id":636,"materia":"est","nivel":3,"enunciado":"O coeficiente de correlação de Pearson varia entre:","opcoes":["−1 e 1","0 e 1","0 e 100","−100 e 100"],"explicacao":"0 indica ausência de relação linear."},{"id":637,"materia":"est","nivel":3,"enunciado":"Na amostragem estratificada:","opcoes":["Divide-se a população em grupos e sorteia-se em cada um","Sorteiam-se grupos inteiros e pesquisam-se todos","Escolhem-se elementos de k em k numa lista","Escolhem-se os elementos mais fáceis de achar"],"explicacao":"Os estratos são grupos homogêneos, como faixa etária ou região."},{"id":638,"materia":"est","nivel":3,"enunciado":"Na amostragem por conglomerados:","opcoes":["Sorteiam-se grupos inteiros, como bairros","Divide-se em grupos e sorteia-se em cada um","Escolhem-se elementos de k em k numa lista","Escolhem-se os elementos mais fáceis de achar"],"explicacao":"Todos os elementos dos grupos sorteados são pesquisados."},{"id":639,"materia":"est","nivel":3,"enunciado":"Um valor fixo que descreve a população, como a média populacional, é um:","opcoes":["Parâmetro","Estimador","Rol","Quartil"],"explicacao":"Quando calculado na amostra, chama-se estatística ou estimativa."},{"id":640,"materia":"est","nivel":3,"enunciado":"Uma turma de 20 alunos tem média 6 e outra de 30 alunos tem média 8. Qual a média geral?","opcoes":["7,2","7","7,5","6,8"],"explicacao":"(20 × 6 + 30 × 8) ÷ 50 = 360 ÷ 50 = 7,2. Não basta tirar a média de 6 e 8."},{"id":641,"materia":"est","nivel":3,"enunciado":"A média de 10 números é 6. Retirando o número 15, qual a nova média?","opcoes":["5","6","4,5","5,5"],"explicacao":"A soma era 60. Sem o 15, fica 45 para 9 números: 45 ÷ 9 = 5."},{"id":642,"materia":"est","nivel":3,"enunciado":"Qual a variância de 5, 5, 5, 5?","opcoes":["0","5","1","25"],"explicacao":"Todos iguais: não há dispersão."},{"id":643,"materia":"est","nivel":3,"enunciado":"Qual medida permite comparar a dispersão de conjuntos com unidades diferentes?","opcoes":["Coeficiente de variação","Desvio padrão","Variância","Amplitude total"],"explicacao":"O CV é adimensional, expresso em porcentagem."},{"id":644,"materia":"est","nivel":3,"enunciado":"As classes 0–10, 10–20 e 20–30 têm frequências 5, 10 e 5. Qual o ponto médio da classe modal?","opcoes":["15","10","20","25"],"explicacao":"A classe modal é 10–20, a de maior frequência. Seu ponto médio é 15."},{"id":645,"materia":"est","nivel":3,"enunciado":"A curtose de uma distribuição mede seu grau de:","opcoes":["Achatamento","Assimetria","Tendência central","Correlação"],"explicacao":"Compara o achatamento da curva com o da distribuição normal."},{"id":646,"materia":"est","nivel":3,"enunciado":"A soma dos desvios em relação à média aritmética é sempre:","opcoes":["Zero","Igual à variância","Positiva","Igual ao desvio padrão"],"explicacao":"Os desvios positivos e negativos se anulam. Por isso a variância usa os quadrados."},{"id":647,"materia":"est","nivel":4,"enunciado":"Rejeitar a hipótese nula quando ela é verdadeira é o erro do:","opcoes":["Tipo I","Tipo II","Tipo III","Tipo amostral"],"explicacao":"Sua probabilidade é o nível de significância α."},{"id":648,"materia":"est","nivel":4,"enunciado":"Não rejeitar a hipótese nula quando ela é falsa é o erro do:","opcoes":["Tipo II","Tipo I","Tipo padrão","Tipo sistemático"],"explicacao":"Sua probabilidade é β; o poder do teste é 1 − β."},{"id":649,"materia":"est","nivel":4,"enunciado":"Um p-valor menor que o nível de significância leva a:","opcoes":["Rejeitar a hipótese nula","Aceitar a hipótese nula","Aumentar a amostra","Rejeitar a alternativa"],"explicacao":"Os dados seriam improváveis se a hipótese nula fosse verdadeira."},{"id":650,"materia":"est","nivel":4,"enunciado":"O nível de significância (α) de um teste é a probabilidade de:","opcoes":["Cometer o erro do tipo I","Cometer o erro do tipo II","A hipótese nula ser falsa","Obter um p-valor alto"],"explicacao":"É fixado antes do teste, geralmente em 5%."},{"id":651,"materia":"est","nivel":4,"enunciado":"Mantidas as demais condições, aumentar o tamanho da amostra faz o intervalo de confiança:","opcoes":["Ficar mais estreito","Ficar mais largo","Não mudar","Perder a confiança"],"explicacao":"O erro padrão diminui com o aumento de n."},{"id":652,"materia":"est","nivel":4,"enunciado":"Mantida a amostra, aumentar o nível de confiança de 95% para 99% faz o intervalo:","opcoes":["Ficar mais largo","Ficar mais estreito","Não mudar","Mudar de centro"],"explicacao":"Mais confiança exige uma margem maior."},{"id":653,"materia":"est","nivel":4,"enunciado":"Para reduzir pela metade o erro padrão da média, o tamanho da amostra deve ser multiplicado por:","opcoes":["4","2","8","√2"],"explicacao":"O erro padrão é σ ÷ √n. Para dividir por 2, √n precisa dobrar, então n quadruplica."},{"id":654,"materia":"est","nivel":4,"enunciado":"Qual o erro padrão da média para σ = 10 e n = 25?","opcoes":["2","0,4","5","10"],"explicacao":"σ ÷ √n = 10 ÷ 5 = 2."},{"id":655,"materia":"est","nivel":4,"enunciado":"Numa binomial com n = 10 e p = 0,3, qual o valor esperado?","opcoes":["3","0,3","7","2,1"],"explicacao":"Média = n × p = 10 × 0,3 = 3."},{"id":656,"materia":"est","nivel":4,"enunciado":"Numa binomial com n = 10 e p = 0,3, qual a variância?","opcoes":["2,1","3","0,21","7"],"explicacao":"Variância = n × p × (1 − p) = 10 × 0,3 × 0,7 = 2,1."},{"id":657,"materia":"est","nivel":4,"enunciado":"Qual a média geométrica de 2 e 8?","opcoes":["4","5","10","16"],"explicacao":"√(2 × 8) = √16 = 4."},{"id":658,"materia":"est","nivel":4,"enunciado":"Qual a média harmônica de 2 e 6?","opcoes":["3","4","8","2,5"],"explicacao":"2 ÷ (1/2 + 1/6) = 2 ÷ (4/6) = 3."},{"id":659,"materia":"est","nivel":4,"enunciado":"Um carro vai a 60 km/h e volta pelo mesmo trajeto a 40 km/h. Qual a velocidade média da viagem?","opcoes":["48 km/h","50 km/h","45 km/h","52 km/h"],"explicacao":"Com distâncias iguais, usa-se a média harmônica: 2 × 60 × 40 ÷ 100 = 48. A média simples, 50, está errada."},{"id":660,"materia":"est","nivel":4,"enunciado":"Na variância amostral, a soma dos quadrados dos desvios é dividida por:","opcoes":["n − 1","n","n + 1","n²"],"explicacao":"O n − 1 corrige o viés da estimativa. Na variância populacional, divide-se por n."},{"id":661,"materia":"est","nivel":4,"enunciado":"Qual a variância amostral de 2, 4 e 6?","opcoes":["4","2,67","8","2"],"explicacao":"Média 4. Desvios ao quadrado: 4, 0, 4. Soma 8 ÷ (3 − 1) = 4."},{"id":662,"materia":"est","nivel":4,"enunciado":"Se X tem média 5 e Y = 2X + 3, qual a média de Y?","opcoes":["13","10","8","16"],"explicacao":"E(Y) = 2 × 5 + 3 = 13."},{"id":663,"materia":"est","nivel":4,"enunciado":"Se X tem variância 4 e Y = 3X − 1, qual a variância de Y?","opcoes":["36","12","11","35"],"explicacao":"Var(Y) = 3² × 4 = 36. A constante −1 não altera a variância."},{"id":664,"materia":"est","nivel":4,"enunciado":"Lançando uma moeda honesta 4 vezes, qual a probabilidade de saírem exatamente 2 caras?","opcoes":["3/8","1/2","1/4","1/8"],"explicacao":"C(4,2) ÷ 2⁴ = 6 ÷ 16 = 3/8."},{"id":665,"materia":"est","nivel":4,"enunciado":"Na normal padrão, qual a probabilidade de Z ser maior que 0?","opcoes":["50%","68%","95%","0%"],"explicacao":"A curva é simétrica em torno de 0."},{"id":666,"materia":"est","nivel":4,"enunciado":"Numa regressão linear simples com R² = 0,81, a correlação, em módulo, é:","opcoes":["0,9","0,81","0,66","0,19"],"explicacao":"R² é o quadrado da correlação: √0,81 = 0,9."},{"id":667,"materia":"est","nivel":4,"enunciado":"Na reta de regressão y = 2 + 3x, se x aumenta 1 unidade, y:","opcoes":["Aumenta 3","Aumenta 2","Aumenta 5","Triplica"],"explicacao":"O coeficiente angular, 3, é a variação de y para cada unidade de x."},{"id":668,"materia":"cont","nivel":2,"enunciado":"Pelo regime de competência, a receita é reconhecida quando:","opcoes":["É ganha, mesmo sem recebimento","O dinheiro entra no caixa","O cliente assina o contrato","O balanço anual é publicado"],"explicacao":"Competência considera o fato gerador, e não o pagamento ou o recebimento."},{"id":669,"materia":"cont","nivel":2,"enunciado":"Pelo regime de caixa, a despesa é reconhecida quando:","opcoes":["É paga","Ocorre o fato gerador","É contratada","O serviço é prestado"],"explicacao":"O regime de caixa considera só a entrada e a saída de dinheiro."},{"id":670,"materia":"cont","nivel":2,"enunciado":"No Balanço Patrimonial, o ativo é dividido em:","opcoes":["Circulante e não circulante","Exigível e não exigível","Fixo e variável","Operacional e financeiro"],"explicacao":"Classificação da Lei 6.404/1976."},{"id":671,"materia":"cont","nivel":2,"enunciado":"Pela Lei 6.404/1976, o ativo circulante reúne os direitos realizáveis:","opcoes":["Até o fim do exercício seguinte","Em mais de cinco exercícios","Apenas dentro do mesmo mês","Somente após a liquidação"],"explicacao":"Art. 179, I. O que vence depois disso vai para o realizável a longo prazo."},{"id":672,"materia":"cont","nivel":2,"enunciado":"Máquinas e veículos usados nas atividades da empresa ficam no:","opcoes":["Imobilizado","Ativo circulante","Intangível","Passivo não circulante"],"explicacao":"São bens corpóreos destinados à manutenção das atividades."},{"id":673,"materia":"cont","nivel":2,"enunciado":"Marcas, patentes e softwares adquiridos ficam no:","opcoes":["Intangível","Imobilizado","Estoque","Investimentos"],"explicacao":"São bens incorpóreos."},{"id":674,"materia":"cont","nivel":2,"enunciado":"A perda de valor de um bem do imobilizado pelo uso ou desgaste é a:","opcoes":["Depreciação","Amortização","Exaustão","Provisão"],"explicacao":"Amortização é para intangíveis; exaustão, para recursos naturais."},{"id":675,"materia":"cont","nivel":2,"enunciado":"A redução do valor de recursos naturais, como minas e florestas, é a:","opcoes":["Exaustão","Depreciação","Amortização","Provisão"],"explicacao":"Acompanha a extração do recurso."},{"id":676,"materia":"cont","nivel":2,"enunciado":"A redução de valor de um ativo intangível com vida útil definida é a:","opcoes":["Amortização","Depreciação","Exaustão","Provisão"],"explicacao":"Intangível com vida útil indefinida não é amortizado; é testado por impairment."},{"id":677,"materia":"cont","nivel":2,"enunciado":"Uma máquina custou R$ 50.000 e tem vida útil de 10 anos, sem valor residual. Qual a depreciação anual linear?","opcoes":["R$ 5.000","R$ 10.000","R$ 500","R$ 50.000"],"explicacao":"50.000 ÷ 10 = 5.000 por ano."},{"id":678,"materia":"cont","nivel":2,"enunciado":"Depreciação acumulada é uma conta:","opcoes":["Retificadora do ativo","Do passivo circulante","De receita","Do patrimônio líquido"],"explicacao":"Tem saldo credor e reduz o valor do imobilizado no balanço."},{"id":679,"materia":"cont","nivel":2,"enunciado":"Qual a fórmula do custo das mercadorias vendidas (CMV)?","opcoes":["EI + Compras − EF","EI − Compras + EF","Vendas − EF","Compras + EF − EI"],"explicacao":"Estoque inicial mais compras menos estoque final."},{"id":680,"materia":"cont","nivel":2,"enunciado":"Estoque inicial R$ 10.000, compras R$ 30.000 e estoque final R$ 15.000. Qual o CMV?","opcoes":["R$ 25.000","R$ 55.000","R$ 35.000","R$ 5.000"],"explicacao":"10.000 + 30.000 − 15.000 = 25.000."},{"id":681,"materia":"cont","nivel":2,"enunciado":"Vendas de R$ 80.000 e CMV de R$ 50.000 geram um lucro bruto de:","opcoes":["R$ 30.000","R$ 130.000","R$ 50.000","R$ 80.000"],"explicacao":"Lucro bruto = receita líquida − CMV."},{"id":682,"materia":"cont","nivel":2,"enunciado":"Qual demonstração mostra as receitas, as despesas e o lucro ou prejuízo do período?","opcoes":["DRE","Balanço Patrimonial","DFC","DMPL"],"explicacao":"Demonstração do Resultado do Exercício."},{"id":683,"materia":"cont","nivel":2,"enunciado":"Qual demonstração mostra a posição do patrimônio numa data?","opcoes":["Balanço Patrimonial","Demonstração do Resultado","Fluxo de Caixa","Valor Adicionado"],"explicacao":"É uma “fotografia” do ativo, do passivo e do PL naquela data."},{"id":684,"materia":"cont","nivel":2,"enunciado":"A compra de mercadorias à vista é um fato:","opcoes":["Permutativo","Modificativo aumentativo","Modificativo diminutivo","Misto"],"explicacao":"Troca-se caixa por estoque e o PL não muda."},{"id":685,"materia":"cont","nivel":2,"enunciado":"O pagamento do aluguel do mês é um fato:","opcoes":["Modificativo diminutivo","Permutativo","Modificativo aumentativo","Misto aumentativo"],"explicacao":"Reduz o caixa e gera despesa, o que diminui o PL."},{"id":686,"materia":"cont","nivel":2,"enunciado":"O recebimento de uma duplicata com juros é um fato:","opcoes":["Misto aumentativo","Permutativo","Modificativo diminutivo","Misto diminutivo"],"explicacao":"Há troca (duplicata por caixa) e há receita (juros), que aumenta o PL."},{"id":687,"materia":"cont","nivel":2,"enunciado":"Na compra de mercadorias a prazo, o lançamento é:","opcoes":["Débito em Estoques e crédito em Fornecedores","Débito em Fornecedores e crédito em Estoques","Débito em Caixa e crédito em Estoques","Débito em Estoques e crédito em Caixa"],"explicacao":"O ativo (estoque) aumenta a débito; a obrigação (fornecedores) aumenta a crédito."},{"id":688,"materia":"cont","nivel":2,"enunciado":"Valor recebido antes de entregar o produto ou serviço é registrado no passivo como:","opcoes":["Adiantamento de clientes","Receita do período","Despesa antecipada","Capital a integralizar"],"explicacao":"Também é chamado de receita antecipada ou diferida. Vira receita quando a empresa cumpre a obrigação."},{"id":689,"materia":"cont","nivel":3,"enunciado":"Pela Lei 6.404/1976, o ativo não circulante se divide em:","opcoes":["Realizável a LP, investimentos, imobilizado e intangível","Disponível, estoques, clientes e despesas antecipadas","Capital, reservas, ajustes e prejuízos","Fornecedores, salários, impostos e empréstimos"],"explicacao":"Art. 178, § 1º, II."},{"id":690,"materia":"cont","nivel":3,"enunciado":"Participações permanentes em outras empresas são classificadas em:","opcoes":["Investimentos","Imobilizado","Ativo circulante","Intangível"],"explicacao":"Ficam no ativo não circulante."},{"id":691,"materia":"cont","nivel":3,"enunciado":"Um terreno mantido para valorização, sem uso nas atividades, fica em:","opcoes":["Investimentos","Imobilizado","Estoques","Intangível"],"explicacao":"É propriedade para investimento. Se fosse usado na operação, iria para o imobilizado."},{"id":692,"materia":"cont","nivel":3,"enunciado":"Terrenos usados nas atividades da empresa:","opcoes":["Não sofrem depreciação","Depreciam 4% ao ano","Sofrem exaustão","Sofrem amortização"],"explicacao":"Em regra, terrenos têm vida útil indefinida. Os edifícios sobre eles depreciam."},{"id":693,"materia":"cont","nivel":3,"enunciado":"Pelo CPC 16, qual método de avaliação de estoques NÃO é permitido?","opcoes":["UEPS","PEPS","Custo médio ponderado","Custo específico"],"explicacao":"O UEPS (último a entrar, primeiro a sair) é vedado. A legislação do IR também não o aceita."},{"id":694,"materia":"cont","nivel":3,"enunciado":"Com preços subindo, o PEPS resulta em:","opcoes":["Estoque final maior e lucro maior","Estoque final menor e lucro menor","CMV maior e lucro menor","Mesmo resultado do custo médio"],"explicacao":"Saem primeiro os itens mais baratos, então o CMV fica menor e o estoque final fica com os preços mais altos."},{"id":695,"materia":"cont","nivel":3,"enunciado":"Compras: 10 un. a R$ 5 e depois 10 un. a R$ 7. Foram vendidas 12 unidades. Pelo PEPS, qual o CMV?","opcoes":["R$ 64","R$ 72","R$ 80","R$ 84"],"explicacao":"Saem primeiro as 10 a R$ 5 (R$ 50) e mais 2 a R$ 7 (R$ 14): total R$ 64."},{"id":696,"materia":"cont","nivel":3,"enunciado":"Compras: 10 un. a R$ 5 e 10 un. a R$ 7. Vendidas 12. Pelo custo médio ponderado, qual o CMV?","opcoes":["R$ 72","R$ 64","R$ 80","R$ 60"],"explicacao":"Custo médio = (50 + 70) ÷ 20 = R$ 6. 12 × 6 = R$ 72."},{"id":697,"materia":"cont","nivel":3,"enunciado":"O índice de liquidez corrente é:","opcoes":["Ativo circulante ÷ passivo circulante","Disponível ÷ passivo circulante","(AC − estoques) ÷ passivo circulante","Passivo circulante ÷ ativo total"],"explicacao":"Acima de 1 indica que o AC cobre as dívidas de curto prazo."},{"id":698,"materia":"cont","nivel":3,"enunciado":"AC R$ 200 mil, estoques R$ 50 mil e PC R$ 100 mil. Qual a liquidez seca?","opcoes":["1,5","2,0","0,5","2,5"],"explicacao":"(200 − 50) ÷ 100 = 1,5. A liquidez corrente seria 2,0."},{"id":699,"materia":"cont","nivel":3,"enunciado":"A liquidez imediata considera, no numerador, apenas:","opcoes":["As disponibilidades","Os estoques","Todo o ativo","O realizável a LP"],"explicacao":"Disponível ÷ passivo circulante."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;
